package com.ascent.climb.data.i18n

/**
 * English question bank, part C. Split again once part B outgrew the compiler.
 * [PACK_EN_QUIZ] in PackEnQuiz2.kt joins A, B and C.
 */
internal val PACK_EN_QUIZ_C: Map<String, String> = mapOf(

    "q.m03#10.e" to "60 m, about 70 paces, is the usual sanitary distance, for waste, washing and dishes.",
    "q.m03#11.p" to "What is the right attitude to fires in the backcountry?",
    "q.m03#11.o0" to "Use a stove first; if a fire is genuinely needed, use an existing ring and put it out completely",
    "q.m03#11.o1" to "A fire is more atmospheric",
    "q.m03#11.o2" to "As long as it does not start a wildfire",
    "q.m03#11.o3" to "Fire keeps animals away",
    "q.m03#11.e" to "Fire scars last for years and encourage the next person to burn in the same spot. In a dry season a spark can be a real disaster.",
    "q.m03#12.p" to "What is the reasonable approach to wildlife?",
    "q.m03#12.o0" to "Keep your distance, do not feed, back away slowly, do not chase a photo",
    "q.m03#12.o1" to "Get close for a photo",
    "q.m03#12.o2" to "Feed it to calm it",
    "q.m03#12.o3" to "Shout to drive it off",
    "q.m03#12.e" to "Feeding changes animal behaviour and raises the risk of conflict. Keeping distance protects both of you.",
    "q.m04#10.p" to "When reading a forecast, what matters more than the chance of precipitation?",
    "q.m04#10.o0" to "Wind speed, temperature, and whether precipitation falls as rain or snow with height",
    "q.m04#10.o1" to "Only the precipitation chance",
    "q.m04#10.o2" to "Only the maximum temperature",
    "q.m04#10.o3" to "Only humidity",
    "q.m04#10.e" to "The same amount of precipitation means very different things as rain or snow. Wind decides how it feels and whether you can move; temperature decides the kit.",
    "q.m04#11.p" to "What is the common afternoon weather pattern in the mountains?",
    "q.m04#11.o0" to "Cloud builds, convection develops, and the chance of thunderstorms and showers rises",
    "q.m04#11.o1" to "It stays clear",
    "q.m04#11.o2" to "Wind drops",
    "q.m04#11.o3" to "Temperature falls fastest",
    "q.m04#11.e" to "That is where the rule about starting in the morning and leaving exposed terrain by afternoon comes from. Plan around that rhythm.",
    "q.m04#12.p" to "Using the lapse rate to estimate the snowline, how much does it drop per 1,000 m?",
    "q.m04#12.o0" to "6.5 °C",
    "q.m04#12.o1" to "2 °C",
    "q.m04#12.o2" to "10 °C",
    "q.m04#12.o3" to "15 °C",
    "q.m04#12.e" to "6.5 °C per 1,000 m is the average. It lets you estimate the freezing level roughly, which tells you rain or snow.",
    "q.m05#10.p" to "Why does the season window matter for introductory snow peaks?",
    "q.m05#10.o0" to "Snow conditions, wind and permit policy differ a lot by season, and missing the window doubles the difficulty",
    "q.m05#10.o1" to "Because of ticket prices",
    "q.m05#10.o2" to "Because of crowds",
    "q.m05#10.o3" to "Because of daylight",
    "q.m05#10.e" to "The same mountain is two different objectives either side of the monsoon. Choose the season first, then the route.",
    "q.m05#11.p" to "When choosing a first snow peak, what does needing technical skills mean?",
    "q.m05#11.o0" to "Whether roping up, belaying and travelling over crevasses are required",
    "q.m05#11.o1" to "Whether there is an entry fee",
    "q.m05#11.o2" to "Whether a guide is required",
    "q.m05#11.o3" to "Whether you need a tent",
    "q.m05#11.e" to "That is the core difference between a trekking peak and a technical one. For a first snow peak, prefer a route that needs no technical skills.",
    "q.m05#12.p" to "What is the right way to read a summit success rate?",
    "q.m05#12.o0" to "It reflects the weather window and the difficulty, but the basis of the statistics varies a lot between years",
    "q.m05#12.o1" to "Higher is always better",
    "q.m05#12.o2" to "Lower is always safer",
    "q.m05#12.o3" to "It has no value",
    "q.m05#12.e" to "A success rate is information, not a promise. Read the year, the season, and whether commercial assistance is included.",
    "q.m25#12.p" to "After a retreat, what is the most useful debrief?",
    "q.m25#12.o0" to "Go back over the information behind the decision: what was ignored, and where an earlier call was possible",
    "q.m25#12.o1" to "Record the conclusion only",
    "q.m25#12.o2" to "Attribute it to luck",
    "q.m25#12.o3" to "Never mention it again",
    "q.m25#12.e" to "The point is not blame but turning we would catch it earlier next time into something concrete. A written timeline beats a description of feelings.",
    "q.m06#10.p" to "In the three systems of technical climbing, what does protection mean?",
    "q.m06#10.o0" to "Catching a fall with anchors and rope",
    "q.m06#10.o1" to "Walking",
    "q.m06#10.o2" to "Climbing movement",
    "q.m06#10.o3" to "Buying gear",
    "q.m06#10.e" to "Movement, protection and belaying form a closed loop: you can move, protect yourself, and protect someone else. Missing any one of them is not technical climbing.",
    "q.m06#11.p" to "Why do technical courses usually teach arrest before climbing?",
    "q.m06#11.o0" to "Because sliding falls are the most frequent danger, and arresting is the baseline skill",
    "q.m06#11.o1" to "Because climbing is harder",
    "q.m06#11.o2" to "Because of the order gear is bought",
    "q.m06#11.o3" to "Because the textbook says so",
    "q.m06#11.e" to "Being able to climb but not to stop multiplies the risk. Arresting, roping up and belaying are the skills you never use until something goes wrong, so they have to become muscle memory first.",
    "q.m06#12.p" to "What is the value of repeated simulation on safe ground?",
    "q.m06#12.o0" to "It turns the movement into a reflex that needs no thought, leaving attention free to judge the real situation",
    "q.m06#12.o1" to "It passes the time",
    "q.m06#12.o2" to "It makes good photos",
    "q.m06#12.o3" to "It teaches gear prices",
    "q.m06#12.e" to "In the real environment attention is consumed by weather, fatigue and fear. Only movements you can do without thinking come out at the critical moment.",
    "q.m07#12.p" to "Which way should a carabiner gate face?",
    "q.m07#12.o0" to "Away from the rock, clear of friction and the load direction, so rope or rock cannot lever it open",
    "q.m07#12.o1" to "Up",
    "q.m07#12.o2" to "Down",
    "q.m07#12.o3" to "Any way",
    "q.m07#12.e" to "A gate levered open by an outside force is a real failure mode. Choose the direction wrong and you have handed reliability to luck.",
    "q.m07#13.p" to "Why should webbing not run over a sharp rock edge when linking two anchors?",
    "q.m07#13.o0" to "A sharp edge nicks the webbing and sharply reduces its strength under load",
    "q.m07#13.o1" to "Because it looks bad",
    "q.m07#13.o2" to "Because it slips",
    "q.m07#13.o3" to "Because it is too short",
    "q.m07#13.e" to "A small nick in webbing can halve its strength. Pad the edge or extend with chain instead.",
    "q.m07#14.p" to "What is the usual angle for an ice screw?",
    "q.m07#14.o0" to "Slightly upward, about 10–15°, opposing the load direction",
    "q.m07#14.o1" to "Perfectly horizontal",
    "q.m07#14.o2" to "Angled down",
    "q.m07#14.o3" to "Any angle",
    "q.m07#14.e" to "A slight upward angle follows the load and presses the screw into the ice rather than pulling it out. In poor ice, go longer and more angled.",
    "q.m07#15.p" to "What should you do when a belay has only a single anchor?",
    "q.m07#15.o0" to "Add an independent back-up, or move to more reliable ground",
    "q.m07#15.o1" to "Use it as it is",
    "q.m07#15.o2" to "Add more carabiners",
    "q.m07#15.o3" to "Shorten the rope",
    "q.m07#15.e" to "More carabiners are not redundancy. Redundancy requires different failure modes.",
    "q.m08#12.p" to "For 5,000 m peaks such as Gangshika and Haba, what needs planning first?",
    "q.m08#12.o0" to "Acclimatisation pace and the weather window, not the technical difficulty",
    "q.m08#12.o1" to "Buying gear",
    "q.m08#12.o2" to "Photo spots",
    "q.m08#12.o3" to "Dividing tasks among partners",
    "q.m08#12.e" to "At 5,000 m the difficulty is usually altitude and weather, not technique. Time spent acclimatising pays better than one more move practised.",
    "q.m08#13.p" to "What is the right approach to permits and guide requirements?",
    "q.m08#13.o0" to "Confirm local rules in advance and follow guide or registration requirements exactly",
    "q.m08#13.o1" to "Ask when you arrive",
    "q.m08#13.o2" to "Bypass the checkpoint",
    "q.m08#13.o3" to "Get a friend to smooth it over",
    "q.m08#13.e" to "Many 5,000 m peaks require registration or a guide. Climbing without a permit voids both rescue and insurance.",
    "q.m08#14.p" to "What is the logic of a progression such as satellite peak, then main summit?",
    "q.m08#14.o0" to "Validate acclimatisation and fitness on an easier route, then add the technical difficulty",
    "q.m08#14.o1" to "Because it is cheap",
    "q.m08#14.o2" to "Because it is close",
    "q.m08#14.o3" to "Because it is crowded",
    "q.m08#14.e" to "Progression means adding one variable at a time. Raise altitude and technical difficulty together and you cannot tell which one caused the problem.",
    "q.m08#15.p" to "What retreat information must be confirmed before departure?",
    "q.m08#15.o0" to "The descent route, back-up camp locations, the nearest medical point and contact details",
    "q.m08#15.o1" to "Only the descent route",
    "q.m08#15.o2" to "Only the medical point",
    "q.m08#15.o3" to "None of it",
    "q.m08#15.e" to "Retreat is not simply walking back. When the weather turns, the nearest back-up camp may be the only viable option.",
    "q.l23#0.p" to "When putting an equipment list together, which category should you confirm first?",
    "q.l23#0.o0" to "Warmth and protection, plus technical gear",
    "q.l23#0.o1" to "Camera and power bank",
    "q.l23#0.o2" to "Snacks and condiments",
    "q.l23#0.o3" to "Spare clean clothes",
    "q.l23#0.e" to "The order of the list decides what you will be missing in bad weather. Warmth, protection and technical gear belong to the 'without it something goes wrong' category; a missing comfort item only makes you uncomfortable.",
    "q.l23#1.p" to "What capacities are usually chosen for a summit pack and a duffel?",
    "q.l23#1.o0" to "35–50 L / 90–120 L",
    "q.l23#1.o1" to "20–30 L / 50–60 L",
    "q.l23#1.o2" to "60–70 L / 60 L",
    "q.l23#1.o3" to "The bigger the better",
    "q.l23#1.e" to "The summit pack carries one day's worth: insulation layer, action food, water, headlamp, small first-aid kit. Big luggage goes to the porters; don't carry it up to high camp.",
    "q.l23#2.p" to "Where should heavy items sit in a pack?",
    "q.l23#2.o0" to "Against your back, between the shoulder blades (upper middle of the back)",
    "q.l23#2.o1" to "At the very bottom",
    "q.l23#2.o2" to "On the outside",
    "q.l23#2.o3" to "Wherever it is quick to reach",
    "q.l23#2.e" to "Heavy items ride high and close to the back, so the centre of gravity stays near the body and above the hips and you walk steadily. Weight at the bottom makes the pack sag and loads the hipbelt unevenly; hours later your lower back hurts.",
    "q.l23#3.p" to "Where is a pack's weight mainly carried?",
    "q.l23#3.o0" to "The hipbelt (about 60–70%); the shoulder straps mainly hold the pack against your body",
    "q.l23#3.o1" to "The shoulder straps",
    "q.l23#3.o2" to "The chest",
    "q.l23#3.o3" to "A sling around the neck",
    "q.l23#3.e" to "The hipbelt transfers load to the pelvis, the part of the body best built to carry it. If your shoulders ache after a short stretch, the hipbelt is usually too loose or sitting too high.",
    "q.l23#4.p" to "On summit day, what share of body weight should the pack stay within?",
    "q.l23#4.o0" to "15–20%",
    "q.l23#4.o1" to "30–35%",
    "q.l23#4.o2" to "40%",
    "q.l23#4.o3" to "There is no limit",
    "q.l23#4.e" to "For a 60 kg climber that is roughly 9–12 kg. Above that, the oxygen cost of climbing and the risk of losing balance both rise noticeably.",
    "q.l23#5.p" to "Which approach to waterproofing is correct?",
    "q.l23#5.o0" to "Sleeping bag and down jacket each in their own dry bag, with electronics and medication in another layer",
    "q.l23#5.o1" to "The pack itself is waterproof, so no inner bags are needed",
    "q.l23#5.o2" to "One big bag for everything",
    "q.l23#5.o3" to "A bin liner over the outside of the pack is enough",
    "q.l23#5.e" to "Water seeps through the seams. Layered waterproofing means that even if the outer layer floods, the core stays dry, and one split bag does not sink everything.",
    "q.l23#6.p" to "Which three items are easiest to forget before departure and most dangerous to be without?",
    "q.l23#6.o0" to "Headlamp with spare batteries, spare gloves, first-aid kit",
    "q.l23#6.o1" to "Sunglasses, sunscreen, lip balm",
    "q.l23#6.o2" to "Water bottle, lunch box, chopsticks",
    "q.l23#6.o3" to "Camera, tripod, spare memory card",
    "q.l23#6.e" to "The first two cover the two most frequent scenarios: not making it back to camp before dark, and wet gloves. The last is the thing everyone assumes someone else is carrying.",
    "q.l23#7.p" to "Which of these weights can be left behind at high camp?",
    "q.l23#7.o0" to "Spare camera and tripod",
    "q.l23#7.o1" to "A third set of clothes",
    "q.l23#7.o2" to "Headlamp and spare batteries",
    "q.l23#7.o3" to "First-aid kit",
    "q.l23#7.e" to "Cut weight where it does not affect safety. Headlamp, first-aid kit and insulation layer are non-negotiable; camera and spare clothes are experience items.",
    "q.l23#8.p" to "What makes an equipment list actually usable?",
    "q.l23#8.o0" to "Grouped by situation of use, not by order of purchase",
    "q.l23#8.o1" to "Essentials and optional items marked",
    "q.l23#8.o2" to "Variants for season and altitude band",
    "q.l23#8.o3" to "The longer the better",
    "q.l23#8.e" to "A list earns its keep when you can follow it under pressure. Grouping by situation, marking essentials, and adjusting for altitude are what make it usable; length only makes people stop using it.",
    "q.l23#9.p" to "Put the packing sequence into the correct order.",
    "q.l23#9.o0" to "Sleeping bag and down jacket into a dry bag, at the bottom",
    "q.l23#9.o1" to "Heavy items (water, stove, technical gear) against the back in the upper middle",
    "q.l23#9.o2" to "The day's insulation layer and action food at the top",
    "q.l23#9.o3" to "Headlamp and first-aid kit in the lid or a side pocket, within reach",
    "q.l23#9.e" to "First what you will not need but must carry, then the heavy items, last what you reach for constantly. Headlamp and first-aid kit must come out without unpacking.",
    "q.l23#10.p" to "What is the correct order for checking a loaded pack?",
    "q.l23#10.o0" to "Fasten and tighten the hipbelt",
    "q.l23#10.o1" to "Adjust the shoulder straps to fit",
    "q.l23#10.o2" to "Clip the sternum strap",
    "q.l23#10.o3" to "Stand up, walk a few steps, confirm it does not sway",
    "q.l23#10.e" to "Reverse the order and the weight ends up on your shoulders: hipbelt first to set the position, then the shoulder straps, the sternum strap only stops them sliding outward, and finally you must walk to verify.",
    "q.l23#11.p" to "A summit pack is usually 35–50 L; a duffel is usually ______ L.",
    "q.l23#11.a0" to "90–120",
    "q.l23#11.a1" to "90-120",
    "q.l23#11.a2" to "90~120",
    "q.l23#11.e" to "The duffel moves bulky gear from the road to camp and has to hold sleeping bag, down jacket, boots and technical gear, hence 90–120 L.",
    "q.l23#12.p" to "The hipbelt carries roughly ______ % of pack weight (give one number).",
    "q.l23#12.a0" to "60",
    "q.l23#12.a1" to "65",
    "q.l23#12.a2" to "70",
    "q.l23#12.a3" to "60–70",
    "q.l23#12.e" to "About 60–70%. That is also the test of a good carry: if your shoulders are clearly working hard, the problem is usually the hipbelt.",
    "q.l23#13.p" to "Match each part of the pack with what belongs there.",
    "q.l23#13.l0" to "Upper middle, against the back",
    "q.l23#13.l1" to "Bottom of the pack",
    "q.l23#13.l2" to "Lid",
    "q.l23#13.l3" to "Side pocket",
    "q.l23#13.r0" to "Heavy items: water, stove, technical gear",
    "q.l23#13.r1" to "Sleeping bag and down jacket (in a dry bag)",
    "q.l23#13.r2" to "The day's insulation layer, action food",
    "q.l23#13.r3" to "Headlamp, small first-aid kit, sunscreen",
    "q.l23#13.e" to "Placement decides both access and centre of gravity. Headlamp in a side pocket so you are not digging through the pack in the dark; sleeping bag at the bottom because it is used once a day, in camp.",
    "q.l23#14.p" to "A teammate's pack is clearly much heavier than yours. What is the most sensible response?",
    "q.l23#14.o0" to "Empty both packs on the spot, redistribute, and share the group gear evenly",
    "q.l23#14.o1" to "Let him carry it; that is his choice",
    "q.l23#14.o2" to "Carry half of it for him even if you end up overloaded too",
    "q.l23#14.o3" to "Dump the group gear",
    "q.l23#14.e" to "A team moves at the speed of its slowest member, and an overloaded pack makes the slowest member slower. Group gear (stove, rope, first-aid kit) has to be shared out evenly, and that is a job for before departure.",

    "q.l24#0.p" to "Which temperature rating should you look at when choosing a sleeping bag?",
    "q.l24#0.o0" to "Comfort rating",
    "q.l24#0.o1" to "Limit rating",
    "q.l24#0.o2" to "The lowest temperature in the marketing copy",
    "q.l24#0.o3" to "Weight",
    "q.l24#0.e" to "The comfort rating is the temperature at which you sleep through the night in a base layer without feeling cold; the limit rating is only the survival boundary at which you do not become hypothermic, and the two are often more than 10 ℃ apart.",
    "q.l24#1.p" to "At altitude, how should the sleeping bag's comfort rating be set?",
    "q.l24#1.o0" to "At least 5 ℃ below the expected minimum temperature",
    "q.l24#1.o1" to "Equal to the expected minimum temperature",
    "q.l24#1.o2" to "5 ℃ above the expected minimum temperature",
    "q.l24#1.o3" to "It does not matter",
    "q.l24#1.e" to "The margin exists because metabolism drops overnight, food intake falls and the tent may frost inside, so you feel colder than the forecast.",
    "q.l24#2.p" to "What does a down sleeping bag most need protection from?",
    "q.l24#2.o0" to "Damp: once wet it insulates almost not at all",
    "q.l24#2.o1" to "Being folded",
    "q.l24#2.o2" to "Sunlight",
    "q.l24#2.o3" to "Friction",
    "q.l24#2.e" to "Wet down collapses its loft, insulation drops sharply, and it is very hard to dry properly in the field. A dry bag is the cheapest effective insurance.",
    "q.l24#3.p" to "What is the usual sleeping pad setup at a high camp?",
    "q.l24#3.o0" to "A closed-cell foam pad under an inflatable pad, with the insulation values adding up",
    "q.l24#3.o1" to "An inflatable pad only",
    "q.l24#3.o2" to "A foil mat only",
    "q.l24#3.o3" to "Sleeping straight on the tent floor",
    "q.l24#3.e" to "The foam pad blocks conduction from the ground, the inflatable provides a flat, comfortable surface. Stacked, they also back each other up: if the inflatable punctures, the foam is still there.",
    "q.l24#4.p" to "Your inflatable pad starts leaking in camp. What do you do first?",
    "q.l24#4.o0" to "Find the puncture and patch it, and put the foam pad underneath meanwhile",
    "q.l24#4.o1" to "Keep sleeping and deal with it tomorrow",
    "q.l24#4.o2" to "Let all the air out",
    "q.l24#4.o3" to "Change tents",
    "q.l24#4.e" to "A leak only gets worse, and the night only gets colder. Patch plus foam backup is the standard response; do not bet on it lasting until dawn.",
    "q.l24#5.p" to "How should a sleeping bag be stored long term?",
    "q.l24#5.o0" to "Laid out flat or hung loosely in a dry place",
    "q.l24#5.o1" to "Always compressed in its stuff sack",
    "q.l24#5.o2" to "Vacuum compressed",
    "q.l24#5.o3" to "Sealed in a plastic bag",
    "q.l24#5.e" to "Long-term compression fatigues the down's loft structure and over a few seasons insulation drops noticeably. Store it loose, and store it dry.",
    "q.l24#6.p" to "Which practices genuinely improve sleep at altitude?",
    "q.l24#6.o0" to "Drink less right before bed but still meet your daily fluid target",
    "q.l24#6.o1" to "Earplugs to block noise in the tent",
    "q.l24#6.o2" to "Bring wet clothes into the bag to dry",
    "q.l24#6.o3" to "Eat a very large meal before bed",
    "q.l24#6.e" to "Stuffing wet clothes into the bag drains a lot of heat and wets the down: a textbook mistake. A heavy meal late at night makes the night more uncomfortable.",
    "q.l24#7.p" to "What does a sleep system usually consist of?",
    "q.l24#7.o0" to "Sleeping bag (with liner)",
    "q.l24#7.o1" to "Sleeping pad (foam plus inflatable)",
    "q.l24#7.o2" to "Pillow",
    "q.l24#7.o3" to "Tent footprint",
    "q.l24#7.e" to "Together these four govern ground conduction, air convection and comfort. Miss one and you lose heat steadily in that direction all night.",
    "q.l24#8.p" to "What is the correct order for setting up the sleeping area?",
    "q.l24#8.o0" to "Clear and level the ground, remove stones and sharp objects",
    "q.l24#8.o1" to "Lay the footprint and the foam pad",
    "q.l24#8.o2" to "Inflate the air pad and check it",
    "q.l24#8.o3" to "Lay out the sleeping bag, leaving room to turn over",
    "q.l24#8.e" to "Get the order wrong and you redo it: an uncleared floor can puncture an air pad in a single night.",
    "q.l24#9.p" to "The sleeping bag's comfort rating should be at least ______ ℃ below the expected minimum temperature.",
    "q.l24#9.a0" to "5",
    "q.l24#9.e" to "A 5 ℃ margin is the common practice. Nights at altitude feel colder, so the margin is not generous.",
    "q.l24#10.p" to "Down insulates almost not at all once wet, so it must go in a ______ bag.",
    "q.l24#10.a0" to "waterproof",
    "q.l24#10.a1" to "waterproof bag",
    "q.l24#10.a2" to "dry",
    "q.l24#10.e" to "A separate dry bag is about isolation: the outside gets wet, the core stays dry.",
    "q.l24#11.p" to "Match each sleep item with its main job.",
    "q.l24#11.l0" to "Closed-cell foam pad",
    "q.l24#11.l1" to "Inflatable pad",
    "q.l24#11.l2" to "Sleeping bag liner",
    "q.l24#11.l3" to "Earplugs",
    "q.l24#11.r0" to "Blocks conduction from the ground, and cannot puncture",
    "q.l24#11.r1" to "Provides a flat, comfortable surface and adds insulation when stacked",
    "q.l24#11.r2" to "Reduces soiling and damp in the bag",
    "q.l24#11.r3" to "Cuts noise and helps you fall asleep",
    "q.l24#11.e" to "Four items for four different problems: conduction, flatness, moisture, noise. Whichever is missing is the direction the problem comes from.",
    "q.l24#12.p" to "Heavy frost inside the tent: what should you do the next morning?",
    "q.l24#12.o0" to "Bag the sleeping bag first, then shake the frost off the inner wall, so the bag stays dry",
    "q.l24#12.o1" to "Pack the tent first and leave the bag outside",
    "q.l24#12.o2" to "Melt the frost with body heat",
    "q.l24#12.o3" to "Ignore it; it will dry in the sun",
    "q.l24#12.e" to "Frosted fabric sheds ice the moment you touch it. Sealing the bag first is the key move that stops ten minutes in the morning from ruining a trip.",
    "q.l24#13.p" to "Why is sleep at altitude generally worse?",
    "q.l24#13.o0" to "Low oxygen causes periodic breathing, waking you repeatedly out of light sleep",
    "q.l24#13.o1" to "The tent floor is too hard",
    "q.l24#13.o2" to "Because you walked too little during the day",
    "q.l24#13.o3" to "Because time runs slower at altitude",
    "q.l24#13.e" to "It is physiological. All you can do is improve the conditions (warmth, quiet, hydration), not demand eight full hours of yourself.",
    "q.l24#14.p" to "The team has one spare tent. Who gets priority?",
    "q.l24#14.o0" to "Whoever is most likely to become hypothermic or already shows symptoms of altitude sickness",
    "q.l24#14.o1" to "The leader",
    "q.l24#14.o2" to "The fittest person",
    "q.l24#14.o3" to "Draw lots",
    "q.l24#14.e" to "Spare resources go by risk, not by seniority or fitness. Say so before departure to avoid an argument in the dark.",

    "q.l25#0.p" to "What is most often underestimated about climbing permits?",
    "q.l25#0.o0" to "Lead time and extra requirements (guide, local contact, medical certificate)",
    "q.l25#0.o1" to "The cost",
    "q.l25#0.o2" to "Photo size",
    "q.l25#0.o3" to "Office opening hours",
    "q.l25#0.e" to "Many routes need applications weeks ahead and tie you to a local guide or contact. Apply at the trailhead and you usually end up changing route.",
    "q.l25#1.p" to "Which two things most need confirming when choosing insurance?",
    "q.l25#1.o0" to "Whether technical climbing is covered, and whether high-altitude helicopter evacuation is covered",
    "q.l25#1.o1" to "Whether flight delay is included",
    "q.l25#1.o2" to "Whether you can cancel the policy",
    "q.l25#1.o3" to "How high the premium is",
    "q.l25#1.e" to "Ordinary travel policies routinely exclude technical climbing and high altitude. Discovering the exclusion only when something happens is the most common second injury in these accidents.",
    "q.l25#2.p" to "Which part of the logistics plan must have a backup?",
    "q.l25#2.o0" to "Transport, porterage and camp resupply: a fallback for every leg",
    "q.l25#2.o1" to "Transport only",
    "q.l25#2.o2" to "Accommodation only",
    "q.l25#2.o3" to "No backup is needed",
    "q.l25#2.e" to "Delay is the norm in the mountains: a washed-out road, a cancelled flight, a porter who changes plans. A fallback on every leg is what stops one blockage from collapsing the whole plan.",
    "q.l25#3.p" to "At minimum, what must the itinerary left with your home contact spell out?",
    "q.l25#3.o0" to "The route, checkpoint times, and how long silence lasts before the contingency and the alarm are triggered",
    "q.l25#3.o1" to "Just the name of the mountain",
    "q.l25#3.o2" to "Just teammates' names",
    "q.l25#3.o3" to "Just the budget",
    "q.l25#3.e" to "The itinerary lets someone else judge whether to worry. Times and the trigger plan are the core; the route is the premise.",
    "q.l25#4.p" to "Why keep a 20% margin in the budget?",
    "q.l25#4.o0" to "Delays, extra nights and last-minute porters all happen",
    "q.l25#4.o1" to "To buy souvenirs",
    "q.l25#4.o2" to "For tips",
    "q.l25#4.o3" to "Because exchange rates move",
    "q.l25#4.e" to "These costs are normal, not accidents. The margin is not about saving money; it is about not making bad decisions on the mountain because of money.",
    "q.l25#5.p" to "What does a summit certificate usually require?",
    "q.l25#5.o0" to "Summit photos or video, a summit declaration form, permit and ID",
    "q.l25#5.o1" to "Photos only",
    "q.l25#5.o2" to "A teammate's signature only",
    "q.l25#5.o3" to "Nothing at all",
    "q.l25#5.e" to "Requirements vary by peak, but photos, declaration form and permit are almost always needed. Confirm before you leave; far easier than chasing paperwork afterwards.",
    "q.l25#6.p" to "What must be briefed to the whole team before departure?",
    "q.l25#6.o0" to "Meeting and evacuation times and places",
    "q.l25#6.o1" to "Radio channels and call protocol",
    "q.l25#6.o2" to "Medical information and medication contraindications",
    "q.l25#6.o3" to "Each person's daily food allocation",
    "q.l25#6.e" to "The first two are about getting separated and about rescue, the third is critical in an emergency; food allocation is a logistics detail the leader can handle without a group discussion.",
    "q.l25#7.p" to "Which of these are documents you can be turned away for lacking?",
    "q.l25#7.o0" to "Protected-area or climbing permit",
    "q.l25#7.o1" to "Identification",
    "q.l25#7.o2" to "Insurance policy (required on some routes)",
    "q.l25#7.o3" to "Summit certificate",
    "q.l25#7.e" to "A summit certificate is something you only have afterwards, so it cannot be an entry document. The first two are checked almost everywhere, the third depends on the route.",
    "q.l25#8.p" to "From deciding on a mountain to departure, what is a sensible sequence?",
    "q.l25#8.o0" to "Fix the route and the time window",
    "q.l25#8.o1" to "Get permits, book transport and porterage",
    "q.l25#8.o2" to "Buy targeted insurance and check the exclusions",
    "q.l25#8.o3" to "Assemble the document pack and leave the itinerary with your contact",
    "q.l25#8.e" to "You cannot apply for a permit until the route is set, and you do not know which days and activities the insurance must cover until permit and transport are fixed. Filing comes last.",
    "q.l25#9.p" to "If luggage is delayed or does not arrive on your flight, what should you be carrying with you?",
    "q.l25#9.a0" to "climbing boots",
    "q.l25#9.a1" to "mountaineering boots",
    "q.l25#9.a2" to "boots",
    "q.l25#9.a3" to "personal technical gear",
    "q.l25#9.e" to "Boots and personal technical gear are almost impossible to replace at short notice. Most teams require both to travel with you, not in checked baggage.",
    "q.l25#10.p" to "Budgets usually keep a ______ % margin.",
    "q.l25#10.a0" to "20",
    "q.l25#10.e" to "20% is the rule of thumb. Extra spending on a mountain trip clusters around delays and around people.",
    "q.l25#11.p" to "Match each document with its purpose.",
    "q.l25#11.l0" to "Climbing permit",
    "q.l25#11.l1" to "Insurance policy and rescue number",
    "q.l25#11.l2" to "Summit declaration form",
    "q.l25#11.l3" to "Itinerary",
    "q.l25#11.r0" to "Proof of access; checked at control points",
    "q.l25#11.r1" to "The basis for calling rescue and for a claim",
    "q.l25#11.r2" to "Submitted when applying for a summit certificate",
    "q.l25#11.r3" to "Left with your contact, so they know when to raise the alarm",
    "q.l25#11.e" to "Four documents for four situations: getting in, something going wrong, proving it, going silent. Miss one and that situation jams.",
    "q.l25#12.p" to "If the team never confirms who has the authority to call a stop, what is the most likely consequence?",
    "q.l25#12.o0" to "Nobody dares speak when it matters, and collective silence amplifies the risk",
    "q.l25#12.o1" to "The team moves faster",
    "q.l25#12.o2" to "Packs get lighter",
    "q.l25#12.o3" to "No effect at all",
    "q.l25#12.e" to "Make calling a stop a pre-granted authority rather than a test of personal courage. Saying this before departure is far more useful than debating it on the mountain.",
    "q.l25#13.p" to "The permit requires a local guide but some in the team object. What is the right response?",
    "q.l25#13.o0" to "Follow the rule, and put the guide into the budget and the plan",
    "q.l25#13.o1" to "Bypass the checkpoint",
    "q.l25#13.o2" to "Have the guide sign on paper only",
    "q.l25#13.o3" to "Switch to a route that does not require one, and reassess",
    "q.l25#13.e" to "Circumventing a permit is not only illegal, it voids rescue and insurance. Comply, or change route; there is no option that relies on luck.",
    "q.l25#14.p" to "Why collect medical and medication information before departure?",
    "q.l25#14.o0" to "First aid needs to know contraindications and history, and altitude magnifies underlying conditions",
    "q.l25#14.o1" to "To get a discount on insurance",
    "q.l25#14.o2" to "For splitting into groups",
    "q.l25#14.o3" to "It has no practical use",
    "q.l25#14.e" to "Above 5,000 m an ordinary infection or a drug allergy can turn into an emergency. Collect the information before you leave, not one by one after something happens.",
    "q.l42#0.p" to "What does the 4-3-3 principle mean?",
    "q.l42#0.o0" to "Keep a third in reserve in fitness, time, and equipment",
    "q.l42#0.o1" to "Three people, three hours, three routes",
    "q.l42#0.o2" to "Three kinds of gear, three kinds of weather",
    "q.l42#0.o3" to "Three checks, three confirmations",
    "q.l42#0.e" to "Leaving a margin is not conservatism; it means pricing the unexpected into the plan in advance. Use everything up and any change leaves you relying on luck.",
    "q.l42#1.p" to "In the no-three-news rule, what are the three news?",
    "q.l42#1.o0" to "A new route, new teammates, new equipment",
    "q.l42#1.o1" to "A new season, new weather, a new altitude",
    "q.l42#1.o2" to "A new plan, a new budget, a new objective",
    "q.l42#1.o3" to "A new guide, a new vehicle, new boots",
    "q.l42#1.e" to "Each new element represents the unknown. Stacking all three at once maxes out uncertainty in a single trip.",
    "q.l42#2.p" to "Why reduce consequences before reducing likelihood?",
    "q.l42#2.o0" to "A consequence cannot be undone once it happens, while likelihood can only be lowered, never removed",
    "q.l42#2.o1" to "Because reducing consequences is cheaper",
    "q.l42#2.o2" to "Because likelihood cannot be calculated",
    "q.l42#2.o3" to "The order does not matter",
    "q.l42#2.e" to "Roping up, wearing a helmet, keeping an escape route: all of these mean that even if it happens, it need not be fatal. That is far more effective than being careful.",
    "q.l42#3.p" to "What is the correct order of the STOP principle?",
    "q.l42#3.o0" to "Stop, Think, Observe, Plan",
    "q.l42#3.o1" to "Observe, Stop, Think, Plan",
    "q.l42#3.o2" to "Think, Observe, Stop, Plan",
    "q.l42#3.o3" to "Stop, Observe, Think, Plan",
    "q.l42#3.e" to "You have to stop before thinking and observing are possible. Under pressure the first reflex is usually to keep walking, which is the most dangerous default.",
    "q.l42#4.p" to "What is the purpose of the abandon-conditions line in a plan?",
    "q.l42#4.o0" to "It moves the decision outside emotion and summit pressure",
    "q.l42#4.o1" to "It makes the plan look complete",
    "q.l42#4.o2" to "It satisfies an inspection",
    "q.l42#4.o3" to "It has no practical effect",
    "q.l42#4.e" to "Deciding to turn around on the mountain, tired and goal-focused, is nearly impossible. Only conditions written down in advance have any force.",
    "q.l42#5.p" to "Which is NOT one of the three keys to a safe camp?",
    "q.l42#5.o0" to "Pitch as close to the water as possible",
    "q.l42#5.o1" to "Avoid terrain traps",
    "q.l42#5.o2" to "Keep an escape route open",
    "q.l42#5.o3" to "Consolidate critical supplies",
    "q.l42#5.e" to "Camping right beside the water is the classic flash-flood scenario. The three keys all come down to being able to retreat first; views and convenience rank lower.",
    "q.l42#6.p" to "The team has brand-new equipment and is also on a new route. What does the three-news rule suggest?",
    "q.l42#6.o0" to "Drop at least one of them, or lower the difficulty enough to test the gear",
    "q.l42#6.o1" to "It is fine, new gear is safer",
    "q.l42#6.o2" to "Speed up to compensate",
    "q.l42#6.o3" to "Split up and go separately",
    "q.l42#6.e" to "New gear needs validation and a new route needs adaptation. Do both at once and you cannot tell which one caused the problem.",
    "q.l42#7.p" to "Regarding risk = consequence x likelihood, which statement is correct?",
    "q.l42#7.o0" to "When the consequence is severe enough, even a low likelihood must be addressed",
    "q.l42#7.o1" to "A low likelihood can be ignored",
    "q.l42#7.o2" to "Look only at likelihood",
    "q.l42#7.o3" to "Look only at consequence",
    "q.l42#7.e" to "The point of the product is that when the consequence is large enough, even a very low-probability event must be covered by a contingency plan.",
    "q.l42#8.p" to "Which measures reduce consequences?",
    "q.l42#8.o0" to "Moving roped up and placing protection",
    "q.l42#8.o1" to "Wearing a helmet",
    "q.l42#8.o2" to "Keeping an escape route open",
    "q.l42#8.o3" to "Improving fitness",
    "q.l42#8.e" to "The first three all reduce harm when something goes wrong. Better fitness lowers how likely an incident is, not how bad it gets.",
    "q.l42#9.p" to "Which measures reduce likelihood?",
    "q.l42#9.o0" to "Checking the weather and avalanche forecast",
    "q.l42#9.o1" to "Acclimatising in advance",
    "q.l42#9.o2" to "Choosing a well-established route",
    "q.l42#9.o3" to "Carrying only one radio",
    "q.l42#9.e" to "The first three reduce how often you meet danger. The last has nothing to do with risk level and actually removes redundancy.",
    "q.l42#10.p" to "Which situations should trigger STOP?",
    "q.l42#10.o0" to "The route does not match the map",
    "q.l42#10.o1" to "The weather changes obviously within a short time",
    "q.l42#10.o2" to "A team member is not right but cannot say why",
    "q.l42#10.o3" to "You are half an hour behind schedule",
    "q.l42#10.e" to "The first three are all signals that reality no longer matches expectation. Being half an hour behind is normal variation; check the clock before deciding.",
    "q.l42#11.p" to "Put one round of risk handling in order.",
    "q.l42#11.o0" to "Identify the hazards (terrain, weather, people's condition)",
    "q.l42#11.o1" to "Judge the consequence and the likelihood",
    "q.l42#11.o2" to "Prefer measures that reduce consequences",
    "q.l42#11.o3" to "Execute and set a review time",
    "q.l42#11.e" to "The last step is the one most often skipped: without a review time, measures quietly stop working.",
    "q.l42#12.p" to "Put the pre-trip three-news check in order.",
    "q.l42#12.o0" to "List this trip's new route, new teammates, and new equipment",
    "q.l42#12.o1" to "Assess the unknowns each one brings",
    "q.l42#12.o2" to "Decide which to drop or how to lower the difficulty",
    "q.l42#12.o3" to "Write the decision into the plan and tell the team",
    "q.l42#12.e" to "The third step is the crux: dropping something is an active decision, not a promise to be careful once you are out there.",
    "q.l42#13.p" to "The 4-3-3 principle keeps ______ of the margin in fitness, time, and equipment.",
    "q.l42#13.a0" to "one third",
    "q.l42#13.a1" to "1/3",
    "q.l42#13.a2" to "a third",
    "q.l42#13.e" to "A third is a rule of thumb. The more of it you spend, the less room you have when conditions change.",
    "q.l42#14.p" to "Risk equals consequence multiplied by ______.",
    "q.l42#14.a0" to "likelihood",
    "q.l42#14.a1" to "probability",
    "q.l42#14.e" to "Splitting risk into two multipliers tells you which one to attack, and it is usually the consequence first.",
    "q.l42#15.p" to "Under the no-three-news rule, how many news is it advisable to have on one trip at most?",
    "q.l42#15.a0" to "1",
    "q.l42#15.a1" to "one",
    "q.l42#15.a2" to "2",
    "q.l42#15.a3" to "two",
    "q.l42#15.e" to "One at most; two is already the ceiling. All three means building the plan on three unknowns.",
    "q.l42#16.p" to "Match each measure with its effect.",
    "q.l42#16.l0" to "Moving roped up",
    "q.l42#16.l1" to "Checking the avalanche forecast",
    "q.l42#16.l2" to "Keeping an escape route",
    "q.l42#16.l3" to "Acclimatising in advance",
    "q.l42#16.r0" to "Reduces consequence (a fall is no longer borne alone)",
    "q.l42#16.r1" to "Reduces likelihood (avoiding high-risk days)",
    "q.l42#16.r2" to "Reduces consequence (you can withdraw when it turns)",
    "q.l42#16.r3" to "Reduces likelihood (less altitude illness)",
    "q.l42#16.e" to "The difference is whether a measure changes the outcome or the probability. Get that straight and you know where to invest.",
    "q.l42#17.p" to "Match each principle with where it applies.",
    "q.l42#17.l0" to "4-3-3",
    "q.l42#17.l1" to "No three news",
    "q.l42#17.l2" to "STOP",
    "q.l42#17.l3" to "Consequence x likelihood",
    "q.l42#17.r0" to "Itinerary and resource allocation",
    "q.l42#17.r1" to "Pre-trip choices and what to drop",
    "q.l42#17.r2" to "Something suddenly looks wrong on the ground",
    "q.l42#17.r3" to "Choosing between several options",
    "q.l42#17.e" to "The four tools serve planning, pre-trip selection, the moment on the ground, and trade-offs. They do not replace each other; they work at different stages.",
    "q.l26#0.p" to "On a 1:50,000 map, one centimetre represents how many metres on the ground?",
    "q.l26#0.o0" to "500 m",
    "q.l26#0.o1" to "50 m",
    "q.l26#0.o2" to "5,000 m",
    "q.l26#0.o3" to "5 m",
    "q.l26#0.e" to "Drop two zeros from the denominator and you have metres per centimetre: 50,000 becomes 500 m. This is the starting point for every map calculation.",
    "q.l26#1.p" to "What does contour interval mean?",
    "q.l26#1.o0" to "The height difference between two adjacent contour lines",
    "q.l26#1.o1" to "The horizontal distance between contour lines",
    "q.l26#1.o2" to "The height difference between two points on the map",
    "q.l26#1.o3" to "A peak's relative height",
    "q.l26#1.e" to "A larger interval gives a more generalised map. Slope steepness comes from how tightly the lines are packed; height difference comes from the interval.",
    "q.l26#2.p" to "How is magnetic declination defined?",
    "q.l26#2.o0" to "The angle between magnetic north and true north",
    "q.l26#2.o1" to "The angle between the map and the ground",
    "q.l26#2.o2" to "The angle of a slope",
    "q.l26#2.o3" to "The error of the compass needle",
    "q.l26#2.e" to "Declination differs by region and drifts year by year. Maps usually print the value and the annual change, so correct it for the current year before use.",
    "q.l26#3.p" to "After taking a bearing to a target on the map, how should you travel?",
    "q.l26#3.o0" to "Follow the bearing while continuously confirming with contours and terrain features",
    "q.l26#3.o1" to "Head down, eyes on the compass, straight all the way",
    "q.l26#3.o2" to "Just follow the GPS arrow",
    "q.l26#3.o3" to "Take the most obvious trail and ignore the bearing",
    "q.l26#3.e" to "The bearing gives general direction; terrain gives your actual position. Following the needle alone easily puts you one ridge off, and that costs hours.",
    "q.l26#4.p" to "Contour lines packed closely together mean what?",
    "q.l26#4.o0" to "A steeper slope",
    "q.l26#4.o1" to "A gentler slope",
    "q.l26#4.o2" to "A higher altitude",
    "q.l26#4.o3" to "Flatter ground",
    "q.l26#4.e" to "Tight contours mean more height gain over the same horizontal distance, which is steeper. This is most useful when deciding which way up is less work.",
    "q.l26#5.p" to "What should a GPS be in the field?",
    "q.l26#5.o0" to "An accelerator and a backup, never the only means of navigation",
    "q.l26#5.o1" to "The only means of navigation",
    "q.l26#5.o2" to "An entertainment device",
    "q.l26#5.o3" to "A rescue device",
    "q.l26#5.e" to "Batteries, cold, water, and drops will all take it out. A paper map and compass are the only solution that needs no power.",
    "q.l26#6.p" to "What does orienting the map mean?",
    "q.l26#6.o0" to "Aligning the map's north with true north on the ground",
    "q.l26#6.o1" to "Folding the map to the current area",
    "q.l26#6.o2" to "Putting the map in a waterproof case",
    "q.l26#6.o3" to "Drawing the route thicker",
    "q.l26#6.e" to "Only once the map is oriented do the ridges and valleys on paper match what is in front of you. Many people who cannot read a map go wrong at this first step.",
    "q.l26#7.p" to "When visibility disappears on a snow slope or in fog, what is the most reliable way to navigate?",
    "q.l26#7.o0" to "Take a bearing with the compass plus estimate distance by time or pacing",
    "q.l26#7.o1" to "Go by feel",
    "q.l26#7.o2" to "Wait for the cloud to lift",
    "q.l26#7.o3" to "Follow someone else's tracks",
    "q.l26#7.e" to "With poor visibility all terrain references vanish, leaving only angle and distance. Pacing requires that you have calibrated your step count beforehand, or the error is large.",
    "q.l26#8.p" to "A navigation kit that does not depend on electronics should include at least what?",
    "q.l26#8.o0" to "A paper topographic map covering the area",
    "q.l26#8.o1" to "A compass",
    "q.l26#8.o2" to "An altimeter or a watch",
    "q.l26#8.o3" to "Spare batteries",
    "q.l26#8.e" to "The fourth serves electronic devices, so it is not part of the no-electronics set. Map, compass, and altimeter together are enough to fix position and travel.",
    "q.l26#9.p" to "Which conditions make a GPS track unreliable?",
    "q.l26#9.o0" to "Canyons and steep walls blocking the signal",
    "q.l26#9.o1" to "Cold draining the battery suddenly",
    "q.l26#9.o2" to "Pausing under a cornice",
    "q.l26#9.o3" to "A route that is very straight",
    "q.l26#9.e" to "The first three cause drift or power loss. How straight a route is has nothing to do with signal, though a straight line tends to make people trust the device and read the terrain less.",
    "q.l26#10.p" to "Which clues confirm your position while reading the map?",
    "q.l26#10.o0" to "The aspect of the slope you are on",
    "q.l26#10.o1" to "The contour pattern underfoot (ridge, valley, saddle)",
    "q.l26#10.o2" to "Bearing relationships to obvious features",
    "q.l26#10.o3" to "The shape of the clouds",
    "q.l26#10.e" to "Aspect, contour pattern, and bearings to identifiable features intersect to fix your position. Cloud shape belongs to weather judgement, not navigation.",
    "q.l26#11.p" to "Put a complete compass navigation sequence in order.",
    "q.l26#11.o0" to "Orient the map so map north matches true north",
    "q.l26#11.o1" to "Confirm your current position",
    "q.l26#11.o2" to "Take the bearing to the target",
    "q.l26#11.o3" to "Travel on the bearing and check the terrain as you go",
    "q.l26#11.e" to "The order cannot be skipped: if your position is uncertain, the bearing is meaningless, and without checking terrain you are walking a theoretical straight line.",
    "q.l26#12.p" to "In terrain with no obvious landmarks, what is the sequence for covering a bearing leg?",
    "q.l26#12.o0" to "Pick an intermediate target in the distance",
    "q.l26#12.o1" to "Walk to it and re-confirm your position",
    "q.l26#12.o2" to "Pick the next intermediate target",
    "q.l26#12.o3" to "Use terrain features to confirm as you close in",
    "q.l26#12.e" to "A long straight line is almost impossible to hold in broken terrain. Breaking the leg into intermediate points is the only way to land the angle on real ground.",
    "q.l26#13.p" to "The angle between magnetic north and true north is called ______.",
    "q.l26#13.a0" to "declination",
    "q.l26#13.a1" to "magnetic declination",
    "q.l26#13.a2" to "variation",
    "q.l26#13.e" to "Magnetic declination must be corrected with the year's value printed on the map, or you can drift tens of metres off per kilometre.",
    "q.l26#14.p" to "On a 1:25,000 map, one centimetre represents ______ metres on the ground.",
    "q.l26#14.a0" to "250",
    "q.l26#14.e" to "Drop two zeros from the denominator: 25,000 becomes 250 m. A larger scale shows more detail and covers less ground.",
    "q.l26#15.p" to "With a 10 m contour interval, going from the 3,200 m contour to the 3,280 m contour crosses ______ contours (not counting the start).",
    "q.l26#15.a0" to "8",
    "q.l26#15.e" to "(3,280 - 3,200) / 10 = 8. You use this kind of arithmetic every day when estimating ascent and time.",
    "q.l26#16.p" to "Match each terrain feature with how it appears on the map.",
    "q.l26#16.l0" to "Ridge",
    "q.l26#16.l1" to "Valley",
    "q.l26#16.l2" to "Saddle",
    "q.l26#16.l3" to "Cliff",
    "q.l26#16.r0" to "Contours bulge toward lower ground",
    "q.l26#16.r1" to "Contours bulge toward higher ground",
    "q.l26#16.r2" to "A low point between two contour groups, higher on both sides",
    "q.l26#16.r3" to "Many contours merged or extremely close",
    "q.l26#16.e" to "Bulge low is a ridge, bulge high is a valley: the most useful rule of thumb in map reading. A saddle is a key feature in route choice because it is often the lowest passage.",
    "q.l26#17.p" to "Match each navigation tool with its limitation.",
    "q.l26#17.l0" to "GPS",
    "q.l26#17.l1" to "Compass",
    "q.l26#17.l2" to "Altimeter",
    "q.l26#17.l3" to "Paper map",
    "q.l26#17.r0" to "Needs power and satellite signal; fails in canyons and cold",
    "q.l26#17.r1" to "Affected by nearby ferrous objects; needs declination correction",
    "q.l26#17.r2" to "Gives altitude only, not horizontal position",
    "q.l26#17.r3" to "Needs updating and may not cover new routes",
    "q.l26#17.e" to "Every tool has a failure mode, so navigation has to be combined: when one fails, another still gives you a constraint.",
    "q.l27#0.p" to "What has the highest priority when choosing a campsite?",
    "q.l27#0.o0" to "Avoiding rockfall, avalanche paths, and flood lines",
    "q.l27#0.o1" to "A good view",
    "q.l27#0.o2" to "Being closest to the route",
    "q.l27#0.o3" to "The flattest ground",
    "q.l27#0.e" to "Safety, then water, then flat ground, then comfort. Reverse that order and you get incidents like a tent pitched in an avalanche deposit.",
    "q.l27#1.p" to "What is the first step when camping on a snow slope?",
    "q.l27#1.o0" to "Stomp the snow firm and cut a level platform",
    "q.l27#1.o1" to "Lay the tent out immediately",
    "q.l27#1.o2" to "Start melting water",
    "q.l27#1.o3" to "Guy out the tent first",
    "q.l27#1.e" to "An uneven snow surface means sliding all night; without a platform the tent is loaded unevenly and deforms in the first gust.",
    "q.l27#2.p" to "What is a sensible distance between camp and a water source?",
    "q.l27#2.o0" to "Convenient, but camp at least 60 m from the water",
    "q.l27#2.o1" to "Right on the bank",
    "q.l27#2.o2" to "In the water",
    "q.l27#2.o3" to "As far as possible, two kilometres",
    "q.l27#2.e" to "60 m is the standard sanitary distance: it limits contamination of the water and keeps you off the night-time flood line. Camping at the water's edge is the classic flash-flood scenario.",
    "q.l27#3.p" to "At base camp, how should the cooking area and sleeping area be arranged?",
    "q.l27#3.o0" to "Separate them, with cooking well away from sleeping",
    "q.l27#3.o1" to "Together, it is more convenient",
    "q.l27#3.o2" to "Cooking inside the tent",
    "q.l27#3.o3" to "It does not matter",
    "q.l27#3.e" to "Three reasons to separate: open flame, carbon monoxide, and food smells attracting animals. Combining them saves a dozen metres of walking and can cost you the whole tent.",
    "q.l27#4.p" to "How do you anchor a tent on ice or hard snow?",
    "q.l27#4.o0" to "Ice screws, snow anchors, or buried stuff sacks, never just rocks on top",
    "q.l27#4.o1" to "Rocks on the guy lines are enough",
    "q.l27#4.o2" to "Tie the guys to trekking poles",
    "q.l27#4.o3" to "No anchoring needed",
    "q.l27#4.e" to "Ice offers no loose material to weight anything down, and wind will pull the tent and its stakes out together. Ice screws and snow anchors are the effective points.",
    "q.l27#5.p" to "How should a fire scar be dealt with when leaving camp?",
    "q.l27#5.o0" to "Douse it thoroughly, scatter the ash, and restore the ground",
    "q.l27#5.o1" to "Cover it with soil",
    "q.l27#5.o2" to "Leave it for next time",
    "q.l27#5.o3" to "Ignore it",
    "q.l27#5.e" to "Scattering the ash lets it weather back to a natural look. A leftover fire ring persists for years and invites the next party to burn in the same spot.",
    "q.l27#6.p" to "In strong wind, where does a tent most often fail?",
    "q.l27#6.o0" to "Guy lines and anchor points: uneven loading lifts one side first",
    "q.l27#6.o1" to "The fabric",
    "q.l27#6.o2" to "The zips",
    "q.l27#6.o3" to "The footprint",
    "q.l27#6.e" to "Guy line angles and anchors decide wind resistance. Tents rarely fail because the fabric tore; one anchor point goes first.",
    "q.l27#7.p" to "It snowed overnight and the tent is half buried by morning. What do you do?",
    "q.l27#7.o0" to "Clear the vents and door first, then dig out around the tent",
    "q.l27#7.o1" to "Take photos first",
    "q.l27#7.o2" to "Pack the tent up straight away",
    "q.l27#7.o3" to "Wait for the snow to stop",
    "q.l27#7.e" to "A blocked vent means carbon monoxide and oxygen starvation. Restore ventilation before anything else.",
    "q.l27#8.p" to "Which of these are terrain traps and unsuitable for camping?",
    "q.l27#8.o0" to "The runout at the base of an avalanche path",
    "q.l27#8.o1" to "Dry riverbeds and gullies",
    "q.l27#8.o2" to "A windy notch on a ridge",
    "q.l27#8.o3" to "A flat clearing in the trees",
    "q.l27#8.e" to "The first three are classic avalanche, flash-flood, and wind positions. A forest clearing is comparatively safe, but still check for dead branches and fallen trees.",
    "q.l27#9.p" to "What should a suitable campsite satisfy?",
    "q.l27#9.o0" to "Level ground with good drainage",
    "q.l27#9.o1" to "Sheltered but not enclosed",
    "q.l27#9.o2" to "A usable water source",
    "q.l27#9.o3" to "Full phone signal",
    "q.l27#9.e" to "The first three decide whether you sleep well and stay warm. Signal is a bonus, and you should not move camp onto an exposed ridge to get it.",
    "q.l27#10.p" to "Which practices are correct for waste and hygiene in the field?",
    "q.l27#10.o0" to "Dig a 15-20 cm cathole at least 60 m from water",
    "q.l27#10.o1" to "Pack out toilet paper rather than burning it",
    "q.l27#10.o2" to "Use one single spot for everyone",
    "q.l27#10.o3" to "Bury it in the snow",
    "q.l27#10.e" to "Concentrating waste concentrates contamination, and anything buried in snow is exposed at melt. Catholes plus packing out paper is the standard low-impact approach.",
    "q.l27#11.p" to "Put camp construction in a sensible order.",
    "q.l27#11.o0" to "Assess rockfall, avalanche, and flood risk",
    "q.l27#11.o1" to "Choose the tent site and level the ground",
    "q.l27#11.o2" to "Pitch the tent, set guy lines and anchors",
    "q.l27#11.o3" to "Define cooking, storage, and toilet areas",
    "q.l27#11.e" to "Assess before you build. Many people pitch first and only then look up to see the cracks and hanging ice above.",
    "q.l27#12.p" to "A cathole in the field is usually about ______ cm deep.",
    "q.l27#12.a0" to "15-20",
    "q.l27#12.a1" to "15 to 20",
    "q.l27#12.a2" to "15",
    "q.l27#12.a3" to "20",
    "q.l27#12.a4" to "15~20",
    "q.l27#12.e" to "15-20 cm is the commonly cited depth: deep enough to break down, shallow enough not to reach the subsoil.",
    "q.l27#13.p" to "The minimum sanitary distance from camp to water and trails is usually ______ m.",
    "q.l27#13.a0" to "60",
    "q.l27#13.e" to "60 m, roughly 70 paces, is the standard leave-no-trace distance for waste, dishes, and washing.",
    "q.l27#14.p" to "Match each camp zone with its requirement.",
    "q.l27#14.l0" to "Sleeping area",
    "q.l27#14.l1" to "Cooking area",
    "q.l27#14.l2" to "Storage area",
    "q.l27#14.l3" to "Toilet area",
    "q.l27#14.r0" to "Level, sheltered, away from flame and food smells",
    "q.l27#14.r1" to "Ventilated, away from tents, fire handled with care",
    "q.l27#14.r2" to "Dry and animal-proof, close by but out of the walkway",
    "q.l27#14.r3" to "Over 60 m from water, away from slope runoff",
    "q.l27#14.e" to "Zoning lets each activity happen under the right conditions. The immediate cost of muddled zoning is food smells in the tent and an open flame next to where people sleep.",
    "q.l27#15.p" to "There is a lovely stream beside camp, but it is pouring with rain two kilometres upstream. What do you conclude?",
    "q.l27#15.o0" to "Do not camp in the streambed; the risk of a night flood is high",
    "q.l27#15.o1" to "It is fine, the stream is small",
    "q.l27#15.o2" to "Move the tent a little closer to the water",
    "q.l27#15.o3" to "Put rocks in the stream to block it",
    "q.l27#15.e" to "A mountain stream can rise within minutes, and you hear it before you see it. Never camp in a streambed, gully, or alluvial fan: that is a hard rule.",
    "q.l27#16.p" to "Why should a campsite not be under an isolated large tree?",
    "q.l27#16.o0" to "Both lightning strike and falling branch risk are higher",
    "q.l27#16.o1" to "It is not ventilated under a tree",
    "q.l27#16.o2" to "Roots trip people",
    "q.l27#16.o3" to "It blocks the light",
    "q.l27#16.e" to "An isolated high point is the preferred path for lightning, and broken branches are a common source of injury in storms. In forest, choose a clearing rather than a single big tree.",
    "q.l28#0.p" to "What is the first step of the STOP principle?",
    "q.l28#0.o0" to "Stop",
    "q.l28#0.o1" to "Head straight back the way you came",
    "q.l28#0.o2" to "Make a phone call",
    "q.l28#0.o3" to "Climb up to look for the route",
    "q.l28#0.e" to "Stopping brings judgement back to reason. The first reflex when lost is usually to speed up, and that is exactly where incidents start to grow.",
    "q.l28#1.p" to "How many signals make an internationally recognised distress call?",
    "q.l28#1.o0" to "Three (three whistle blasts, three flashes, three columns of smoke)",
    "q.l28#1.o1" to "One",
    "q.l28#1.o2" to "Five",
    "q.l28#1.o3" to "As many as possible",
    "q.l28#1.e" to "Three is the international mountain convention. Only three in a row, repeated after a one-minute pause, is read as distress rather than an accidental noise.",
    "q.l28#2.p" to "In the field, which way of signalling is the least tiring and carries farthest?",
    "q.l28#2.o0" to "A whistle",
    "q.l28#2.o1" to "Shouting",
    "q.l28#2.o2" to "Waving",
    "q.l28#2.o3" to "Whistling with your lips",
    "q.l28#2.e" to "Shouting leaves you hoarse within minutes, while a whistle still cuts through wind. That is why a whistle is one of the ten essentials.",
    "q.l28#3.p" to "You realise you are lost on a gentle slope with no obvious features. What comes first?",
    "q.l28#3.o0" to "Recall your last certain position and judge whether retreating is feasible",
    "q.l28#3.o1" to "Keep descending to find a route",
    "q.l28#3.o2" to "Wait where you are until dark",
    "q.l28#3.o3" to "Split up and each look for the way",
    "q.l28#3.e" to "The last certain position is the only reliable anchor. Splitting up is the most dangerous option in a lost-person incident: one missing person becomes two.",
    "q.l28#4.p" to "While waiting for rescue, what should you secure first?",
    "q.l28#4.o0" to "Warmth and water, then making yourself visible",
    "q.l28#4.o1" to "Eat all the food in your pack",
    "q.l28#4.o2" to "Keep looking for the route",
    "q.l28#4.o3" to "Take a nap",
    "q.l28#4.e" to "Most deaths after getting lost come from hypothermia and dehydration, not from failing to find the way. Warmth, water, and visibility are the three jobs of the waiting period.",
    "q.l28#5.p" to "For an unplanned forced bivouac, what is most needed but most often left at camp?",
    "q.l28#5.o0" to "Headlamp and insulation",
    "q.l28#5.o1" to "Snacks",
    "q.l28#5.o2" to "The map",
    "q.l28#5.o3" to "The water bottle",
    "q.l28#5.e" to "On short excursions people leave these two behind. Once forced to stay out, they are exactly what decides whether you last until morning.",
    "q.l28#6.p" to "A teammate has not returned on time. What is the first step?",
    "q.l28#6.o0" to "Fix the last sighting point and time, and start the agreed overdue procedure",
    "q.l28#6.o1" to "Everyone spreads out to search",
    "q.l28#6.o2" to "Keep waiting",
    "q.l28#6.o3" to "Pack up the tents first",
    "q.l28#6.e" to "Pin down the facts first (time, place, gear, condition), then decide how to search. Sending everyone out separately is a common way to create a second incident.",
    "q.l28#7.p" to "Why does a mirror flash work so well on a sunny day?",
    "q.l28#7.o0" to "Reflected light can be seen from far away and from the air, well beyond the range of sound",
    "q.l28#7.o1" to "Because mirrors are shiny",
    "q.l28#7.o2" to "Because it makes a noise",
    "q.l28#7.o3" to "Because it can start a fire",
    "q.l28#7.e" to "Helicopters and distant teams pick up regular flashes most easily. With sun, a mirror is the best value signalling tool you carry.",
    "q.l28#8.p" to "Which actions should you avoid after getting lost?",
    "q.l28#8.o0" to "Continuing to travel after dark",
    "q.l28#8.o1" to "Splitting up",
    "q.l28#8.o2" to "Following a stream downhill",
    "q.l28#8.o3" to "Stopping and building shelter",
    "q.l28#8.e" to "Night travel, splitting up, and blindly following a stream down are the three most common fatal choices in lost-person incidents. Stopping and building shelter is the correct answer.",
    "q.l28#9.p" to "What do the ten essentials usually include?",
    "q.l28#9.o0" to "Navigation (map and compass)",
    "q.l28#9.o1" to "Headlamp",
    "q.l28#9.o2" to "Extra warm clothing",
    "q.l28#9.o3" to "Sun protection and first aid",
    "q.l28#9.e" to "The logic behind the ten essentials is surviving a forced night out: navigation, light, insulation, water, food, sun protection, first aid, fire, knife, shelter.",
    "q.l28#10.p" to "What must a distress message state clearly?",
    "q.l28#10.o0" to "Position (coordinates or an obvious landmark)",
    "q.l28#10.o1" to "Number of people and injuries",
    "q.l28#10.o2" to "Gear and supplies on hand",
    "q.l28#10.o3" to "The year the team was founded",
    "q.l28#10.e" to "Rescuers need to know where, how many, in what condition, and how long you can hold out. Missing any of the first four costs hours of confirmation.",
    "q.l28#11.p" to "Put the response to being lost in the correct order.",
    "q.l28#11.o0" to "Stop and admit you are actually lost",
    "q.l28#11.o1" to "Recall your last certain position",
    "q.l28#11.o2" to "Assess retreating versus climbing to obvious terrain",
    "q.l28#11.o3" to "Commit to a plan and execute it, keeping a rescue option open",
    "q.l28#11.e" to "The sequence is admit, then locate, then decide. Without admitting you are lost, none of the next three steps actually happens.",
    "q.l28#12.p" to "What is the correct priority order while waiting for rescue?",
    "q.l28#12.o0" to "Find shelter from the wind and add insulation",
    "q.l28#12.o1" to "Get water or melt snow",
    "q.l28#12.o2" to "Set out visible signals (whistle, mirror, bright colours)",
    "q.l28#12.o3" to "Repeat calls at fixed intervals",
    "q.l28#12.e" to "Stay alive first, then signal. Reverse it and you may be hypothermic before you ever send a signal.",
    "q.l28#13.p" to "An international distress signal is usually repeated ______ times per group.",
    "q.l28#13.a0" to "3",
    "q.l28#13.a1" to "three",
    "q.l28#13.e" to "Three per group, repeated after a minute, is the convention shared by mountain and maritime rescue.",
    "q.l28#14.p" to "The four-step response to being lost is STOP, where P stands for ______.",
    "q.l28#14.a0" to "Plan",
    "q.l28#14.a1" to "plan",
    "q.l28#14.a2" to "planning",
    "q.l28#14.e" to "Stop, Think, Observe, Plan. Stop first, then think, then look, and only then make a plan.",
    "q.l28#15.p" to "Match each signalling method with when it works.",
    "q.l28#15.l0" to "Whistle",
    "q.l28#15.l1" to "Mirror flash",
    "q.l28#15.l2" to "Three columns of smoke",
    "q.l28#15.l3" to "Bright clothing",
    "q.l28#15.r0" to "Any weather; three short blasts, repeated",
    "q.l28#15.r1" to "Clear sky with sun and good visibility",
    "q.l28#15.r2" to "Daytime, little wind, open ground",
    "q.l28#15.r3" to "Laid out on the ground for helicopters or distant searchers",
    "q.l28#15.e" to "No single method works in all conditions, so use several at once. Signalling is about raising the chance of being found, not about finding the perfect method.",
    "q.l28#16.p" to "There is no phone signal, but the team carries a satellite communicator. When should it be used?",
    "q.l28#16.o0" to "As soon as outside rescue is clearly needed, not after dark",
    "q.l28#16.o1" to "Wait until the next day",
    "q.l28#16.o2" to "Only if someone is injured",
    "q.l28#16.o3" to "Save it for the last day",
    "q.l28#16.e" to "Battery and weather windows are both limited, and rescue response takes time. Wait for darkness or a turn in the weather and the helicopter often cannot come in at all.",
    "q.l28#17.p" to "If you judge that you must walk out yourselves, what should you do before leaving?",
    "q.l28#17.o0" to "Leave a note with your direction and time, take full insulation and light, and mark the route",
    "q.l28#17.o1" to "Just go",
    "q.l28#17.o2" to "Leave the gear behind to lighten the load",
    "q.l28#17.o3" to "Split up",
    "q.l28#17.e" to "Walking out is a decision that must be recorded: a note tells searchers where you went, and the gear decides whether you get there.",
    "q.l29#0.p" to "At altitude, what is the most reliable everyday indicator of dehydration?",
    "q.l29#0.o0" to "Darker urine and reduced volume",
    "q.l29#0.o1" to "How thirsty you feel",
    "q.l29#0.o2" to "Body weight",
    "q.l29#0.o3" to "Whether the skin is dry",
    "q.l29#0.e" to "By the time thirst appears you are already noticeably short of fluid. Urine colour is the cheapest check: pale yellow is fine, dark yellow means drink.",
    "q.l29#1.p" to "What is the core criterion for heat stroke?",
    "q.l29#1.o0" to "Core temperature above 40 C with altered mental status",
    "q.l29#1.o1" to "Sweating heavily",
    "q.l29#1.o2" to "Red skin",
    "q.l29#1.o3" to "A fast heartbeat",
    "q.l29#1.e" to "Once mental status changes (confusion, unsteady gait, unconsciousness), treat it as heat stroke, cool immediately, and evacuate. Do not wait for a thermometer.",
    "q.l29#2.p" to "What is the correct order of heat illness treatment?",
    "q.l29#2.o0" to "Move to shade, loosen clothing, cool physically, replace electrolytes",
    "q.l29#2.o1" to "Electrolytes first, then cool",
    "q.l29#2.o2" to "Give water first, then move to shade",
    "q.l29#2.o3" to "Massage the limbs first",
    "q.l29#2.e" to "Cooling comes before fluids: heat itself is damaging organs, and drinking takes time to work. Massaging the limbs can add to the circulatory load.",
    "q.l29#3.p" to "What is correct when a heat casualty is confused?",
    "q.l29#3.o0" to "Do not force fluids; apply wet cooling and evacuate as fast as possible",
    "q.l29#3.o1" to "Pour water into their mouth",
    "q.l29#3.o2" to "Give salt tablets",
    "q.l29#3.o3" to "Let them drink on their own",
    "q.l29#3.e" to "With altered consciousness the swallow reflex is unreliable and forced fluids risk aspiration. Cooling and professional rescue are the only effective measures.",
    "q.l29#4.p" to "A blister is affecting your walking. What is the correct treatment?",
    "q.l29#4.o0" to "Disinfect, drain from the edge, keep the roof and cover with a dressing",
    "q.l29#4.o1" to "Tear the whole thing off",
    "q.l29#4.o2" to "Puncture it in the middle with a needle",
    "q.l29#4.o3" to "Ignore it and keep walking",
    "q.l29#4.e" to "The blister roof is the best dressing you have and prevents infection. Puncturing the middle tears easily, and ripping it off exposes the wound to a dirty sock.",
    "q.l29#5.p" to "How is a first-degree burn (red, painful skin) treated in the field?",
    "q.l29#5.o0" to "Cool under running water for 20 minutes, then cover with a clean dressing",
    "q.l29#5.o1" to "Spread toothpaste on it",
    "q.l29#5.o2" to "Apply oil",
    "q.l29#5.o3" to "Wipe it with alcohol",
    "q.l29#5.e" to "Cool water carries away residual heat and limits tissue damage. Toothpaste and ointments trap heat and raise infection risk.",
    "q.l29#6.p" to "Why are sunburns worse at altitude than at sea level?",
    "q.l29#6.o0" to "UV is stronger and snow reflection doubles the exposure",
    "q.l29#6.o1" to "Because it is windier",
    "q.l29#6.o2" to "Because skin is thinner",
    "q.l29#6.o3" to "Because you sweat more",
    "q.l29#6.e" to "UV rises roughly 10-12% per 1,000 m, and snow reflects most of it back. Overcast and spindrift days burn you just as badly.",
    "q.l29#7.p" to "Which set of observations best tells you whether you are drinking enough?",
    "q.l29#7.o0" to "Urine colour, urine volume, resting heart rate, and mental state",
    "q.l29#7.o1" to "Changes in body weight",
    "q.l29#7.o2" to "Skin elasticity",
    "q.l29#7.o3" to "How thirsty you feel",
    "q.l29#7.e" to "Only the four together mean anything. Thirst alone or colour alone can both mislead, especially in the cold, where urine becomes concentrated.",
    "q.l29#8.p" to "A teammate has heat cramps (muscle spasms after heavy sweating). What is correct?",
    "q.l29#8.o0" to "Stop, move to shade, drink an electrolyte solution, and stretch gently",
    "q.l29#8.o1" to "Keep walking, it will pass",
    "q.l29#8.o2" to "Drink plain water only",
    "q.l29#8.o3" to "Rub the muscle hard",
    "q.l29#8.e" to "Heat cramps signal electrolyte loss. Plain water alone further dilutes blood sodium and can make things worse.",
    "q.l29#9.p" to "Which factors clearly raise the risk of heat illness?",
    "q.l29#9.o0" to "High humidity and no wind",
    "q.l29#9.o1" to "Wearing non-breathable clothing",
    "q.l29#9.o2" to "Too little sleep the night before",
    "q.l29#9.o3" to "Drinking only plain water after heavy sweating",
    "q.l29#9.e" to "All four weaken heat loss or electrolyte balance. Heat illness is never a single cause; it is several unfavourable conditions stacked up.",
    "q.l29#10.p" to "Which common injuries must be treated first in the field?",
    "q.l29#10.o0" to "Severe bleeding",
    "q.l29#10.o1" to "Moving a suspected spinal injury",
    "q.l29#10.o2" to "A foot wound that prevents walking",
    "q.l29#10.o3" to "A minor graze",
    "q.l29#10.e" to "Bleeding control, spinal protection, and restoring mobility belong to the get-worse-if-ignored category; a graze can wait until camp.",
    "q.l29#11.p" to "What should a small outdoor medical kit usually contain?",
    "q.l29#11.o0" to "Pain and fever relief",
    "q.l29#11.o1" to "Antihistamines",
    "q.l29#11.o2" to "Anti-diarrhoeals and oral rehydration salts",
    "q.l29#11.o3" to "Antibiotics (used at will)",
    "q.l29#11.e" to "The first three are symptom relief with clear uses and manageable risk. Antibiotics require a doctor's judgement; carrying them is not permission to take them.",
    "q.l29#12.p" to "What is the correct field sequence for heat stroke?",
    "q.l29#12.o0" to "Move to shade and remove excess clothing",
    "q.l29#12.o1" to "Pour cold water or apply ice to neck, armpits, and groin",
    "q.l29#12.o2" to "Monitor consciousness and breathing, prepare to call for help",
    "q.l29#12.o3" to "Evacuate as soon as possible, cooling continuously en route",
    "q.l29#12.e" to "The core of the sequence is that cooling never stops. Heat stroke mortality tracks how long the body stays hot, so keep cooling during transport.",
    "q.l29#13.p" to "What is the correct order for treating a foot blister?",
    "q.l29#13.o0" to "Wash hands and tools and disinfect",
    "q.l29#13.o1" to "Drain from the edge of the blister",
    "q.l29#13.o2" to "Keep the roof and cover with a dressing",
    "q.l29#13.o3" to "Change to dry socks and adjust the lacing",
    "q.l29#13.e" to "Infection is the main complication. Disinfect, keep the roof, keep it dry: all three are needed.",
    "q.l29#14.p" to "The core temperature threshold for heat stroke is ______ C (whole number).",
    "q.l29#14.a0" to "40",
    "q.l29#14.e" to "40 C plus altered mental status is the classic definition. Without a thermometer in the field, go by mental state.",
    "q.l29#15.p" to "After a burn, cool under running water for about ______ minutes.",
    "q.l29#15.a0" to "20",
    "q.l29#15.e" to "Twenty minutes effectively carries away residual heat. Any shorter and heat keeps conducting into deeper tissue.",
    "q.l29#16.p" to "One of the earliest reliable signs of dehydration is urine turning ______.",
    "q.l29#16.a0" to "dark",
    "q.l29#16.a1" to "dark yellow",
    "q.l29#16.a2" to "darker",
    "q.l29#16.e" to "Darker urine means it is concentrated. It is the cheapest indicator you can check yourself every day.",
    "q.l29#17.p" to "Match each grade of heat illness with its typical picture.",
    "q.l29#17.l0" to "Heat cramps",
    "q.l29#17.l1" to "Heat exhaustion",
    "q.l29#17.l2" to "Impending heat stroke",
    "q.l29#17.l3" to "Heat stroke",
    "q.l29#17.r0" to "Muscle spasms after heavy sweating, fully alert",
    "q.l29#17.r1" to "Weakness, dizziness, nausea, cool clammy skin",
    "q.l29#17.r2" to "Rising temperature, headache, uncoordinated movement",
    "q.l29#17.r3" to "Core temperature over 40 C with altered mental status",
    "q.l29#17.e" to "The four grades are one continuous deterioration, not four separate diseases. Which grade you are looking at decides whether you stop and drink or cool and call for help.",
    "q.l29#18.p" to "Match each injury with its field treatment.",
    "q.l29#18.l0" to "Severe bleeding",
    "q.l29#18.l1" to "Sprain",
    "q.l29#18.l2" to "Burn",
    "q.l29#18.l3" to "Suspected spinal injury",
    "q.l29#18.r0" to "Direct pressure, with a pressure bandage if needed",
    "q.l29#18.r1" to "Rest, ice, compression, elevation (RICE)",
    "q.l29#18.r2" to "Cool under water for 20 minutes, then a clean dressing",
    "q.l29#18.r3" to "Do not move; keep the spine aligned and call for help",
    "q.l29#18.e" to "All four share one idea: do the thing you cannot get wrong first. Pressure, immobilise, cool, do not move. Wait for professional judgement rather than inventing technique.",
    "q.l29#19.p" to "A teammate has had dark yellow urine, headache, and fatigue for two days. What is the most reasonable judgement?",
    "q.l29#19.o0" to "Treat as dehydration and observe, while watching for altitude illness",
    "q.l29#19.o1" to "It must be AMS, descend immediately",
    "q.l29#19.o2" to "They are just tired",
    "q.l29#19.o3" to "Give them coffee for energy",
    "q.l29#19.e" to "Dehydration and AMS overlap heavily, and the response does not conflict: fluids, rest, observation. If it does not improve with fluids, or walking becomes unsteady, treat as altitude illness.",
    "q.l29#20.p" to "Why is drink when you are thirsty not advised at altitude?",
    "q.l29#20.o0" to "Thirst lags behind actual fluid deficit, and breathing at altitude loses more water",
    "q.l29#20.o1" to "Because water is heavy",
    "q.l29#20.o2" to "Because drinking causes altitude sickness",
    "q.l29#20.o3" to "Because you will need the toilet constantly",
    "q.l29#20.e" to "Dry air and high respiratory volume mean large insensible losses. By the time you are thirsty, judgement is often already slipping.",
    "q.l29#21.p" to "After walking in strong sun, a teammate has a headache, nausea, and cool clammy skin. What is the first step?",
    "q.l29#21.o0" to "Stop immediately, move to shade, start cooling, and replace electrolytes",
    "q.l29#21.o1" to "Keep walking to camp",
    "q.l29#21.o2" to "Give a painkiller and carry on",
    "q.l29#21.o3" to "Have them put on more clothes to avoid a chill",
    "q.l29#21.e" to "These are the classic signs of heat exhaustion. Continuing to walk pushes it quickly toward heat stroke, which can kill within tens of minutes.",
    "q.l29#22.p" to "Which areas are most often missed when applying sun protection?",
    "q.l29#22.o0" to "Lips, sides of the nose, behind the ears, and under the chin",
    "q.l29#22.o1" to "The forearms",
    "q.l29#22.o2" to "The lower legs",
    "q.l29#22.o3" to "The back of the neck",
    "q.l29#22.e" to "These spots either lack melanin protection or catch reflected light from below. Once burned, eating, talking, and wearing a helmet all hurt.",
    "q.l30#0.p" to "Why is a first-aid kit split into three layers?",
    "q.l30#0.o0" to "Each layer serves a different job: personal, team, and base-camp medical",
    "q.l30#0.o1" to "So it looks organised",
    "q.l30#0.o2" to "To spread the weight",
    "q.l30#0.o3" to "To carry more medicine",
    "q.l30#0.e" to "The personal pouch must be reachable in thirty seconds, the team kit must handle fractures and hypothermia, and the base-camp box must last for days. Merge them into one bag and you cannot find anything when it matters.",
    "q.l30#1.p" to "Which group belongs in a personal carry pouch?",
    "q.l30#1.o0" to "Haemostatic dressing, blister plasters, painkillers, sunscreen",
    "q.l30#1.o1" to "Splints and a cervical collar",
    "q.l30#1.o2" to "An oxygen cylinder",
    "q.l30#1.o3" to "IV fluids",
    "q.l30#1.e" to "The pouch solves the need-it-now, must-be-small problem. Splints and oxygen belong at team level and cannot be carried personally.",
    "q.l30#2.p" to "What must a team first-aid kit never lack?",
    "q.l30#2.o0" to "Immobilisation and insulation gear (splint, emergency blanket)",
    "q.l30#2.o1" to "Adhesive plasters",
    "q.l30#2.o2" to "A thermometer",
    "q.l30#2.o3" to "Throat lozenges",
    "q.l30#2.e" to "At altitude, hypothermia and fractures are the two problems most needing field treatment. Immobilisation and insulation decide whether the casualty lasts until rescue.",
    "q.l30#3.p" to "What is the correct principle for prescription medication?",
    "q.l30#3.o0" to "Prescribed by a doctor with stated indications; team members do not recommend to each other",
    "q.l30#3.o1" to "Whoever has experience decides",
    "q.l30#3.o2" to "Take it by reading the leaflet",
    "q.l30#3.o3" to "Teammates can share among themselves",
    "q.l30#3.e" to "Altitude drugs carry many contraindications and interactions, and dose depends on the course. Handing medication to each other is the most common source of error in these incidents.",
    "q.l30#4.p" to "What is the correct use of a pulse oximeter?",
    "q.l30#4.o0" to "Watch the trend at the same altitude, not a single number",
    "q.l30#4.o1" to "Descend immediately if it reads below 90",
    "q.l30#4.o2" to "Only measure in daylight",
    "q.l30#4.o3" to "See who has the highest number",
    "q.l30#4.e" to "A single reading is heavily affected by temperature, peripheral circulation, and technique. Only a continuous fall plus symptoms is meaningful.",
    "q.l30#5.p" to "What matters most to settle in advance in an evacuation plan?",
    "q.l30#5.o0" to "Who has authority to decide, who is called, and where the casualty goes",
    "q.l30#5.o1" to "Who takes the photos",
    "q.l30#5.o2" to "Who carries the oxygen",
    "q.l30#5.o3" to "Who carries the cash",
    "q.l30#5.e" to "Evacuation decisions are most easily delayed under pressure. Naming the decision-maker and the contact chain in advance turns hours of discussion into ten minutes.",
    "q.l30#6.p" to "What is the key difference between the base-camp medical box and the team kit?",
    "q.l30#6.o0" to "Base camp can hold prescription drugs, monitoring equipment, and bulk supplies",
    "q.l30#6.o1" to "The base-camp one is lighter",
    "q.l30#6.o2" to "The base-camp one holds only plasters",
    "q.l30#6.o3" to "There is no difference",
    "q.l30#6.e" to "Base camp has a stable environment and a fixed crew, so it can support more complex material; the team kit must be light and carried on the body.",
    "q.l30#7.p" to "How should the medical role be assigned?",
    "q.l30#7.o0" to "Name a medical lead before departure and make sure everyone knows who it is",
    "q.l30#7.o1" to "See who knows something at the time",
    "q.l30#7.o2" to "Give it to the fittest person as an extra duty",
    "q.l30#7.o3" to "No role is needed",
    "q.l30#7.e" to "Without a clear role, everyone waits for someone else to decide. Naming a lead does not make them a doctor; it makes them responsible for assessment and communication.",
    "q.l30#8.p" to "Which categories are suitable to keep in a small emergency kit?",
    "q.l30#8.o0" to "Pain and fever relief",
    "q.l30#8.o1" to "Antihistamines",
    "q.l30#8.o2" to "Anti-diarrhoeals and oral rehydration salts",
    "q.l30#8.o3" to "Sedatives and sleeping pills",
    "q.l30#8.e" to "Sedatives suppress respiratory drive and are high-risk drugs at altitude. They must be a doctor's decision, never a self-carried standby.",
    "q.l30#9.p" to "What should go on the team medical card?",
    "q.l30#9.o0" to "Allergies",
    "q.l30#9.o1" to "Long-term medication and dosage",
    "q.l30#9.o2" to "Previous altitude illness",
    "q.l30#9.o3" to "Blood type",
    "q.l30#9.e" to "All four are used in an emergency. Blood type is almost never relevant to field transfusion, but it is useful information at a handover.",
    "q.l30#10.p" to "Which factors indicate that evacuation should start?",
    "q.l30#10.o0" to "Altered mental status",
    "q.l30#10.o1" to "Breathlessness at rest",
    "q.l30#10.o2" to "Unable to walk unaided",
    "q.l30#10.o3" to "A mild headache but eating and sleeping normally",
    "q.l30#10.e" to "The first three are cannot-wait signals. A mild headache can be observed, hydrated, and rested; evacuating for it also consumes rescue resources.",
    "q.l30#11.p" to "What is the correct order for handling a teammate with a suspected fracture?",
    "q.l30#11.o0" to "Confirm the scene is safe and prevent further injury",
    "q.l30#11.o1" to "Control bleeding and cover the wound",
    "q.l30#11.o2" to "Immobilise the limb and check distal circulation",
    "q.l30#11.o3" to "Insulate and arrange transport",
    "q.l30#11.e" to "Always check distal temperature, colour, and pulse after splinting, or a bandage tied too tight causes new injury.",
    "q.l30#12.p" to "What is the correct order for reporting and recording a medical event?",
    "q.l30#12.o0" to "Record time, place, symptoms, and treatment",
    "q.l30#12.o1" to "Notify the team medical lead",
    "q.l30#12.o2" to "Contact outside rescue or a doctor",
    "q.l30#12.o3" to "Hand over the record at transfer",
    "q.l30#12.e" to "Record before you call: with vague information, an outside doctor cannot advise. At handover the record is the most valuable thing you have.",
    "q.l30#13.p" to "A first-aid kit is usually split into a personal pouch, a team kit, and a ______ medical box.",
    "q.l30#13.a0" to "base camp",
    "q.l30#13.a1" to "camp",
    "q.l30#13.a2" to "base",
    "q.l30#13.e" to "Three tiers is the standard approach to kit design, and the organising idea is layering by how fast you need it.",
    "q.l30#14.p" to "To judge a change in altitude illness, look at the ______ in oxygen saturation rather than a single reading.",
    "q.l30#14.a0" to "trend",
    "q.l30#14.a1" to "trend over time",
    "q.l30#14.e" to "A trend is more reliable than an absolute value. A steady fall at the same altitude deserves more attention than one odd low number.",
    "q.l30#15.p" to "Match each tier of medical kit with its role.",
    "q.l30#15.l0" to "Personal pouch",
    "q.l30#15.l1" to "Team kit",
    "q.l30#15.l2" to "Base-camp medical box",
    "q.l30#15.l3" to "Evacuation paperwork",
    "q.l30#15.r0" to "Reachable in 30 seconds; bleeding, blisters, pain relief",
    "q.l30#15.r1" to "Splinting, wound cleaning, insulation, oxygen",
    "q.l30#15.r2" to "Prescription drugs, monitoring equipment, multi-day supplies",
    "q.l30#15.r3" to "Insurance policy, rescue numbers, medical records",
    "q.l30#15.e" to "All four share one idea: decide the layers beforehand. Digging through one big bag is slowest in exactly the minutes that matter most.",
    "q.l30#16.p" to "A teammate suggests bringing antibiotics to take if they feel unwell on the trip. What is the best response?",
    "q.l30#16.o0" to "Bring them, but a doctor must specify when to use them and for how long",
    "q.l30#16.o1" to "Bring them and take them as you like",
    "q.l30#16.o2" to "Do not bring them at all",
    "q.l30#16.o3" to "Bring steroids instead, they work better",
    "q.l30#16.e" to "What matters with antibiotics is the indication and the course. Bringing them with no clear rules is more dangerous than leaving them: stopping halfway breeds resistance and relapse.",
    "q.l30#17.p" to "At a 6,000 m camp a teammate is breathless at rest but saturation is 82% and they can still talk. What should you do?",
    "q.l30#17.o0" to "Treat as suspected HAPE: rest, oxygen, prepare to descend",
    "q.l30#17.o1" to "Observe for another day",
    "q.l30#17.o2" to "Tell them to drink more water",
    "q.l30#17.o3" to "Give a painkiller",
    "q.l30#17.e" to "Breathlessness at rest is a classic HAPE sign; no saturation number, however acceptable, overrides the symptom. Descent is the most definitive treatment.",
    "q.l30#18.p" to "Which two things are most often missing from a medical record, yet most important?",
    "q.l30#18.o0" to "Times and how the condition changed",
    "q.l30#18.o1" to "Name and age",
    "q.l30#18.o2" to "Blood type and weight",
    "q.l30#18.o3" to "Medication brand names",
    "q.l30#18.e" to "When it started and how it evolved is what drives the judgement. Without a timeline, a symptom description is almost unreadable.",
    "q.l30#19.p" to "What is the main use of the emergency blanket in a team kit?",
    "q.l30#19.o0" to "Reflect body heat and block wind, combined with insulation from the ground",
    "q.l30#19.o1" to "As a raincoat",
    "q.l30#19.o2" to "As a stretcher",
    "q.l30#19.o3" to "As a tent",
    "q.l30#19.e" to "An emergency blanket barely breathes, so wrapping it directly on the skin traps sweat. Used properly it goes under the casualty to block ground cold, blocks wind, and works with clothing.",
    "q.l30#20.p" to "Why run a medical drill before departure?",
    "q.l30#20.o0" to "So everyone knows where things are, who the roles are, and how the process runs",
    "q.l30#20.o1" to "For the photographs",
    "q.l30#20.o2" to "To use up medication",
    "q.l30#20.o3" to "It is unnecessary",
    "q.l30#20.e" to "The bottleneck in first aid is rarely knowledge; it is finding things and waiting for someone to decide. A drill compresses both into minutes.",
    "q.l30#21.p" to "A teammate hid an asthma history and only mentioned it after departure. What should you do?",
    "q.l30#21.o0" to "Assess their current condition, adjust the plan, and tell the medical lead",
    "q.l30#21.o1" to "Tell them off",
    "q.l30#21.o2" to "Carry on as planned",
    "q.l30#21.o3" to "Make them responsible for themselves",
    "q.l30#21.e" to "The risk of a hidden history is the wrong drug or a missed diagnosis in an emergency. Once known, add the information and change the plan rather than assign blame; blame only makes people less willing to speak.",
    "q.l31#0.p" to "What is the single strongest predictor of altitude illness?",
    "q.l31#0.o0" to "A previous history of altitude illness",
    "q.l31#0.o1" to "Age",
    "q.l31#0.o2" to "Fitness level",
    "q.l31#0.o3" to "Sex",
    "q.l31#0.e" to "A history matters because it reflects how that individual acclimatises. Anyone who has had AMS needs a more conservative ascent profile.",
    "q.l31#1.p" to "Which statement about fitness and altitude illness is correct?",
    "q.l31#1.o0" to "Being fit does not protect you, and can even be riskier because you climb faster",
    "q.l31#1.o1" to "The fitter you are, the safer you are",
    "q.l31#1.o2" to "The fitter you are, the more likely you are to get sick",
    "q.l31#1.o3" to "The two are completely unrelated",
    "q.l31#1.e" to "Fitness decides how fast you can walk; acclimatisation decides how high you can go. They are not the same thing, and treating fitness as a talisman is a common misjudgement.",
    "q.l31#2.p" to "Which of these clearly raises the risk of altitude illness?",
    "q.l31#2.o0" to "Going up with a respiratory infection",
    "q.l31#2.o1" to "Arriving a day early",
    "q.l31#2.o2" to "Drinking plenty of water",
    "q.l31#2.o3" to "Getting enough sleep",
    "q.l31#2.e" to "An infection leaves the alveoli and airways inflamed, which raises HAPE risk. Ascending before a cold has cleared is a common clinical trigger.",
    "q.l31#3.p" to "How does age relate to altitude illness risk?",
    "q.l31#3.o0" to "Age is not a major factor; individual variation matters far more",
    "q.l31#3.o1" to "Younger people are at more risk",
    "q.l31#3.o2" to "Older people are at more risk",
    "q.l31#3.o3" to "It depends only on age",
    "q.l31#3.e" to "The independent effect of age in the research is weak. What actually explains risk is history, rate of ascent, and general health.",
    "q.l31#4.p" to "What is the most effective prevention for someone prone to altitude illness?",
    "q.l31#4.o0" to "Slow the ascent and build in acclimatisation days",
    "q.l31#4.o1" to "Take painkillers in advance",
    "q.l31#4.o2" to "Carry more oxygen cylinders",
    "q.l31#4.o3" to "Train harder before the trip",
    "q.l31#4.e" to "Itinerary design is itself the most effective prevention. Drugs and oxygen are rescue measures; pace is the foundation.",
    "q.l31#5.p" to "What are the limits of acetazolamide?",
    "q.l31#5.o0" to "It eases symptoms and aids acclimatisation, but cannot replace ascent pace",
    "q.l31#5.o1" to "It lets you go straight to 5,000 m",
    "q.l31#5.o2" to "It cures HACE",
    "q.l31#5.o3" to "It has no side effects",
    "q.l31#5.e" to "It stimulates breathing by promoting bicarbonate excretion, so it assists acclimatisation. Using it to force a fast ascent only postpones the risk.",
    "q.l31#6.p" to "Why does sleeping altitude matter more than the highest point reached during the day?",
    "q.l31#6.o0" to "Ventilation drops at night and hypoxia is worst then, so sleep altitude sets overnight oxygen levels",
    "q.l31#6.o1" to "Because the bed is harder",
    "q.l31#6.o2" to "Because nights are colder",
    "q.l31#6.o3" to "Because poor sleep ruins your mood",
    "q.l31#6.e" to "Respiratory drive is lowest at night, when saturation falls most. Controlling the daily gain in sleeping altitude is the core of acclimatisation strategy.",
    "q.l31#7.p" to "What is the right attitude to a woman going to altitude during her period?",
    "q.l31#7.o0" to "Not a contraindication, but watch iron status and her individual response",
    "q.l31#7.o1" to "Absolutely not allowed",
    "q.l31#7.o2" to "She must take medication",
    "q.l31#7.o3" to "Exactly the same as men, nothing to watch",
    "q.l31#7.e" to "Menstruation is not a contraindication for altitude, but anaemia, heavy bleeding, and pain affect condition and judgement. An individual assessment beats a blanket rule.",
    "q.l31#8.p" to "Someone says they were completely fine at 5,000 m last time. Can the team ascend faster this trip?",
    "q.l31#8.o0" to "No; every trip can differ, so keep the standard pace",
    "q.l31#8.o1" to "Yes, they have experience",
    "q.l31#8.o2" to "Yes, twice as fast",
    "q.l31#8.o3" to "Yes, skip the acclimatisation days",
    "q.l31#8.e" to "Being symptom-free before only means slightly lower risk this time; it is not immunity. Treating last time as a guarantee is where many teams start to go wrong.",
    "q.l31#9.p" to "How well do children and teenagers acclimatise at altitude?",
    "q.l31#9.o0" to "Similarly to adults, but they describe symptoms less well, so watch them more closely",
    "q.l31#9.o1" to "Clearly worse",
    "q.l31#9.o2" to "Clearly better",
    "q.l31#9.o3" to "They cannot go to altitude at all",
    "q.l31#9.e" to "Physiological acclimatisation is similar; the difficulty is communication. Children cannot articulate a headache versus feeling unwell, so a change in behaviour is often the first signal.",
    "q.l31#10.p" to "Which practices count as a workable prevention pace?",
    "q.l31#10.o0" to "Above 3,000 m, gain no more than 500 m of sleeping altitude per day",
    "q.l31#10.o1" to "Take a rest day for every 1,000 m gained",
    "q.l31#10.o2" to "Climb high, sleep low",
    "q.l31#10.o3" to "Sleep at 4,000 m on the first night",
    "q.l31#10.e" to "The first three are accepted pacing rules. The first matters most because it governs where you sleep, not how far you walk.",
    "q.l31#11.p" to "Who needs a more conservative ascent plan?",
    "q.l31#11.o0" to "Anyone with a history of AMS or HAPE",
    "q.l31#11.o1" to "Anyone with a recent respiratory infection",
    "q.l31#11.o2" to "Anyone with sleep apnoea",
    "q.l31#11.o3" to "Anyone who runs marathons year round",
    "q.l31#11.e" to "The first three directly weaken overnight ventilation or previous acclimatisation. A good marathon time does not offset any of it.",
    "q.l31#12.p" to "Which preventive measures are non-pharmacological?",
    "q.l31#12.o0" to "Controlling the rate of ascent",
    "q.l31#12.o1" to "Avoiding alcohol and sedatives",
    "q.l31#12.o2" to "Ensuring carbohydrate intake and hydration",
    "q.l31#12.o3" to "Taking acetazolamide in advance",
    "q.l31#12.e" to "Alcohol and sedatives suppress respiratory drive and amplify night-time hypoxia. The last item is a drug, not a non-drug measure.",
    "q.l31#13.p" to "What is the correct sequence once AMS symptoms appear?",
    "q.l31#13.o0" to "Stop ascending and rest in place under observation",
    "q.l31#13.o1" to "Hydrate, keep eating, and stay warm",
    "q.l31#13.o2" to "Assess whether symptoms are worsening (steady gait, breathlessness at rest)",
    "q.l31#13.o3" to "If worse, descend immediately and seek medical support",
    "q.l31#13.e" to "The core rule is never ascend with symptoms. Observing is not the same as toughing it out; once danger signs appear, descent is mandatory.",
    "q.l31#14.p" to "Above 3,000 m, sleeping altitude should rise no more than ______ m per day.",
    "q.l31#14.a0" to "500",
    "q.l31#14.e" to "500 m is the common practice. Note that it limits where you sleep; you may climb higher during the day.",
    "q.l31#15.p" to "A rest day is advised roughly every ______ m of gain.",
    "q.l31#15.a0" to "1000",
    "q.l31#15.a1" to "1 000",
    "q.l31#15.a2" to "1,000",
    "q.l31#15.e" to "One rest day per 1,000 m is a common rhythm, adjusted for individual response and route conditions.",
    "q.l31#16.p" to "Match each risk factor with the illness it mainly affects.",
    "q.l31#16.l0" to "Rapid ascent",
    "q.l31#16.l1" to "Respiratory infection",
    "q.l31#16.l2" to "Previous HAPE",
    "q.l31#16.l3" to "Sleep apnoea",
    "q.l31#16.r0" to "A shared trigger for AMS and HACE",
    "q.l31#16.r1" to "Mainly raises HAPE risk",
    "q.l31#16.r2" to "The strongest predictor of HAPE recurring",
    "q.l31#16.r3" to "Worse night-time hypoxia, impairing acclimatisation",
    "q.l31#16.e" to "All four point at the same thing: the load on overnight ventilation and the pulmonary circulation. Knowing which one applies to you is how you set the right pace.",
    "q.l31#17.p" to "Match each preventive measure with what it is.",
    "q.l31#17.l0" to "Controlling the rate of ascent",
    "q.l31#17.l1" to "Acclimatisation days",
    "q.l31#17.l2" to "Acetazolamide",
    "q.l31#17.l3" to "Dexamethasone",
    "q.l31#17.r0" to "Itinerary design, the most fundamental prevention",
    "q.l31#17.r1" to "Itinerary design, trading time for acclimatisation",
    "q.l31#17.r2" to "Assists acclimatisation; prescription drug",
    "q.l31#17.r3" to "Treatment drug, not for routine prevention",
    "q.l31#17.e" to "The first two need no doctor; the last two do. Treating a treatment drug as prevention is a very risky habit.",
    "q.l31#18.p" to "One team member is clearly more susceptible than the others. What is the most sensible arrangement?",
    "q.l31#18.o0" to "Keep them in the front half but on the slowest pace, with a descent point agreed in advance",
    "q.l31#18.o1" to "Put them at the back",
    "q.l31#18.o2" to "Have them take more medication",
    "q.l31#18.o3" to "Persuade them not to come",
    "q.l31#18.e" to "One pace for all, a visible position, and a clear turn-around point are far more practical than talking someone out of the trip. Leaving them at the back is the arrangement most likely to go wrong.",
    "q.l31#19.p" to "What is wrong with saying I took acetazolamide last time, so I will just start it myself this time?",
    "q.l31#19.o0" to "Use requires a doctor to assess indication, dose, and contraindications; experience alone is not enough",
    "q.l31#19.o1" to "The drug is too expensive",
    "q.l31#19.o2" to "It makes you drowsy",
    "q.l31#19.o3" to "Nothing is wrong with it",
    "q.l31#19.e" to "Sulfonamide allergy, kidney function, and interactions with other medication all change the decision. Experience can suggest it might help; it cannot replace assessment.",
    "q.l31#20.p" to "A team member has AMS at 4,500 m but insists on continuing to 5,000 m as planned. What should the leader do?",
    "q.l31#20.o0" to "Refuse clearly and offer alternatives: acclimatise in place or descend",
    "q.l31#20.o1" to "Let them decide for themselves",
    "q.l31#20.o2" to "Add medication and let them go",
    "q.l31#20.o3" to "Take the whole team up with them",
    "q.l31#20.e" to "Never ascend with symptoms is a hard rule and cannot be overridden by a vote or willpower. Offering alternatives is easier to accept than a flat refusal.",
    "q.l31#21.p" to "Which statement about eating and drinking at altitude is correct?",
    "q.l31#21.o0" to "Drink proactively in small amounts, favour carbohydrates, and keep your appetite",
    "q.l31#21.o1" to "Drink less to avoid toilet trips",
    "q.l31#21.o2" to "Eat only high-protein food",
    "q.l31#21.o3" to "Replace meals with coffee",
    "q.l31#21.e" to "Dehydration and loss of appetite both slow acclimatisation. At altitude, being able to eat and drink is itself a skill.",
    "q.l31#22.p" to "Which preventive rule is most often overlooked yet most important for HAPE?",
    "q.l31#22.o0" to "Do not go to altitude with an unresolved cold",
    "q.l31#22.o1" to "Bring an extra layer",
    "q.l31#22.o2" to "Carry a pulse oximeter",
    "q.l31#22.o3" to "Book accommodation in advance",
    "q.l31#22.e" to "Respiratory infection is an important HAPE trigger, and it is usually dismissed as a minor ailment. This rule gives an enormous return for almost no effort.",
    "q.m09#12.p" to "What is the usual adult dose of acetazolamide for prevention?",
    "q.m09#12.o0" to "125 mg twice daily",
    "q.m09#12.o1" to "500 mg once daily",
    "q.m09#12.o2" to "1,000 mg once daily",
    "q.m09#12.o3" to "As needed",
    "q.m09#12.e" to "125 mg twice daily is the dose used in the handbook. It is a prescription drug, and contraindications and side effects need a doctor's assessment.",
    "q.m09#13.p" to "What are common side effects of acetazolamide?",
    "q.m09#13.o0" to "Tingling in hands and feet, altered taste (especially for fizzy drinks), and increased urination",
    "q.m09#13.o1" to "Drowsiness",
    "q.m09#13.o2" to "A racing heartbeat",
    "q.m09#13.o3" to "Raised blood pressure",
    "q.m09#13.e" to "These are usually tolerable but affect drinking and sleep. It is contraindicated in sulfonamide allergy.",
    "q.m09#14.p" to "What is the usual dose of dexamethasone for HACE?",
    "q.m09#14.o0" to "4 mg every 6 hours",
    "q.m09#14.o1" to "1 mg once daily",
    "q.m09#14.o2" to "20 mg every 12 hours",
    "q.m09#14.o3" to "A single dose as needed",
    "q.m09#14.e" to "4 mg every 6 hours is the handbook dose. It is a treatment drug and never a substitute for descent.",
    "q.m09#15.p" to "What is nifedipine mainly used for?",
    "q.m09#15.o0" to "Prevention and treatment of HAPE",
    "q.m09#15.o1" to "AMS",
    "q.m09#15.o2" to "Frostbite",
    "q.m09#15.o3" to "Dehydration",
    "q.m09#15.e" to "Nifedipine works by lowering pulmonary vascular resistance, commonly 20-30 mg every 12 hours. It does not treat AMS.",
    "q.m09#16.p" to "Symptoms clearly improve after dexamethasone. What is the most correct action?",
    "q.m09#16.o0" to "Still descend; the drug only buys time",
    "q.m09#16.o1" to "Cancel the descent",
    "q.m09#16.o2" to "Keep ascending",
    "q.m09#16.o3" to "Stop the drug and observe",
    "q.m09#16.e" to "Steroids mask symptoms while the disease keeps progressing. Continuing upward after relief is the most dangerous misjudgement.",
    "q.m09#17.p" to "Why does carrying the drug not mean knowing how to use it?",
    "q.m09#17.o0" to "Dose, indication, and contraindications need a doctor; teammates should not recommend drugs to each other",
    "q.m09#17.o1" to "Because drugs expire",
    "q.m09#17.o2" to "Because they are heavy",
    "q.m09#17.o3" to "Because leaflets are hard to understand",
    "q.m09#17.e" to "Altitude medication is full of traps: sulfonamide allergy, asthma, polypharmacy. Taking a drug without assessment can carry more risk than benefit.",
    "q.m09#18.p" to "What is the role of aspirin at altitude?",
    "q.m09#18.o0" to "Relieves headache; it is symptom relief and does not change the course",
    "q.m09#18.o1" to "Prevents HAPE",
    "q.m09#18.o2" to "Treats HACE",
    "q.m09#18.o3" to "Raises oxygen saturation",
    "q.m09#18.e" to "Be clear about what symptom relief means: it makes you more comfortable, which does not mean you can keep ascending.",
    "q.m09#19.p" to "When is taking no medication and descending promptly the safest choice?",
    "q.m09#19.o0" to "When symptoms are severe, the cause is unclear, or there is no medical guidance",
    "q.m09#19.o1" to "At all times",
    "q.m09#19.o2" to "Only with mild symptoms",
    "q.m09#19.o3" to "Only when descent is easy",
    "q.m09#19.e" to "Descent is the only reliably effective measure. Once medication becomes guesswork, descending is always the safer path.",
    "q.m10#12.p" to "When relative humidity approaches saturation, what does that most directly mean for the weather?",
    "q.m10#12.o0" to "The cloud base drops, and fog and precipitation become likely",
    "q.m10#12.o1" to "The temperature rises",
    "q.m10#12.o2" to "The wind drops",
    "q.m10#12.o3" to "The pressure rises",
    "q.m10#12.e" to "Saturation means water vapour starts condensing. When climbing, a rapidly dropping cloud base often shows up before the rain does.",
    "q.m10#13.p" to "What usually follows the passage of a cold front?",
    "q.m10#13.o0" to "Falling temperature, a wind shift, and improving visibility",
    "q.m10#13.o1" to "Rising temperature",
    "q.m10#13.o2" to "Continuous rain",
    "q.m10#13.o3" to "Lighter wind",
    "q.m10#13.e" to "Behind the front you often get good weather that is very cold and windy. That is why teams underestimate wind chill when conditions seem to be improving.",
    "q.m10#14.p" to "What do orographic clouds hugging the mountainside mean for climbers?",
    "q.m10#14.o0" to "Strong wind and high humidity; the ridge may already be impassable",
    "q.m10#14.o1" to "Nothing but scenery",
    "q.m10#14.o2" to "The weather is stable",
    "q.m10#14.o3" to "Nothing to do with wind",
    "q.m10#14.e" to "Orographic cloud makes wind and moisture visible. If the cloud is racing across, assume ridge winds are over the limit.",
    "q.m10#15.p" to "Why does a forecast become less reliable the further ahead it goes?",
    "q.m10#15.o0" to "The atmosphere is chaotic, so error grows exponentially with time",
    "q.m10#15.o1" to "Because the models are poor",
    "q.m10#15.o2" to "Because the data are incomplete",
    "q.m10#15.o3" to "Because of the altitude",
    "q.m10#15.e" to "Trends within three days are fairly trustworthy; beyond seven they are only a reference. Build waiting time for a window into the itinerary.",
    "q.m10#16.p" to "Where does the difference between a mountain weather station and the altitude you are heading for mainly come from?",
    "q.m10#16.o0" to "Temperature, wind speed, and precipitation type change with altitude",
    "q.m10#16.o1" to "Instrument error",
    "q.m10#16.o2" to "Time zones",
    "q.m10#16.o3" to "Latitude",
    "q.m10#16.e" to "Light rain at a valley station can be heavy snow and strong wind at 5,000 m. Any forecast has to be converted for height.",
    "q.m10#17.p" to "You hear thunder within 30 seconds of seeing lightning. What does that mean?",
    "q.m10#17.o0" to "The storm is already very close; leave exposed terrain immediately",
    "q.m10#17.o1" to "The storm is far away",
    "q.m10#17.o2" to "You are safe",
    "q.m10#17.o3" to "It is coincidence",
    "q.m10#17.e" to "The gap between light and sound gives a distance estimate. The shorter the gap the closer the storm, and 30 seconds is a common threshold for acting.",
    "q.m10#18.p" to "Why are summit pushes usually scheduled for the early hours?",
    "q.m10#18.o0" to "The snow surface is frozen and firmer, and cloud and wind usually build in the afternoon",
    "q.m10#18.o1" to "For the photographs",
    "q.m10#18.o2" to "Because there are fewer people",
    "q.m10#18.o3" to "Because guides are used to it",
    "q.m10#18.e" to "Firm early-morning snow and a stable weather window are the main reasons. The cost is cold and lost sleep, so prepare for both.",
    "q.m10#19.p" to "When the weather window narrows, what should be given up first?",
    "q.m10#19.o0" to "The summit objective, never the safety margin",
    "q.m10#19.o1" to "Insulation",
    "q.m10#19.o2" to "Backup equipment",
    "q.m10#19.o3" to "Communication devices",
    "q.m10#19.e" to "When the window is too small, what usually gets squeezed is the margin, and that is exactly how incidents begin. Give up the objective first.",
    "q.m11#12.p" to "Why is the south side of Yuzhu Peak a good first 6,000 m objective?",
    "q.m11#12.o0" to "Gentler snow slopes, accessible transport, and an established route",
    "q.m11#12.o1" to "Because it is the highest",
    "q.m11#12.o2" to "Because it is the most technical",
    "q.m11#12.o3" to "Because it is quiet",
    "q.m11#12.e" to "The goal of a first 6,000 m peak is to validate acclimatisation and fitness, not to test technique. An established route reduces the unknowns.",
    "q.m11#13.p" to "Which range is Nyainqentanglha (Qizi) Peak in?",
    "q.m11#13.o0" to "Nyainqentanglha Range",
    "q.m11#13.o1" to "Kunlun Range",
    "q.m11#13.o2" to "Himalaya",
    "q.m11#13.o3" to "Karakoram",
    "q.m11#13.e" to "Qizi sits in Damxung, Tibet, in the Nyainqentanglha Range. The range sets the climate and the seasonal window, which is key background when choosing a peak.",
    "q.m11#14.p" to "What is Lobuche East most typically used for?",
    "q.m11#14.o0" to "A transition and skills peak between 6,000 m and 8,000 m",
    "q.m11#14.o1" to "A tourist route",
    "q.m11#14.o2" to "A ski resort",
    "q.m11#14.o3" to "A viewpoint",
    "q.m11#14.e" to "It sits right beside the Everest trekking route, with steeper snow and easy access, which is why it is a common stepping-stone peak.",
    "q.m11#15.p" to "What is the technical character of Island Peak (Imja Tse)?",
    "q.m11#15.o0" to "Roped travel and crevasse navigation; a classic technical 6,000 m peak",
    "q.m11#15.o1" to "A pure trek",
    "q.m11#15.o2" to "Snow walking only",
    "q.m11#15.o3" to "No snow at any time of year",
    "q.m11#15.e" to "Its technical demands come from the glacier and crevasses rather than rock walls. Roped travel and crevasse rescue are essential skills.",
    "q.m11#16.p" to "When choosing a 6,000 m peak, what deserves more attention than the altitude?",
    "q.m11#16.o0" to "Route character (snow slope, glacier, rock) and how hard retreat would be",
    "q.m11#16.o1" to "Whether the name sounds good",
    "q.m11#16.o2" to "How far away it is",
    "q.m11#16.o3" to "The cost",
    "q.m11#16.e" to "Two 6,100 m peaks can differ by an order of magnitude depending on whether the route is snow or glacier. Look at the character first, the altitude second.",
    "q.m11#17.p" to "Permit and guide requirements at 6,000 m are usually what compared with 5,000 m?",
    "q.m11#17.o0" to "Stricter, often requiring registration or a mandatory guide",
    "q.m11#17.o1" to "Looser",
    "q.m11#17.o2" to "Exactly the same",
    "q.m11#17.o3" to "Non-existent",
    "q.m11#17.e" to "The higher and more remote the route, the tighter the administration. Confirming the rules before you leave is far easier than asking at the trailhead.",
    "q.m11#18.p" to "Why should you assume crevasses are there on a 6,000 m peak?",
    "q.m11#18.o0" to "Snow bridges hide them from view, so you must rope up as if they exist",
    "q.m11#18.o1" to "Because they certainly exist",
    "q.m11#18.o2" to "Because the guide requires it",
    "q.m11#18.o3" to "Because insurance requires it",
    "q.m11#18.e" to "Not seeing something is not the same as it not being there. Roping up costs little; falling into a crevasse costs a great deal.",
    "q.m11#19.p" to "How does the acclimatisation schedule at 6,000 m usually compare with 5,000 m?",
    "q.m11#19.o0" to "Longer, because sleeping altitude is higher and recovery is slower",
    "q.m11#19.o1" to "Shorter",
    "q.m11#19.o2" to "The same",
    "q.m11#19.o3" to "Not needed",
    "q.m11#19.e" to "Every step up in altitude adds acclimatisation time. Transplanting a 5,000 m schedule straight to 6,000 m is a common underestimation.",
    "q.m12#16.p" to "What is the theoretical mechanical advantage of a 3:1 system?",
    "q.m12#16.o0" to "Pulling 1 m of rope raises the load about 1/3 m",
    "q.m12#16.o1" to "The load is halved",
    "q.m12#16.o2" to "The speed is unchanged",
    "q.m12#16.o3" to "No prusik is needed",
    "q.m12#16.e" to "Mechanical advantage equals the number of loaded rope strands. 3:1 means your effort is about a third of the load, ignoring friction.",
    "q.m12#17.p" to "In real rescue work, how efficient is a 5:1 system usually?",
    "q.m12#17.o0" to "Below the theoretical value, because pulleys and rope lose energy to friction",
    "q.m12#17.o1" to "Above the theoretical value",
    "q.m12#17.o2" to "Exactly the theoretical value",
    "q.m12#17.o3" to "Friction plays no part",
    "q.m12#17.e" to "Every pulley loses some effort to friction, and real efficiency is often only 60-70% of the theoretical figure. Build in a margin.",
    "q.m12#18.p" to "What is the main cost of using a carabiner instead of a pulley as a redirect?",
    "q.m12#18.o0" to "Much more friction and lower efficiency",
    "q.m12#18.o1" to "Insufficient strength",
    "q.m12#18.o2" to "It wears the harness",
    "q.m12#18.o3" to "It cannot be locked",
    "q.m12#18.e" to "A carabiner redirects but does not reduce friction, so part of your pull is eaten by it. Use a pulley when you have one.",
    "q.m12#19.p" to "What does the one-way prusik do in a rescue system?",
    "q.m12#19.o0" to "It locks on the return stroke so the load cannot slip back",
    "q.m12#19.o1" to "Increases strength",
    "q.m12#19.o2" to "Reduces friction",
    "q.m12#19.o3" to "Joins two ropes",
    "q.m12#19.e" to "Without a prusik the load slides back every time you release. The prusik is what turns intermittent pulls into net progress.",
    "q.m12#20.p" to "Why does a rescue system need a backup prusik?",
    "q.m12#20.o0" to "The primary can slip or fail, and the backup is the last safeguard",
    "q.m12#20.o1" to "So it looks right",
    "q.m12#20.o2" to "To add pulling power",
    "q.m12#20.o3" to "To save rope",
    "q.m12#20.e" to "Prusik reliability depends on matching rope diameter and on rope condition. In critical systems, two prusiks is standard practice.",
    "q.m12#21.p" to "When hauling an injured climber, the system should where possible do what?",
    "q.m12#21.o0" to "Follow the terrain, so the casualty does not hit rock walls or cornices",
    "q.m12#21.o1" to "Haul as high as possible",
    "q.m12#21.o2" to "Haul as fast as possible",
    "q.m12#21.o3" to "Lift vertically",
    "q.m12#21.e" to "Hauling injuries usually come from collisions, not from the pull itself. Route planning and anchor placement matter just as much.",
    "q.m12#22.p" to "What is the cost of a 6:1 compound system compared with 3:1?",
    "q.m12#22.o0" to "More equipment, slower to set up, and much more rope consumed",
    "q.m12#22.o1" to "Less effort and faster",
    "q.m12#22.o2" to "No cost at all",
    "q.m12#22.o3" to "It cannot be recovered",
    "q.m12#22.e" to "The higher the mechanical advantage, the more complex the setup and the more rope it eats. In rescue, fast often matters more than easy.",
    "q.m12#23.p" to "When a system has to be converted mid-operation, what is the most basic requirement?",
    "q.m12#23.o0" to "Something is loaded at every moment, with no unclipped gap",
    "q.m12#23.o1" to "Move quickly",
    "q.m12#23.o2" to "Two people working together",
    "q.m12#23.o3" to "Use the same rope",
    "q.m12#23.e" to "Conversions are a high-incident moment in rescue. Whenever you dismantle the old, establish the new connection first.",
    "q.m12#24.p" to "How should a rope running over a sharp edge be handled?",
    "q.m12#24.o0" to "Add edge protection or change the line so the sheath is not cut",
    "q.m12#24.o1" to "Run it straight over",
    "q.m12#24.o2" to "Tension it more",
    "q.m12#24.o3" to "Substitute webbing",
    "q.m12#24.e" to "A loaded rope cut through its sheath loses strength abruptly. Edge protection costs almost nothing; the alternative can be a rope, or a fall.",
    "q.m12#25.p" to "Why are anchor requirements for a rescue system higher than for a normal belay station?",
    "q.m12#25.o0" to "It takes static load plus dynamic surges, and there is usually only one system",
    "q.m12#25.o1" to "Because it is more important",
    "q.m12#25.o2" to "Because there are more people",
    "q.m12#25.o3" to "Because of rope length",
    "q.m12#25.e" to "In rescue there is no second belay station as a backstop. Anchor failure means two people go down together.",
    "q.m12#26.p" to "When estimating the force needed to haul, what must be added to the mechanical advantage?",
    "q.m12#26.o0" to "Weight of casualty and gear, rope and pulley friction, and terrain drag",
    "q.m12#26.o1" to "The weather",
    "q.m12#26.o2" to "The time",
    "q.m12#26.o3" to "Teammates' body weight",
    "q.m12#26.e" to "Theoretical pull is routinely underestimated. Add friction and terrain and the real force needed can be twice the theoretical figure.",
    "q.m12#27.p" to "Once the system is built, what should you do first?",
    "q.m12#27.o0" to "Test haul it unloaded to confirm the line, prusiks, and anchors all behave",
    "q.m12#27.o1" to "Start hauling a person immediately",
    "q.m12#27.o2" to "Take a photo",
    "q.m12#27.o3" to "Coil the rope",
    "q.m12#27.e" to "An unloaded test haul catches about 80% of rigging errors. Ten seconds here can save you a system failure.",
    "q.m13#14.p" to "What is the correct sequence for ascending on prusiks?",
    "q.m13#14.o0" to "Stand up (slide the top prusik up), sit back (transfer weight), slide the lower prusik up, repeat",
    "q.m13#14.o1" to "Slide both prusiks at the same time",
    "q.m13#14.o2" to "Only slide the top prusik",
    "q.m13#14.o3" to "Pull with your arms",
    "q.m13#14.e" to "The stand, sit, slide cycle transfers your weight between the upper and lower prusiks. Sliding both at once and you drop straight back.",
    "q.m13#15.p" to "What is the purpose of the foot loop when self-rescuing?",
    "q.m13#15.o0" to "It puts your weight on your legs and spares your arms",
    "q.m13#15.o1" to "Adds friction",
    "q.m13#15.o2" to "Connects the harness",
    "q.m13#15.o3" to "Marks the height",
    "q.m13#15.e" to "Arm-only hauling exhausts you within tens of metres. The foot loop brings the legs in, and that decides whether you get out.",
    "q.m13#16.p" to "In a roped-team rescue, what comes first?",
    "q.m13#16.o0" to "Arrest and secure, so the fallen climber stops sliding",
    "q.m13#16.o1" to "Go straight down into the crevasse",
    "q.m13#16.o2" to "Call for rescue",
    "q.m13#16.o3" to "Photograph the scene",
    "q.m13#16.e" to "The arrest is the one thing that cannot wait. Communication, systems, and hauling come after the load is secured.",
    "q.m13#17.p" to "When someone is hanging in a crevasse, which injuries demand the most attention?",
    "q.m13#17.o0" to "Hypothermia, rope pressure, and impact injuries",
    "q.m13#17.o1" to "Sunburn",
    "q.m13#17.o2" to "Altitude illness",
    "q.m13#17.o3" to "Dehydration",
    "q.m13#17.e" to "It is extremely cold inside a crevasse, and suspension also restricts circulation. The rescue has to be fast, not merely effective.",
    "q.m13#18.p" to "Why give the fallen climber a self-anchor first?",
    "q.m13#18.o0" to "So they no longer depend on the main rope and the rescuer's hands are free to build a system",
    "q.m13#18.o1" to "Because the rope is not trusted",
    "q.m13#18.o2" to "Because the rules say so",
    "q.m13#18.o3" to "Because there is no other gear",
    "q.m13#18.e" to "A self-anchor (prusik or ice axe) stabilises their position and also gives them something to do, which reduces panic.",
    "q.m13#19.p" to "What is the right way to haul out a casualty who cannot move?",
    "q.m13#19.o0" to "Build a 3:1 or 5:1 system and haul from above",
    "q.m13#19.o1" to "Pull the rope by hand",
    "q.m13#19.o2" to "Have the casualty climb out",
    "q.m13#19.o3" to "Wrap the rope around your waist",
    "q.m13#19.e" to "Hand hauling is nearly impossible and you lose control. A systematic haul is the only reliable method.",
    "q.m13#20.p" to "Where does the time pressure in a rescue come from?",
    "q.m13#20.o0" to "Rate of cooling, changing weather, and the team running out of strength",
    "q.m13#20.o1" to "Strength alone",
    "q.m13#20.o2" to "Weather alone",
    "q.m13#20.o3" to "Cold alone",
    "q.m13#20.e" to "All three act at once. A rescue plan has to answer how long it will take, not just whether it is possible.",
    "q.m13#21.p" to "Which means of communication is least reliable during a rescue?",
    "q.m13#21.o0" to "Shouting across a small snow ridge",
    "q.m13#21.o1" to "Two-way radio",
    "q.m13#21.o2" to "Rope signals",
    "q.m13#21.o3" to "Whistle",
    "q.m13#21.e" to "Wind, rope length, and terrain swallow voices. Agreeing rope or whistle signals in advance beats shouting on the spot.",
    "q.m13#22.p" to "Why practise self-rescue skills to the point of automaticity on safe terrain?",
    "q.m13#22.o0" to "In a real fall, fear occupies your attention and only automatic actions get executed",
    "q.m13#22.o1" to "To pass an exam",
    "q.m13#22.o2" to "For speed",
    "q.m13#22.o3" to "So it looks good",
    "q.m13#22.e" to "This is the logic behind all rescue training: drill the movement until it needs no thought, and you have capacity left to observe and judge.",
    "q.m13#23.p" to "In a roped-team rescue, what is the second climber's main job?",
    "q.m13#23.o0" to "Help with the arrest, prepare the system, and watch for hazards above",
    "q.m13#23.o1" to "Take photographs",
    "q.m13#23.o2" to "Keep moving",
    "q.m13#23.o3" to "Coil the rope",
    "q.m13#23.e" to "This is exactly why a team of three works: one arrests, one builds the system, one watches above. With two, you have to cover both.",
    "q.m13#24.p" to "If the fallen climber is unresponsive, what is the priority?",
    "q.m13#24.o0" to "Get them out and start first aid as fast as possible while calling for outside help",
    "q.m13#24.o1" to "Build a 5:1 system first",
    "q.m13#24.o2" to "Wait for rescue",
    "q.m13#24.o3" to "Record everything first",
    "q.m13#24.e" to "Unresponsive means a very short window. Here fast outranks easy, and the simplest workable system is the right one.",
    "q.m13#25.p" to "After a rescue, which step is most often skipped?",
    "q.m13#25.o0" to "Reviewing the system and process and writing the problems down",
    "q.m13#25.o1" to "Coiling the rope",
    "q.m13#25.o2" to "Descending",
    "q.m13#25.o3" to "Eating",
    "q.m13#25.e" to "The gap between drill and reality shows up in the debrief: which step was slow, which knot was wrong, which instruction nobody heard.",
    "q.m13#26.p" to "Why should a rescue system be independent of the main rope?",
    "q.m13#26.o0" to "The main rope may be damaged by ice debris or sharp edges, and it is still loaded",
    "q.m13#26.o1" to "Because the rules say so",
    "q.m13#26.o2" to "Because it is longer",
    "q.m13#26.o3" to "Because it is lighter",
    "q.m13#26.e" to "Hanging a rescue system on a damaged, loaded main rope stacks one risk on another.",
    "q.m13#27.p" to "In crevasse terrain, what should the team settle in advance?",
    "q.m13#27.o0" to "Who arrests, who builds the system, and how you communicate",
    "q.m13#27.o1" to "Who walks in front",
    "q.m13#27.o2" to "Who carries the most weight",
    "q.m13#27.o3" to "Who takes photos",
    "q.m13#27.e" to "Assign the roles before departure. In the first thirty seconds of a fall nobody has time to discuss who does what.",
    "q.m14#17.p" to "How does sunk cost typically show up in climbing decisions?",
    "q.m14#17.o0" to "We have spent this much money and time, so we cannot go home empty-handed",
    "q.m14#17.o1" to "The forecast is wrong",
    "q.m14#17.o2" to "Not enough equipment",
    "q.m14#17.o3" to "Teammates are too slow",
    "q.m14#17.e" to "The more you have invested, the harder it is to walk away. But what you have already spent is not recovered by continuing; it only adds new risk.",
    "q.m14#18.p" to "When is groupthink most likely?",
    "q.m14#18.o0" to "High cohesion, no dissenting voice, and a leader who states a position too early",
    "q.m14#18.o1" to "When the team is deeply divided",
    "q.m14#18.o2" to "When the group is small",
    "q.m14#18.o3" to "In bad weather",
    "q.m14#18.e" to "Cohesion is good, but it suppresses dissent. Letting the youngest speak first and appointing a devil's advocate are standard countermeasures.",
    "q.m14#19.p" to "What is confirmation bias?",
    "q.m14#19.o0" to "Seeking only information that supports your view and ignoring contrary evidence",
    "q.m14#19.o1" to "Being unable to remember information",
    "q.m14#19.o2" to "Being over-cautious",
    "q.m14#19.o3" to "Depending on others",
    "q.m14#19.e" to "If you want to climb today, you will only notice the signs that support it. Actively hunting for counter-examples is the only antidote.",
    "q.m14#20.p" to "Why use a checklist for major decisions?",
    "q.m14#20.o0" to "Fatigue and pressure make you skip items; a list turns remembering into item-by-item confirmation",
    "q.m14#20.o1" to "For the record",
    "q.m14#20.o2" to "To look professional",
    "q.m14#20.o3" to "Because the rules require it",
    "q.m14#20.e" to "A checklist does not replace judgement; it makes sure all the information that judgement needs is present.",
    "q.m14#21.p" to "What is an example of anchoring on a climb?",
    "q.m14#21.o0" to "Treating the planned six hours to camp as the standard and ignoring actual conditions",
    "q.m14#21.o1" to "Trusting the guide",
    "q.m14#21.o2" to "Reading the map",
    "q.m14#21.o3" to "Taking your temperature",
    "q.m14#21.e" to "Once an anchor exists, later judgements adjust around it. Base decisions on actual progress, not on the planned figure.",
    "q.m14#22.p" to "What is the value of recording a decision (time, reasoning, conclusion)?",
    "q.m14#22.o0" to "It gives the debrief evidence and gives the team a shared understanding of the same facts",
    "q.m14#22.o1" to "For the report",
    "q.m14#22.o2" to "For insurance",
    "q.m14#22.o3" to "For a book",
    "q.m14#22.e" to "Without a record, a debrief becomes everyone telling a different story. A written timeline shows which point could have been decided earlier.",
    "q.m14#23.p" to "What specific risk does the expert halo create?",
    "q.m14#23.o0" to "Nobody dares question an obvious error, and the error is carried out smoothly",
    "q.m14#23.o1" to "The expert gets tired",
    "q.m14#23.o2" to "Experts are expensive",
    "q.m14#23.o3" to "The expert does not know the route",
    "q.m14#23.e" to "The halo suppresses information rising to the surface. The most dangerous state on a team is not nobody knowing, but nobody daring to speak.",
    "q.m17#16.p" to "What is the purpose of rotating supplies between high camps?",
    "q.m17#16.o0" to "So each camp holds just enough, with no pile-up in one place and no shortage in another",
    "q.m17#16.o1" to "To reduce weight",
    "q.m17#16.o2" to "To make counting easier",
    "q.m17#16.o3" to "For compliance",
    "q.m17#16.e" to "Expedition supplies are rationed leg by leg. Without a rotation sheet, the usual outcome is discovering a fuel shortage at high camp the day before the summit push.",
    "q.m17#17.p" to "How should camp fuel be estimated?",
    "q.m17#17.o0" to "People x days x daily use per person (melting snow dominates)",
    "q.m17#17.o1" to "By number of canisters",
    "q.m17#17.o2" to "By weight",
    "q.m17#17.o3" to "By feel",
    "q.m17#17.e" to "Melting snow for water is the largest fuel cost at altitude. Estimate for the coldest weather you might get, not for ideal conditions.",
    "q.m17#18.p" to "What matters most when reinforcing a tent in strong wind?",
    "q.m17#18.o0" to "Guy line angles, anchors on the windward side, and burying the snow skirt",
    "q.m17#18.o1" to "The colour of the tent",
    "q.m17#18.o2" to "The inner tent zip",
    "q.m17#18.o3" to "The thickness of the footprint",
    "q.m17#18.e" to "Tents rarely fail because the fabric tears; one anchor goes first. Doubling guys on the windward side and weighting the skirt with snow blocks is standard practice.",
    "q.m17#19.p" to "What are the advantages and risks of digging a snow cave on a snow slope?",
    "q.m17#19.o0" to "Excellent wind resistance and warmth, but risk of collapse and carbon monoxide",
    "q.m17#19.o1" to "Saves the tent, but too cold",
    "q.m17#19.o2" to "Convenient, but illegal",
    "q.m17#19.o3" to "There is no risk",
    "q.m17#19.e" to "A snow cave needs a vent and a judgement of roof thickness. Running a stove in a sealed cave is the classic carbon monoxide scenario.",
    "q.m17#20.p" to "When using a stove inside a tent, what must you guard against most?",
    "q.m17#20.o0" to "Carbon monoxide poisoning and fire",
    "q.m17#20.o1" to "Damp",
    "q.m17#20.o2" to "Cold, other than from lack of oxygen",
    "q.m17#20.o3" to "The tent deforming",
    "q.m17#20.e" to "Carbon monoxide is colourless and odourless, and its symptoms resemble altitude illness. Keep ventilation open and cook in the porch or outside where possible.",
    "q.m17#21.p" to "What is the rule for rubbish at high camp?",
    "q.m17#21.o0" to "Carry it all down; never bury or burn it at high camp",
    "q.m17#21.o1" to "Bury it in the snow",
    "q.m17#21.o2" to "Burn it",
    "q.m17#21.o3" to "Leave it for the next team",
    "q.m17#21.e" to "Decomposition at altitude is extremely slow, and anything buried or burned is exposed at melt. Carrying it down is the only compliant option.",
    "q.m17#22.p" to "How do you make melting snow for water more efficient?",
    "q.m17#22.o0" to "Start with a little liquid water, then add snow, use a high flame, and never run the pot dry",
    "q.m17#22.o1" to "Fill the pot with snow straight away",
    "q.m17#22.o2" to "Use a low flame and heat slowly",
    "q.m17#22.o3" to "Melt with cold water",
    "q.m17#22.e" to "A dry pot scorches and is terribly inefficient. A water starter plus a high flame saves significant fuel and time.",
    "q.m17#23.p" to "How should sleeping altitude be arranged on a high camp rotation?",
    "q.m17#23.o0" to "Follow the planned rotation; do not spend many consecutive nights at high camp",
    "q.m17#23.o1" to "The higher the better",
    "q.m17#23.o2" to "Always sleep at the highest camp",
    "q.m17#23.o3" to "However it works out",
    "q.m17#23.e" to "Rotation balances acclimatisation against recovery. Consecutive nights high accumulate fatigue and actually slow the whole schedule.",
    "q.m18#16.p" to "What are the altitude and location of Muztagh Ata?",
    "q.m18#16.o0" to "7,509 m, Akto County, Xinjiang, on the eastern edge of the Pamirs",
    "q.m18#16.o1" to "6,812 m, Nepal",
    "q.m18#16.o2" to "7,134 m, Kyrgyzstan",
    "q.m18#16.o3" to "8,163 m, Nepal",
    "q.m18#16.e" to "Known as the Father of Ice Mountains, it is one of the first choices for a Chinese 7,000 m peak: endless snow slopes that demand acclimatisation and fitness.",
    "q.m18#17.p" to "What is the main difficulty on Muztagh Ata?",
    "q.m18#17.o0" to "Altitude acclimatisation and the stamina cost of very long snow slopes, not technical difficulty",
    "q.m18#17.o1" to "Vertical rock walls",
    "q.m18#17.o2" to "Dense crevasses",
    "q.m18#17.o3" to "Technical ice climbing",
    "q.m18#17.e" to "The technical standard is moderate, but long, high, and cold magnifies any shortfall in fitness or acclimatisation.",
    "q.m18#18.p" to "Which country or region is Lenin Peak in?",
    "q.m18#18.o0" to "On the border of Kyrgyzstan and Tajikistan",
    "q.m18#18.o1" to "Nepal",
    "q.m18#18.o2" to "Xinjiang, China",
    "q.m18#18.o3" to "Pakistan",
    "q.m18#18.e" to "Lenin Peak in the Pamirs is often used as a first 7,000 m, but it still involves altitude and glacier terrain.",
    "q.m18#19.p" to "What is the altitude of Ama Dablam?",
    "q.m18#19.o0" to "6,812 m",
    "q.m18#19.o1" to "7,509 m",
    "q.m18#19.o2" to "7,126 m",
    "q.m18#19.o3" to "6,189 m",
    "q.m18#19.e" to "It is under 7,000 m, but its steep mixed rock and snow terrain and strong exposure make its technical demand comparable to peaks above 7,000 m.",
    "q.m18#20.p" to "What is Ama Dablam often used as a test piece for?",
    "q.m18#20.o0" to "The technical and psychological preparation for an 8,000 m peak",
    "q.m18#20.o1" to "A first snow mountain",
    "q.m18#20.o2" to "A ski line",
    "q.m18#20.o3" to "A trekking route",
    "q.m18#20.e" to "Its combination of exposure and technique tests whether you can still make the right movement under pressure.",
    "q.m18#21.p" to "How does the seasonal window for 7,000 m peaks usually compare?",
    "q.m18#21.o0" to "Narrower than at 5,000-6,000 m; wind and snowfall decide the window",
    "q.m18#21.o1" to "Open all year",
    "q.m18#21.o2" to "Winter only",
    "q.m18#21.o3" to "The same as at low altitude",
    "q.m18#21.e" to "The higher you go, the more the window depends on upper winds and the monsoon. A narrow window means being more decisive about both waiting and retreating.",
    "q.m18#22.p" to "When choosing a 7,000 m objective, what capability should you confirm first?",
    "q.m18#22.o0" to "Having repeatedly completed long snow-slope days and self-management at 6,000 m",
    "q.m18#22.o1" to "Rock climbing grade",
    "q.m18#22.o2" to "Running times",
    "q.m18#22.o3" to "Quantity of equipment",
    "q.m18#22.e" to "The threshold at 7,000 m is endurance and self-sufficiency, not one particular technical move. Look at your 6,000 m record first.",
    "q.m18#23.p" to "What do permits and logistics for these peaks usually require?",
    "q.m18#23.o0" to "Applying weeks in advance, plus arranging guides, porterage, and camp supplies",
    "q.m18#23.o1" to "Arranging it on site",
    "q.m18#23.o2" to "No permit at all",
    "q.m18#23.o3" to "Just buying a ticket",
    "q.m18#23.e" to "The more remote the route, the longer the logistics chain. Treating permits and logistics as part of the technical preparation is far cheaper than fixing them later.",
    "q.m19#19.p" to "Above what altitude does the death zone usually begin?",
    "q.m19#19.o0" to "8,000 m",
    "q.m19#19.o1" to "6,000 m",
    "q.m19#19.o2" to "7,000 m",
    "q.m19#19.o3" to "5,000 m",
    "q.m19#19.e" to "Above 8,000 m the air pressure is about a third of sea level, and the body cannot hold a balance over time; it only depletes.",
    "q.m19#20.p" to "At 8,000 m, why does rest no longer restore you?",
    "q.m19#20.o0" to "Oxygen supply cannot support repair, so the body is in net deficit",
    "q.m19#20.o1" to "Because it is too cold",
    "q.m19#20.o2" to "Because you cannot sleep",
    "q.m19#20.o3" to "Because of dehydration",
    "q.m19#20.e" to "This is the physiology behind keeping exposure as short as possible. Every tactic is designed around shortening time in the zone.",
    "q.m19#21.p" to "What is the most dangerous feature of cognitive decline at altitude?",
    "q.m19#21.o0" to "You cannot tell that your own judgement has deteriorated",
    "q.m19#21.o1" to "Poor memory",
    "q.m19#21.o2" to "Slow reactions",
    "q.m19#21.o3" to "Poor concentration",
    "q.m19#21.e" to "Hypoxia degrades self-assessment first. That is why decisions get externalised: written checklists and having someone else cross-check.",
    "q.m20#20.p" to "Why does usable cylinder capacity differ from nominal capacity?",
    "q.m20#20.o0" to "Residual pressure leaves the last part unusable, and cold lowers the pressure further",
    "q.m20#20.o1" to "Because of leaks",
    "q.m20#20.o2" to "Because it was mislabelled",
    "q.m20#20.o3" to "Because of mask losses",
    "q.m20#20.e" to "Budget on usable volume. Treating the nominal figure as usable is a common reason oxygen runs out early on summit day.",
    "q.m20#21.p" to "What does raising the oxygen flow rate cost you?",
    "q.m20#21.o0" to "Duration drops proportionally, so you need more backup cylinders",
    "q.m20#21.o1" to "Nothing",
    "q.m20#21.o2" to "The mask wears out",
    "q.m20#21.o3" to "The cylinder freezes",
    "q.m20#21.e" to "Flow and duration are inversely related. Raise the flow and you must recalculate total demand and reserves.",
    "q.m21#18.p" to "What is the latest official height of Everest?",
    "q.m21#18.o0" to "8,848.86 m (joint China-Nepal survey, 2020)",
    "q.m21#18.o1" to "8,848 m",
    "q.m21#18.o2" to "8,850 m",
    "q.m21#18.o3" to "8,846 m",
    "q.m21#18.e" to "8,848.86 m is the jointly announced 2020 figure. The older 8,848 m is the classic value, and both are still widely seen.",
    "q.m21#19.p" to "How does Lhotse sit relative to Everest?",
    "q.m21#19.o0" to "Immediately to the south, often climbed on the same route as Everest",
    "q.m21#19.o1" to "North of Everest",
    "q.m21#19.o2" to "In western Nepal",
    "q.m21#19.o3" to "In the Karakoram",
    "q.m21#19.e" to "The two share part of the South Col route, which is why Everest plus Lhotse is often planned as one expedition.",
    "q.m21#20.p" to "Where is Kangchenjunga?",
    "q.m21#20.o0" to "On the border of Nepal and India",
    "q.m21#20.o1" to "On the border of China and Nepal",
    "q.m21#20.o2" to "Pakistan",
    "q.m21#20.o3" to "Bhutan",
    "q.m21#20.e" to "The world's third highest, on the Nepal-India (Sikkim) border, where permits and logistics are comparatively complicated.",
    "q.m21#21.p" to "What characterises Annapurna I?",
    "q.m21#21.o0" to "A relatively high fatality rate, with a steep route and prominent avalanche and rockfall risk",
    "q.m21#21.o1" to "It is the easiest",
    "q.m21#21.o2" to "It is the highest",
    "q.m21#21.o3" to "It can be climbed all year",
    "q.m21#21.e" to "It is among the most dangerous 8,000 m peaks. The numbers are a reminder that ranking by height is not ranking by difficulty.",
    "q.m22#17.p" to "What is the official height and nickname of K2?",
    "q.m22#17.o0" to "8,611 m, the Savage Mountain",
    "q.m22#17.o1" to "8,586 m, the Snow Leopard",
    "q.m22#17.o2" to "8,126 m, the Naked Mountain",
    "q.m22#17.o3" to "8,080 m, the Hidden Peak",
    "q.m22#17.e" to "K2 is the second highest peak in the world and has long ranked near the top of 8,000 m peaks for technical difficulty and fatality rate.",
    "q.m22#18.p" to "What is Nanga Parbat's nickname and main hazard?",
    "q.m22#18.o0" to "The Naked Mountain; its huge relief brings avalanche and rockfall risk",
    "q.m22#18.o1" to "Father of Ice Mountains",
    "q.m22#18.o2" to "The Hidden Peak",
    "q.m22#18.o3" to "The Man Eater",
    "q.m22#18.e" to "Its south face is one of the greatest wall reliefs on earth. The route is exposed, the weather changeable, and retreat difficult.",
    "q.m22#19.p" to "What are the heights of Gasherbrum I and II?",
    "q.m22#19.o0" to "8,080 m and 8,035 m",
    "q.m22#19.o1" to "8,051 m and 8,080 m",
    "q.m22#19.o2" to "8,611 m and 8,586 m",
    "q.m22#19.o3" to "8,188 m and 8,167 m",
    "q.m22#19.e" to "GI is 8,080 m and GII 8,035 m. They are often compared, but the routes and difficulty differ greatly.",
    "q.m22#20.p" to "What is the height of Broad Peak?",
    "q.m22#20.o0" to "8,051 m",
    "q.m22#20.o1" to "8,035 m",
    "q.m22#20.o2" to "8,080 m",
    "q.m22#20.o3" to "8,126 m",
    "q.m22#20.e" to "Broad Peak is 8,051 m and is often seen as one of the less technical 8,000 m options, though it still involves long snow slopes and altitude risk.",
    "q.m22#21.p" to "How many 8,000 m peaks are in Pakistan?",
    "q.m22#21.o0" to "Five",
    "q.m22#21.o1" to "Three",
    "q.m22#21.o2" to "Four",
    "q.m22#21.o3" to "Two",
    "q.m22#21.e" to "K2, Nanga Parbat, Gasherbrum I and II, and Broad Peak: five in total.",
    "q.m23#18.p" to "Combined scenario: a teammate becomes ataxic at 7,500 m and there is only 2 hours of oxygen left. What comes first?",
    "q.m23#18.o0" to "Descend immediately and give oxygen, while telling base camp to prepare to receive them",
    "q.m23#18.o1" to "Rest and observe first",
    "q.m23#18.o2" to "Give medication first",
    "q.m23#18.o3" to "Continue to camp and deal with it there",
    "q.m23#18.e" to "Ataxia points to HACE. Descent is the only reliably effective measure; oxygen buys time.",
    "q.m23#19.p" to "Combined scenario: on summit day you find the fixed rope frayed by the party ahead. What is correct?",
    "q.m23#19.o0" to "Do not use that section; reroute or retreat",
    "q.m23#19.o1" to "Keep using it but be careful",
    "q.m23#19.o2" to "Just warn the people behind",
    "q.m23#19.o3" to "Record it and carry on",
    "q.m23#19.e" to "The strength of a worn rope cannot be estimated. A fixed line is everyone's lifeline; being careful is not a substitute.",
    "q.m23#20.p" to "Combined scenario: the team hits a blizzard at 6,500 m with 5 m visibility. What is the most reasonable choice?",
    "q.m23#20.o0" to "Build shelter nearby and wait, or follow a pre-recorded track back by GPS",
    "q.m23#20.o1" to "Keep looking for the route",
    "q.m23#20.o2" to "Spread out and search",
    "q.m23#20.o3" to "Sit down where you are and wait for clear weather",
    "q.m23#20.e" to "In a whiteout, navigating almost guarantees drifting off line. Sheltering in place, or reversing a recorded track, are the only two workable options.",
    "q.m23#21.p" to "Combined scenario: the whole team agrees to continue, but something feels wrong to you and you cannot say why. What should you do?",
    "q.m23#21.o0" to "Say clearly that something feels wrong and ask the team to re-check the key information together",
    "q.m23#21.o1" to "Go with the majority",
    "q.m23#21.o2" to "Stay silent and follow",
    "q.m23#21.o3" to "Turn back alone",
    "q.m23#21.e" to "Intuition is often a signal you have noticed but not yet put into words. Say it out loud so the team can check the facts together.",
    "q.m24#18.p" to "Combined scenario: on summit day you are 4 hours behind schedule, wind is rising, and one teammate is slowing down. What is the most reasonable judgement?",
    "q.m24#18.o0" to "Turn around on the pre-agreed conditions and record what triggered them",
    "q.m24#18.o1" to "Push to the top and reassess there",
    "q.m24#18.o2" to "Send the slow one back alone",
    "q.m24#18.o3" to "Speed up to make up time",
    "q.m24#18.e" to "When three signals appear at once, the reason to continue usually comes from goal pressure rather than fact. The turn-around conditions exist for exactly this.",
    "q.m24#19.p" to "Combined scenario: a teammate is breathless at rest but saturation is still 80%. What should you do?",
    "q.m24#19.o0" to "Treat as HAPE: rest, oxygen, prepare to descend",
    "q.m24#19.o1" to "Keep observing",
    "q.m24#19.o2" to "Have them drink more water",
    "q.m24#19.o3" to "Give a painkiller",
    "q.m24#19.e" to "Symptoms outrank numbers. Breathlessness at rest is the core HAPE signal, and descent is the most definitive treatment.",
    "q.m24#20.p" to "Combined scenario: on a fixed-rope section one anchor looks doubtful and the team is already halfway across. What should you do?",
    "q.m24#20.o0" to "Stop using that section, add a backup or reroute, and put people in a safe position first",
    "q.m24#20.o1" to "Move across quickly",
    "q.m24#20.o2" to "Only warn those behind",
    "q.m24#20.o3" to "Keep using it",
    "q.m24#20.e" to "Being halfway across is not a reason to continue. An anchor failure is systemic, not personal.",
    "q.m24#21.p" to "Combined scenario: the trip is over, and what is most worth keeping?",
    "q.m24#21.o0" to "A debrief that records the timeline, the reasoning, and the mistakes",
    "q.m24#21.o1" to "Photographs",
    "q.m24#21.o2" to "The equipment list",
    "q.m24#21.o3" to "The bills",
    "q.m24#21.e" to "A debrief turns an experience into experience. Write down which point could have been decided earlier, and next time it may be.",
    "q.l32#0.p" to "Fixed rope is classed into three uses. Which set is correct?",
    "q.l32#0.o0" to "Handrail, short fixed section, expedition route fixing",
    "q.l32#0.o1" to "Single, half, twin",
    "q.l32#0.o2" to "Dynamic, static, accessory cord",
    "q.l32#0.o3" to "Upper, middle, lower section",
    "q.l32#0.e" to "The three match three situations and three standards. Confuse the situations and you end up rigging a season-long route to handrail standards.",
    "q.l32#1.p" to "Which rope should long fixed lines use?",
    "q.l32#1.o0" to "Static rope (low stretch)",
    "q.l32#1.o1" to "Dynamic rope",
    "q.l32#1.o2" to "Accessory cord",
    "q.l32#1.o3" to "Webbing",
    "q.l32#1.e" to "Dynamic stretch exists for absorbing falls. On a fixed line it makes the rope bounce under body weight and wears out faster.",
    "q.l32#2.p" to "What diameter of static rope is usual for fixed lines?",
    "q.l32#2.o0" to "9-11 mm",
    "q.l32#2.o1" to "5-6 mm",
    "q.l32#2.o2" to "7-8 mm",
    "q.l32#2.o3" to "12-14 mm",
    "q.l32#2.e" to "Too thin and it wears badly and handles poorly; too thick and both weight and bulk climb. 9-11 mm is the usual range for expedition fixing.",
    "q.l32#3.p" to "What is wrong with two anchors threaded on a single sling?",
    "q.l32#3.o0" to "It is a series failure, not redundancy",
    "q.l32#3.o1" to "It wastes sling",
    "q.l32#3.o2" to "It looks untidy",
    "q.l32#3.o3" to "It slows the rope",
    "q.l32#3.e" to "In a series arrangement, one point failing slackens the whole system and the load jumps. Redundancy requires each leg to reach the master point independently.",
    "q.l32#4.p" to "In the five anchor checks, what does independent mean?",
    "q.l32#4.o0" to "The two anchors sit on different rock, different trees, or different bolts",
    "q.l32#4.o1" to "The two anchors are close together",
    "q.l32#4.o2" to "They share one sling",
    "q.l32#4.o3" to "Two nuts in the same crack",
    "q.l32#4.e" to "Two nuts in one crack fail together when that rock fails. Independence is a question of whether the failure cause is the same.",
    "q.l32#5.p" to "What does the direction check on an anchor mean?",
    "q.l32#5.o0" to "The anchor must take the actual load direction, not just downward",
    "q.l32#5.o1" to "The anchor faces the view",
    "q.l32#5.o2" to "The rope should run straight",
    "q.l32#5.o3" to "The anchor must be above you",
    "q.l32#5.e" to "Traversing while fixing, and swinging while ascending, both create lateral load. An anchor designed only for downward pull fails when loaded sideways.",
    "q.l32#6.p" to "What needs extra caution with snow anchors?",
    "q.l32#6.o0" to "Snow strength and melt risk: a whole section can fail as it melts",
    "q.l32#6.o1" to "Soft snow is hard to bury in",
    "q.l32#6.o2" to "Snow wets the rope",
    "q.l32#6.o3" to "Snow stakes are heavy",
    "q.l32#6.e" to "Snow anchor reliability depends heavily on temperature and time. An anchor at afternoon melt can be a completely different object from the same one at dawn.",
    "q.l32#7.p" to "What is the purpose of a stopper knot in the rope end?",
    "q.l32#7.o0" to "It stops the rope end running out of the device",
    "q.l32#7.o1" to "Makes coiling easier",
    "q.l32#7.o2" to "Marks the length",
    "q.l32#7.o3" to "Adds friction",
    "q.l32#7.e" to "If the end slips out of the device while rappelling or following, you lose the connection entirely. A stopper knot is the cheapest insurance with the highest return.",
    "q.l32#8.p" to "What is the main job of a mid-point re-belay?",
    "q.l32#8.o0" to "It keeps the rope running smoothly and confines fall and wear to one section",
    "q.l32#8.o1" to "Adds weight",
    "q.l32#8.o2" to "Makes photography easier",
    "q.l32#8.o3" to "Replaces a belay station",
    "q.l32#8.e" to "Without re-belays on a long route the rope forms a huge angle over the rock edge, which makes it hard to pull, concentrates wear, and lengthens any fall.",
    "q.l32#9.p" to "Can anyone stand below while a route is being fixed?",
    "q.l32#9.o0" to "No; the ground below must be clear while the fixer works above",
    "q.l32#9.o1" to "Yes, to pass tools up",
    "q.l32#9.o2" to "Yes, as long as they wear a helmet",
    "q.l32#9.o3" to "Yes, as long as nobody is fooling around",
    "q.l32#9.e" to "Rockfall is the main source of injury during fixing. Having someone stand below puts a teammate in the most dangerous position.",
    "q.l32#10.p" to "What four things should be settled during route-fixing planning?",
    "q.l32#10.o0" to "Start and end of each section, re-belays and escape points, rope length, and fixing method",
    "q.l32#10.o1" to "Colour, brand, price, weight",
    "q.l32#10.o2" to "Who goes first, who photographs, who boils water, who keeps accounts",
    "q.l32#10.o3" to "Weather, mood, budget, holidays",
    "q.l32#10.e" to "These four decide whether a fixing operation can retreat safely. Skipping the plan and getting straight on the rope leaves the escape plan to luck.",
    "q.l32#11.p" to "Why do fixed lines need scheduled inspection and records?",
    "q.l32#11.o0" to "Fixed routes often last a whole season, and rope condition changes with sun, wear, and freeze-thaw",
    "q.l32#11.o1" to "For auditing",
    "q.l32#11.o2" to "To share liability",
    "q.l32#11.o3" to "It is unnecessary",
    "q.l32#11.e" to "Fuzzed sheath, stiffness, and flattened spots are all retirement signals. Without records nobody can say how many days that rope has been hanging.",
    "q.l32#12.p" to "What do the five anchor checks include?",
    "q.l32#12.o0" to "Independent",
    "q.l32#12.o1" to "Equalised",
    "q.l32#12.o2" to "Direction",
    "q.l32#12.o3" to "Edge protection",
    "q.l32#12.e" to "The fifth is backup. The one most often missed is edges: a sling cut on a rock corner can be left with a small fraction of its strength.",
    "q.l32#13.p" to "Which conditions mean a fixed line should be retired?",
    "q.l32#13.o0" to "Fuzzed sheath, with core visible through it",
    "q.l32#13.o1" to "The rope is stiff and feels brittle",
    "q.l32#13.o2" to "Local flattening and deformation",
    "q.l32#13.o3" to "The colour has faded",
    "q.l32#13.e" to "The first three are structural damage. Fading is cosmetic, though it does correlate with UV ageing.",
    "q.l32#14.p" to "What self-protection does route fixing require?",
    "q.l32#14.o0" to "At least two attachment points at all times",
    "q.l32#14.o1" to "Wear a helmet",
    "q.l32#14.o2" to "Post a lookout above and manage rockfall",
    "q.l32#14.o3" to "Manage spare rope in a rope bag",
    "q.l32#14.e" to "Together these make the work area safe. The hard rule is the two points; the only exception is tieing directly into the rope to lead.",
    "q.l32#15.p" to "At which levels can a fixed-rope system be redundant?",
    "q.l32#15.o0" to "Anchor redundancy (two independent points)",
    "q.l32#15.o1" to "Connection redundancy (PAS or sling backup)",
    "q.l32#15.o2" to "Device redundancy (backup prusik)",
    "q.l32#15.o3" to "Colour redundancy (buy several colours)",
    "q.l32#15.e" to "The three layers mean the system does not fail, the transfer is never empty, and no single device carries you alone. Colour has nothing to do with safety.",
    "q.l32#16.p" to "Put the rigging of one fixed-rope section in the correct order.",
    "q.l32#16.o0" to "Set the start, end, and re-belay positions, and estimate rope length",
    "q.l32#16.o1" to "Build the anchors (independent, equalised, backed up)",
    "q.l32#16.o2" to "Run the rope and install the mid-point re-belays",
    "q.l32#16.o3" to "Tie the stopper knot and record the rope's condition",
    "q.l32#16.e" to "Allow length for knots and connections; too long is better than too short. The stopper knot comes last, but it can never be skipped.",
    "q.l32#17.p" to "One anchor point looks doubtful. What is the correct order of response?",
    "q.l32#17.o0" to "Stop using that section and put people in a safe position",
    "q.l32#17.o1" to "Add an independent backup point",
    "q.l32#17.o2" to "Re-equalise the load",
    "q.l32#17.o3" to "Inspect, record, then decide whether to continue",
    "q.l32#17.e" to "Get people safe before discussing technical fixes. Reverse the order and the fix itself becomes the accident scene.",
    "q.l32#18.p" to "What is the correct daily routine for a long-lived fixed line?",
    "q.l32#18.o0" to "Check anchors and rope condition before setting out",
    "q.l32#18.o1" to "Confirm two connections while passing",
    "q.l32#18.o2" to "Check wear and the stopper knot when the team comes off",
    "q.l32#18.o3" to "Record the inspection date and any problems",
    "q.l32#18.e" to "The value of the routine is turning inspection into habit. Managing a season-long fixed line from memory will eventually miss something.",
    "q.l32#19.p" to "The standard for dynamic rope is EN ______.",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "Dynamic rope is EN 892 / UIAA 101; static rope is EN 1891 / UIAA 110. Check the standard number when buying and inspecting.",
    "q.l32#20.p" to "Fixed lines should use ______ rope (dynamic or static).",
    "q.l32#20.a0" to "static",
    "q.l32#20.a1" to "static rope",
    "q.l32#20.e" to "Static rope is low stretch and abrasion resistant, which suits long-term fixing. Dynamic stretch makes a fixed line bounce constantly under use.",
    "q.l32#21.p" to "When fixing a route, the rope end must be ______ to stop it slipping out of the device.",
    "q.l32#21.a0" to "knotted",
    "q.l32#21.a1" to "tied off with a stopper knot",
    "q.l32#21.e" to "It is the step most easily skipped and the one with the most direct consequence.",
    "q.l32#22.p" to "The usual static rope diameter range for expedition fixing is ______-11 mm.",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9-11 mm balances abrasion resistance against weight. Below 9 mm it wears fast; above 11 mm the weight is noticeable.",
    "q.l32#23.p" to "Match each type of fixed rope with its typical situation.",
    "q.l32#23.l0" to "Handrail",
    "q.l32#23.l1" to "Short fixed section",
    "q.l32#23.l2" to "Expedition route fixing",
    "q.l32#23.l3" to "Mid-point re-belay",
    "q.l32#23.r0" to "A short exposed passage, held while moving through",
    "q.l32#23.r1" to "One steep slope or pitch, climbed repeatedly",
    "q.l32#23.r2" to "Long route, many pitches, loads carried, used all season",
    "q.l32#23.r3" to "Breaks a long rope into sections, reducing angles and wear",
    "q.l32#23.e" to "The situation sets the standard: the longer term, the heavier the loads, and the more exposed the ground, the higher the demand for anchor redundancy and rope records.",
    "q.l32#24.p" to "Match each item with its standard number.",
    "q.l32#24.l0" to "Static rope",
    "q.l32#24.l1" to "Dynamic rope",
    "q.l32#24.l2" to "Ascender",
    "q.l32#24.l3" to "Harness",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "Standard numbers are the basis for buying and inspecting, and they tell you what kind of loading the item was originally designed for.",
    "q.l32#25.p" to "Match each anchor problem with its consequence.",
    "q.l32#25.l0" to "Series failure",
    "q.l32#25.l1" to "Single load direction",
    "q.l32#25.l2" to "Unprotected sharp edge",
    "q.l32#25.l3" to "Single point, no backup",
    "q.l32#25.r0" to "One failure slackens the whole system and the load jumps",
    "q.l32#25.r1" to "The anchor pulls or breaks under lateral load",
    "q.l32#25.r2" to "The sling is cut and loses most of its strength",
    "q.l32#25.r3" to "The only connection fails and protection is gone entirely",
    "q.l32#25.e" to "Four problems, four failure modes. They often coexist, which is why the check is done item by item rather than by impression.",
    "q.l32#26.p" to "A teammate says the rope has only been up one season so it need not be checked. What is the best reply?",
    "q.l32#26.o0" to "Fixed rope wear depends on exposure and abrasion, not on how long the season is",
    "q.l32#26.o1" to "True, no check needed",
    "q.l32#26.o2" to "Just change the colour",
    "q.l32#26.o3" to "If it is not broken it is fine",
    "q.l32#26.e" to "Sun, freeze-thaw, and rock-edge friction all accumulate damage. Inspection intervals for fixed rope are set by intensity of use, not by the calendar.",
    "q.l32#27.p" to "What is the principle for estimating rope length when fixing?",
    "q.l32#27.o0" to "Allow for knots and connections; too long is better than too short",
    "q.l32#27.o1" to "Exactly the section length",
    "q.l32#27.o2" to "Shorter and lighter is always better",
    "q.l32#27.o3" to "Use the straight-line distance on the map",
    "q.l32#27.e" to "Too short and the whole section is wasted; too long only means a bit more weight. Knots, connections, and re-belays all consume length, so count them in.",
    "q.l32#28.p" to "A climber is about to cross a fixed line with lateral swing. What matters most to confirm?",
    "q.l32#28.o0" to "Whether the anchors can take lateral load, and whether there is a second attachment point",
    "q.l32#28.o1" to "The colour of the rope",
    "q.l32#28.o2" to "The length of the rope",
    "q.l32#28.o3" to "Their body weight",
    "q.l32#28.e" to "A lateral swing turns a downward anchor into a sideways-loaded one, which is exactly how many anchors get pulled out.",
    "q.l32#29.p" to "Why should a fixed-rope route include escape points?",
    "q.l32#29.o0" to "So the team can exit safely within one section if weather or conditions change",
    "q.l32#29.o1" to "For resting",
    "q.l32#29.o2" to "To store equipment",
    "q.l32#29.o3" to "For photographs",
    "q.l32#29.e" to "You cannot always go all the way on a long route. Escape points decide whether you still have a choice when things turn bad.",
    "q.l33#0.p" to "Which item is NOT part of the standard kit for ascending a fixed line?",
    "q.l33#0.o0" to "A descender (figure eight or tube)",
    "q.l33#0.o1" to "A handled ascender",
    "q.l33#0.o2" to "A foot loop",
    "q.l33#0.o3" to "A backup prusik",
    "q.l33#0.e" to "Ascending does not need a descender; that belongs to switching over and rappelling. Kit lists follow the action at hand, not everything you own.",
    "q.l33#1.p" to "What is the mnemonic for the ascending motion?",
    "q.l33#1.o0" to "Stand, sit, slide",
    "q.l33#1.o1" to "Pull, push, jump",
    "q.l33#1.o2" to "Squat, jump, grab",
    "q.l33#1.o3" to "Push, pull, sit",
    "q.l33#1.e" to "Stand on the foot loop, weight rises, push the chest ascender up, sit back, then slide the hand ascender. Get the rhythm right and you save half your energy.",
    "q.l33#2.p" to "Where should your centre of gravity be while ascending?",
    "q.l33#2.o0" to "Close to the rope",
    "q.l33#2.o1" to "As far out as possible",
    "q.l33#2.o2" to "Swinging side to side",
    "q.l33#2.o3" to "Leaning back as far as possible",
    "q.l33#2.e" to "Swinging out loads the ascender sideways, which can unclip it and burns far more energy. Staying close to the rope is both safety and efficiency.",
    "q.l33#3.p" to "What is the exception to the two-point rule?",
    "q.l33#3.o0" to "Tieing directly into the rope to lead",
    "q.l33#3.o1" to "In good weather",
    "q.l33#3.o2" to "In daylight",
    "q.l33#3.o3" to "Over short distances",
    "q.l33#3.e" to "When leading, you are part of the system and cannot clip a second point. In every other situation there should be two independent attachments.",
    "q.l33#4.p" to "What is the first rule for passing a knot?",
    "q.l33#4.o0" to "Make the new connection before releasing the old one",
    "q.l33#4.o1" to "Release the old connection, then make the new one",
    "q.l33#4.o2" to "Operate both at the same time",
    "q.l33#4.o3" to "Just skip over the knot",
    "q.l33#4.e" to "Reversed, you briefly sit on one point, or on none. Passing a knot is essentially a controlled system transfer.",
    "q.l33#5.p" to "While passing a knot, may both ascenders be off the rope at once?",
    "q.l33#5.o0" to "No; at least one must stay on the rope and loaded at all times",
    "q.l33#5.o1" to "Yes, if you are quick",
    "q.l33#5.o2" to "Yes, if someone is watching",
    "q.l33#5.o3" to "Yes, for short knots",
    "q.l33#5.e" to "Both off means every upward connection is gone. Take an extra minute to re-rig rather than gamble once.",
    "q.l33#6.p" to "What is the first step when switching from ascending to rappelling?",
    "q.l33#6.o0" to "Clip yourself to the anchor with a PAS or sling",
    "q.l33#6.o1" to "Remove the handled ascender first",
    "q.l33#6.o2" to "Install the descender first",
    "q.l33#6.o3" to "Release the chest ascender first",
    "q.l33#6.e" to "First gain a connection independent of the ascending system, then you can dismantle the old one. This is the common start of every changeover.",
    "q.l33#7.p" to "After installing the descender and before removing the ascender, what must you do?",
    "q.l33#7.o0" to "Load the descender and test it",
    "q.l33#7.o1" to "Unfasten the harness",
    "q.l33#7.o2" to "Coil the rope",
    "q.l33#7.o3" to "Take off your helmet",
    "q.l33#7.e" to "Testing under load is the only way to confirm the new system really holds your weight. Skip it and removing the old system may drop you.",
    "q.l33#8.p" to "What does the friction hitch above the descender do?",
    "q.l33#8.o0" to "It locks automatically if you lose control, acting as an independent backup",
    "q.l33#8.o1" to "Increases descent speed",
    "q.l33#8.o2" to "Protects the rope",
    "q.l33#8.o3" to "Marks your position",
    "q.l33#8.e" to "The hitch bites when you release the brake hand. It is the only line of defence at the single most dangerous moment: letting go.",
    "q.l33#9.p" to "Why tie a stopper knot before rappelling?",
    "q.l33#9.o0" to "To stop the rope end slipping out of the descender",
    "q.l33#9.o1" to "Makes coiling easier",
    "q.l33#9.o2" to "Marks the rope length",
    "q.l33#9.o3" to "Reduces wear",
    "q.l33#9.e" to "If the rope is too short, the end running out means instant loss of braking. The stopper knot is a must-check before every rappel.",
    "q.l33#10.p" to "What is the correct order for passing a mid-point re-belay?",
    "q.l33#10.o0" to "Clip into the re-belay anchor, then move the ascenders, then release the anchor connection",
    "q.l33#10.o1" to "Move the ascenders first, then clip the anchor",
    "q.l33#10.o2" to "Pass straight through without clipping",
    "q.l33#10.o3" to "Release the anchor first, then move",
    "q.l33#10.e" to "At a re-belay the rope is constrained by the carabiner, so there is little room and technique degrades. Gain an independent connection first to create room for error.",
    "q.l33#11.p" to "What should you do when the rope jams?",
    "q.l33#11.o0" to "Change the pull angle or haul from the side; never stand under it and yank",
    "q.l33#11.o1" to "Stand directly below and pull hard",
    "q.l33#11.o2" to "Use body weight to jerk it",
    "q.l33#11.o3" to "Cut it",
    "q.l33#11.e" to "Pulling from directly below exposes you to rope snap-back or rockfall and can jam the knot harder. Changing the angle is the most effective first move.",
    "q.l33#12.p" to "When pulling the rope after a double-rope rappel, which side should you pull?",
    "q.l33#12.o0" to "The side with less friction",
    "q.l33#12.o1" to "The side with more friction",
    "q.l33#12.o2" to "Either side",
    "q.l33#12.o3" to "Both at once",
    "q.l33#12.e" to "Pulling the low-friction side retrieves more easily and wears the sheath less, provided the ends are knotted and nothing is snagged.",
    "q.l33#13.p" to "Which items are mandatory on your person when ascending a fixed line?",
    "q.l33#13.o0" to "Handled and chest ascenders (or a second prusik)",
    "q.l33#13.o1" to "Foot loop",
    "q.l33#13.o2" to "Backup prusik and PAS",
    "q.l33#13.o3" to "Helmet",
    "q.l33#13.e" to "Together these make a complete ascending and backup system. Leave one out and you are forced into single-point work at every knot and changeover.",
    "q.l33#14.p" to "What are the most common errors at a changeover?",
    "q.l33#14.o0" to "Releasing the old system before building the new one",
    "q.l33#14.o1" to "Removing the ascender without testing the descender under load",
    "q.l33#14.o2" to "Both ascenders off the rope at the same time",
    "q.l33#14.o3" to "Clipping into the anchor before the changeover",
    "q.l33#14.e" to "The first three are all order errors. The last is precisely the correct practice, and it exists to prevent the other three.",
    "q.l33#15.p" to "What checks must be complete before rappelling?",
    "q.l33#15.o0" to "The descender is threaded the right way",
    "q.l33#15.o1" to "The friction hitch backup is fitted and working",
    "q.l33#15.o2" to "The rope end is knotted",
    "q.l33#15.o3" to "The rope is long enough to reach the next station",
    "q.l33#15.e" to "Miss any one and you risk losing control. All four must be done before you release your protection.",
    "q.l33#16.p" to "Which of these count as a new connection when passing a knot?",
    "q.l33#16.o0" to "A PAS or sling clipped above the knot",
    "q.l33#16.o1" to "Clipping a nearby anchor",
    "q.l33#16.o2" to "Installing a second ascender above",
    "q.l33#16.o3" to "Holding the rope with your hand",
    "q.l33#16.e" to "A hand is not a connection; it disappears the moment you let go. The first three all create a load-bearing point independent of the old system.",
    "q.l33#17.p" to "Put the five steps of passing a knot on ascent in the correct order.",
    "q.l33#17.o0" to "Slow down before the knot and assess its position and the rope above",
    "q.l33#17.o1" to "Connect yourself to the rope above the knot, or to a nearby anchor, with a PAS or sling",
    "q.l33#17.o2" to "Install a second ascender or prusik above, stand up, and transfer your weight",
    "q.l33#17.o3" to "Remove the lower ascender and reinstall it above the knot",
    "q.l33#17.o4" to "Confirm the new connection is loaded, then release the PAS backup",
    "q.l33#17.e" to "The whole point is always having one more point. Skip any step and you open a window with a single point loaded, or none at all.",
    "q.l33#18.p" to "Put the ascent-to-rappel changeover in order.",
    "q.l33#18.o0" to "Clip into the anchor with a PAS or sling",
    "q.l33#18.o1" to "Install the descender and thread it correctly",
    "q.l33#18.o2" to "Load the descender and test it",
    "q.l33#18.o3" to "Remove the handled ascender, keeping the chest ascender or backup prusik",
    "q.l33#18.o4" to "Remove the other ascender and confirm the descender and backup are working",
    "q.l33#18.o5" to "Release the PAS and begin the descent",
    "q.l33#18.e" to "The order is fixed and not adjusted on the fly. Every step keeps at least one reliable connection in place.",
    "q.l33#19.p" to "Put the rappel-to-ascent changeover in order.",
    "q.l33#19.o0" to "Install a prusik or ascender above the descender and clip it to the harness",
    "q.l33#19.o1" to "Stand up and transfer your weight to the hitch",
    "q.l33#19.o2" to "Install a second ascender or the foot loop and confirm it is loaded",
    "q.l33#19.o3" to "Remove the descender",
    "q.l33#19.o4" to "Begin ascending",
    "q.l33#19.e" to "The crux is the third step: the new system must already be loaded before the descender comes off.",
    "q.l33#20.p" to "Put the three steps of rappelling past a knot in order.",
    "q.l33#20.o0" to "Clip a PAS to the knot or an anchor above it as a backup",
    "q.l33#20.o1" to "Move the descender below the knot, tighten it, and test it under load",
    "q.l33#20.o2" to "Release the PAS and continue the descent",
    "q.l33#20.e" to "When a bulky knot will not pass, move the backup hitch below the knot first, then the descender, keeping one reliable connection through both transfers.",
    "q.l33#21.p" to "When ascending a fixed line you should maintain ______ independent attachment points at all times.",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "two",
    "q.l33#21.e" to "Two points is the hard rule of fixed-rope work. The only exception is tieing directly into the rope to lead.",
    "q.l33#22.p" to "When changing from ascent to rappel you must first clip into the ______ before removing the ascender.",
    "q.l33#22.a0" to "anchor",
    "q.l33#22.a1" to "belay station",
    "q.l33#22.a2" to "re-belay",
    "q.l33#22.e" to "Gaining a connection that does not depend on the old system is the starting point of every changeover.",
    "q.l33#23.p" to "The common backup friction hitches above a descender are the prusik or the ______.",
    "q.l33#23.a0" to "autoblock",
    "q.l33#23.a1" to "French prusik",
    "q.l33#23.a2" to "friction hitch",
    "q.l33#23.e" to "Both lock the moment you let go. Wrapped the wrong way or the wrong length and they fail, so drill until you can confirm them with your eyes closed.",
    "q.l33#24.p" to "Match each operation with its key principle.",
    "q.l33#24.l0" to "Passing a knot",
    "q.l33#24.l1" to "Passing a re-belay",
    "q.l33#24.l2" to "Ascent to rappel",
    "q.l33#24.l3" to "Rappel to ascent",
    "q.l33#24.r0" to "Build the new connection before releasing the old",
    "q.l33#24.r1" to "Clip the anchor before moving the hardware",
    "q.l33#24.r2" to "Anchor, descender, test, then remove ascender",
    "q.l33#24.r3" to "Only remove the descender once the new system is loaded",
    "q.l33#24.e" to "All four share one structure: build, transfer, release. Remembering the structure survives forgetting the steps.",
    "q.l33#25.p" to "Match each letter of the ABCDE check with its content.",
    "q.l33#25.l0" to "A, anchors",
    "q.l33#25.l1" to "B, backup",
    "q.l33#25.l2" to "C, connections",
    "q.l33#25.l3" to "E, exit",
    "q.l33#25.r0" to "Two independent points, equalised, correct load direction, edges protected",
    "q.l33#25.r1" to "PAS or prusik in place, each device independently backed up",
    "q.l33#25.r2" to "Carabiner gates closed, knots dressed, rope ends knotted",
    "q.l33#25.r3" to "Know the nearest escape point, rope long enough, communication clear",
    "q.l33#25.e" to "The value of the checklist is running it before every time you get on the rope. It does not replace judgement, but it blocks most basic errors.",
    "q.l33#26.p" to "A teammate plans to unclip one ascender and clip the other immediately after. What do you say?",
    "q.l33#26.o0" to "You must first establish a PAS or anchor connection; no unconnected gap is allowed",
    "q.l33#26.o1" to "Just be quick about it",
    "q.l33#26.o2" to "It is fine in daylight",
    "q.l33#26.o3" to "It is fine for short knots",
    "q.l33#26.e" to "Immediately after means zero margin if you fumble. The tolerance at a knot has to be created by a third connection.",
    "q.l33#27.p" to "At a re-belay the rope must come out of the carabiner and go back in. What is correct?",
    "q.l33#27.o0" to "Clip into the anchor first, then handle the rope, then release the backup",
    "q.l33#27.o1" to "Take the rope out first, then clip the anchor",
    "q.l33#27.o2" to "Have someone hold the rope",
    "q.l33#27.o3" to "Just open the carabiner",
    "q.l33#27.e" to "The moment the rope comes out you may depend entirely on the old connection. Build an independent one first, then the operation means something.",
    "q.l33#28.p" to "Why is the changeover considered the most dangerous part of fixed-rope work?",
    "q.l33#28.o0" to "Because it transfers between dismantling the old system and building the new one, leaving the smallest margin for error",
    "q.l33#28.o1" to "Because there is a lot of gear",
    "q.l33#28.o2" to "Because it is tiring",
    "q.l33#28.o3" to "Because it needs two people",
    "q.l33#28.e" to "Passing a knot only adds a point; a changeover replaces an entire system. Any error in the order means losing the connection outright.",
    "q.l43#0.p" to "What are the three main sources of skin problems at altitude?",
    "q.l43#0.o0" to "Dry air, ultraviolet, and wind",
    "q.l43#0.o1" to "Cold, damp, and friction",
    "q.l43#0.o2" to "Hypoxia, low pressure, and low temperature",
    "q.l43#0.o3" to "Diet, sleep, and stress",
    "q.l43#0.e" to "All three act at once and the skin barrier breaks down quickly. Moisturising and sun protection are not indulgences; they maintain your ability to work.",
    "q.l43#1.p" to "What is the correct way to use a heat pack?",
    "q.l43#1.o0" to "On the lower back, abdomen, or outside the boot, never directly on skin",
    "q.l43#1.o1" to "Directly on the skin",
    "q.l43#1.o2" to "On the forehead",
    "q.l43#1.o3" to "All over the body while sleeping",
    "q.l43#1.e" to "Direct skin contact can cause a low-temperature burn, and those heal very slowly at altitude. The point is to protect core temperature.",
    "q.l43#2.p" to "How should washing-up water be disposed of?",
    "q.l43#2.o0" to "Strain out the food scraps and carry them out; scatter the water widely",
    "q.l43#2.o1" to "Pour it into the stream",
    "q.l43#2.o2" to "Pour it beside the tent",
    "q.l43#2.o3" to "Pour it into the toilet hole",
    "q.l43#2.e" to "Food scraps are both pollution and an animal attractant. Strain and carry out, scatter the water: that is the low-impact method.",
    "q.l43#3.p" to "Why wash base layers first?",
    "q.l43#3.o0" to "Salt from sweat abrades the skin, and broken skin heals badly at altitude",
    "q.l43#3.o1" to "Because they look better",
    "q.l43#3.o2" to "Because they are light",
    "q.l43#3.o3" to "Because they are cheap",
    "q.l43#3.e" to "Salt and bacteria in base layers irritate skin continuously. In dry cold, a small break can take weeks to heal.",
    "q.l43#4.p" to "What is the correct treatment for a dirty or wet down jacket?",
    "q.l43#4.o0" to "Do not wash it; shake off surface snow and air dry",
    "q.l43#4.o1" to "Scrub it with detergent",
    "q.l43#4.o2" to "Wring it out",
    "q.l43#4.o3" to "Dry it by the fire",
    "q.l43#4.e" to "Down is very hard to restore to full loft in the field once washed. If wet, only air dry; do not roast it, which damages both fabric and down.",
    "q.l43#5.p" to "Which is NOT one of the three camp rules?",
    "q.l43#5.o0" to "Store food in the tent overnight",
    "q.l43#5.o1" to "Boots in the porch",
    "q.l43#5.o2" to "No food in the tent",
    "q.l43#5.o3" to "Hang rubbish up high, all together",
    "q.l43#5.e" to "Food in the tent brings animals right into the sleeping area and leaves the smell in your bag for days. The three rules cover damp, animals, and contamination at once.",
    "q.l43#6.p" to "Why does lip protection matter at altitude?",
    "q.l43#6.o0" to "Lips have no melanin protection, and once cracked, eating and speaking both hurt",
    "q.l43#6.o1" to "Because it looks better",
    "q.l43#6.o2" to "Because they get tanned",
    "q.l43#6.o3" to "Because they swell",
    "q.l43#6.e" to "The lips are the most commonly forgotten sun protection and the place where pain interferes with eating. Keep lip balm on you.",
    "q.l43#7.p" to "How should personal care time be arranged?",
    "q.l43#7.o0" to "As a fixed short routine each day (a few minutes morning and evening), not whenever there is time",
    "q.l43#7.o1" to "Only when the sun is out",
    "q.l43#7.o2" to "Once a week",
    "q.l43#7.o3" to "Depends on mood",
    "q.l43#7.e" to "The value of care comes from consistency. A fixed routine still gets done when you are exhausted; deciding on willpower usually means skipping it.",
    "q.l43#8.p" to "Which items need one set per person, marked with names?",
    "q.l43#8.o0" to "Eating utensils",
    "q.l43#8.o1" to "Washing kit",
    "q.l43#8.o2" to "Cups",
    "q.l43#8.o3" to "Tents",
    "q.l43#8.e" to "The first three touch the mouth or skin, and sharing spreads gut and skin problems. Tents are allocated per person and need no name.",
    "q.l43#9.p" to "Which care actions should happen every day at altitude?",
    "q.l43#9.o0" to "Apply sunscreen, including lips",
    "q.l43#9.o1" to "Moisturise",
    "q.l43#9.o2" to "Change to dry socks and air the boots",
    "q.l43#9.o3" to "Take a full shower daily",
    "q.l43#9.e" to "The first three directly determine the state of your skin and feet. A daily shower is neither practical nor necessary at altitude; local cleaning is enough.",
    "q.l43#10.p" to "Which situations should you avoid with a heat pack?",
    "q.l43#10.o0" to "Placing it directly on skin",
    "q.l43#10.o1" to "Leaving it on the same spot for hours while asleep",
    "q.l43#10.o2" to "Placing it on already frostbitten tissue",
    "q.l43#10.o3" to "Placing it on the lower back",
    "q.l43#10.e" to "The first three can cause low-temperature burns or worsen damage when sensation is dulled. The lower back is a normal placement.",
    "q.l43#11.p" to "Put the routine for arriving in camp in order.",
    "q.l43#11.o0" to "Change out of wet base layers and add insulation",
    "q.l43#11.o1" to "Pitch the tent, lay out the pad, air the boots and socks",
    "q.l43#11.o2" to "Boil water, eat, and drink",
    "q.l43#11.o3" to "Run the fixed care routine (sunscreen, moisturiser, lip balm, dress broken skin)",
    "q.l43#11.e" to "The core of the order is stopping heat loss first. Cooking before changing is the most common mistake.",
    "q.l43#12.p" to "A heat pack goes on the lower back, abdomen, or outside the boot, never directly on ______.",
    "q.l43#12.a0" to "skin",
    "q.l43#12.a1" to "the skin",
    "q.l43#12.e" to "Direct contact can cause a low-temperature burn, and burns heal extremely poorly at altitude.",
    "q.l43#13.p" to "Camp rules require that food stays out of the ______.",
    "q.l43#13.a0" to "tent",
    "q.l43#13.a1" to "sleeping tent",
    "q.l43#13.e" to "Food smells draw animals into the sleeping area and linger in your bag and clothing.",
    "q.l43#14.p" to "Match each care action with the problem it prevents.",
    "q.l43#14.l0" to "Sunscreen and lip balm",
    "q.l43#14.l1" to "Moisturiser",
    "q.l43#14.l2" to "Dry socks",
    "q.l43#14.l3" to "Heat pack",
    "q.l43#14.r0" to "UV burns, including snow blindness risk",
    "q.l43#14.r1" to "Cracked, broken skin barrier",
    "q.l43#14.r2" to "Blisters and maceration",
    "q.l43#14.r3" to "Falling core temperature",
    "q.l43#14.e" to "Four actions for four problems. None of them is difficult; what is difficult is doing them every day.",
    "q.l43#15.p" to "What is the most realistic way to do laundry at altitude?",
    "q.l43#15.o0" to "Wash only the base layers with a little detergent, rinse well, and dry them inside the tent",
    "q.l43#15.o1" to "Wash everything",
    "q.l43#15.o2" to "Do not wash",
    "q.l43#15.o3" to "Scrub with snow",
    "q.l43#15.e" to "Both water and fuel are precious. Base layers are the only thing that must be washed; the rest can be aired and shaken.",
    "q.l43#16.p" to "How often should sunscreen be reapplied at altitude?",
    "q.l43#16.o0" to "Every 2-3 hours, and again after sweating or in snow reflection",
    "q.l43#16.o1" to "Once in the morning",
    "q.l43#16.o2" to "Once a day",
    "q.l43#16.o3" to "Not at all",
    "q.l43#16.e" to "Strong UV, wind, and snow reflection break the film down fast. Reapplying matters more than choosing a high SPF.",
    "q.l43#17.p" to "What is most often forgotten when going outside camp at night?",
    "q.l43#17.o0" to "Boots or camp shoes; do not walk on snow in socks alone",
    "q.l43#17.o1" to "The camera",
    "q.l43#17.o2" to "Water",
    "q.l43#17.o3" to "A hat",
    "q.l43#17.e" to "Wet socks mean a cold night and raise the risk of frostbite and hypothermia. Camp shoes are the simplest effective piece of kit.",
    "q.l43#18.p" to "How should consumables like wipes and tissues be planned?",
    "q.l43#18.o0" to "Split them into daily portions with one spare, and keep them dry",
    "q.l43#18.o1" to "Bring the whole pack",
    "q.l43#18.o2" to "Bring extra",
    "q.l43#18.o3" to "Do not bring any",
    "q.l43#18.e" to "A whole pack absorbs moisture and takes up space. Daily portions control usage and leave you a backup if one gets wet.",
    "q.l43#19.p" to "Which personal care items most deserve a duplicate?",
    "q.l43#19.o0" to "Lip balm and sunscreen",
    "q.l43#19.o1" to "Shampoo",
    "q.l43#19.o2" to "Perfume",
    "q.l43#19.o3" to "A razor",
    "q.l43#19.e" to "These two are small, impossible to replace once lost, and directly affect eating and the skin barrier.",
    "q.l34#0.p" to "Which terrain on a glacier is the most dangerous and the most underestimated?",
    "q.l34#0.o0" to "Crevasses and snow bridges hidden under snow",
    "q.l34#0.o1" to "Lateral moraine ridges",
    "q.l34#0.o2" to "Flat snowfields",
    "q.l34#0.o3" to "The scree slopes at the glacier edges",
    "q.l34#0.e" to "Once covered by fresh snow, a crevasse looks exactly like ordinary snow. Falling into crevasses accounts for the largest share of glacier accidents.",
    "q.l34#1.p" to "Where do transverse crevasses most often appear?",
    "q.l34#1.o0" to "Where the gradient changes (tops and feet of slopes, ice steps)",
    "q.l34#1.o1" to "In the middle of the glacier",
    "q.l34#1.o2" to "At the glacier terminus",
    "q.l34#1.o3" to "On the moraine",
    "q.l34#1.e" to "An abrupt change in gradient means extension or compression, and crevasses open exactly there. Looking at the crest zone before starting up is the most practical habit.",
    "q.l34#2.p" to "What causes the longitudinal crevasses common along the sides of a glacier?",
    "q.l34#2.o0" to "Extension from friction between the flowing ice and the valley walls",
    "q.l34#2.o1" to "Rockfall impact",
    "q.l34#2.o2" to "Climbers trampling the surface",
    "q.l34#2.o3" to "Meltwater cutting channels",
    "q.l34#2.e" to "The centre flows faster than the margins, and the speed difference creates shear and extension. That is why the centre line is usually safer than hugging the edge.",
    "q.l34#3.p" to "How much rope is usual between climbers on a glacier?",
    "q.l34#3.o0" to "8-10 m",
    "q.l34#3.o1" to "2-3 m",
    "q.l34#3.o2" to "20-30 m",
    "q.l34#3.o3" to "As short as possible",
    "q.l34#3.e" to "Too short and one fall pulls teammates straight in; too long and both arrest distance and rescue difficulty increase. Shorten it in dense crevasse fields, but not below 6-8 m.",
    "q.l34#4.p" to "Why tie knots in the rope when moving as a rope team?",
    "q.l34#4.o0" to "They limit fall depth, add braking friction, and give rescuers something to grip",
    "q.l34#4.o1" to "To stop the rope kinking",
    "q.l34#4.o2" to "To mark the length",
    "q.l34#4.o3" to "For appearance",
    "q.l34#4.e" to "Knots catch at the lip of the crevasse and add resistance, noticeably reducing how far you drop. The cost is slightly fussier rope handling, and it is worth it.",
    "q.l34#5.p" to "What is the main advantage of a three-person rope team over two?",
    "q.l34#5.o0" to "Two people can hold the fall while one prepares the rescue system, giving more margin",
    "q.l34#5.o1" to "You move faster",
    "q.l34#5.o2" to "The rope is lighter",
    "q.l34#5.o3" to "No knots are needed",
    "q.l34#5.e" to "With two, whoever is arresting can barely operate a rescue system. Only with three do you get the split between holding and rigging.",
    "q.l34#6.p" to "What do you look at first when judging whether a snow bridge is sound?",
    "q.l34#6.o0" to "Colour and sag: dark or blue patches, or radial cracks, mean it is thin",
    "q.l34#6.o1" to "How many footprints there are",
    "q.l34#6.o2" to "Whether the surface is smooth",
    "q.l34#6.o3" to "Whether there is wind",
    "q.l34#6.e" to "Bridge strength depends on span and snow depth. Colour and sag are the most direct clues; footprints only prove someone else went there, not that it is safe.",
    "q.l34#7.p" to "When is the best time to cross a dense crevasse field?",
    "q.l34#7.o0" to "Early morning or during the cold hours of night",
    "q.l34#7.o1" to "At noon",
    "q.l34#7.o2" to "In the afternoon",
    "q.l34#7.o3" to "Any time is the same",
    "q.l34#7.e" to "Snow bridges are strongest in the cold and lose considerable strength after afternoon melt. Plan the crossing time around that fact.",
    "q.l34#8.p" to "How should you move through a serac zone?",
    "q.l34#8.o0" to "Move fast, keep spacing, wear a helmet, and do not stop inside it",
    "q.l34#8.o1" to "Move slowly, roped together",
    "q.l34#8.o2" to "Rest inside the zone",
    "q.l34#8.o3" to "Stop for photographs",
    "q.l34#8.e" to "The hazard in a serac zone is ice tower collapse, which unlike a crevasse arrives as a single block. Minimise time inside and never rope up and wait there.",
    "q.l34#9.p" to "What state should the rope be in while travelling on a glacier?",
    "q.l34#9.o0" to "Moderately taut: neither dragging on the snow nor slack",
    "q.l34#9.o1" to "Completely slack, dragging on the surface",
    "q.l34#9.o2" to "Bar tight",
    "q.l34#9.o3" to "Coiled and carried in hand",
    "q.l34#9.e" to "A slack rope produces a shock load the instant someone falls; a tight one drags teammates. Moderate tension plus knots is the most stable combination.",
    "q.l34#10.p" to "What is the first response to an obvious crevasse?",
    "q.l34#10.o0" to "Go around it, finding a narrower spot or an existing snow bridge",
    "q.l34#10.o1" to "Jump across",
    "q.l34#10.o2" to "Stand on the edge to look down",
    "q.l34#10.o3" to "Widen it with the axe",
    "q.l34#10.e" to "The first principle of glacier route choice is go around. Jumping it and peering over the edge are the two most common ways people hurt themselves.",
    "q.l34#11.p" to "Why is travelling along the centre line of a glacier usually safer?",
    "q.l34#11.o0" to "The marginal extension zones have more crevasses; the centre is loaded more evenly",
    "q.l34#11.o1" to "The snow is deeper in the centre",
    "q.l34#11.o2" to "The centre is shorter",
    "q.l34#11.o3" to "There are more people in the centre",
    "q.l34#11.e" to "The centre usually has fewer crevasses and shorter bridge spans. But judge serac zones and ice steps separately; do not apply it mechanically.",
    "q.l34#12.p" to "What must a glacier route assessment consider?",
    "q.l34#12.o0" to "Crevasse density and snow bridge condition",
    "q.l34#12.o1" to "Serac and falling ice hazard",
    "q.l34#12.o2" to "Temperature and sun that day, which drive bridge strength",
    "q.l34#12.o3" to "Team size and roping arrangement",
    "q.l34#12.e" to "All four interact: temperature sets bridge strength, numbers set the roping, roping sets the consequences of a fall. Risk assessment means looking at them together.",
    "q.l34#13.p" to "Which signs suggest a snow bridge may be unreliable?",
    "q.l34#13.o0" to "The surface sags noticeably",
    "q.l34#13.o1" to "It looks dark or blue",
    "q.l34#13.o2" to "Radial cracks at its edges",
    "q.l34#13.o3" to "Fresh snow on top, with a hollow echo underneath",
    "q.l34#13.e" to "All four are different expressions of insufficient strength. If you hear a hollow echo, back off rather than taking one more step forward.",
    "q.l34#14.p" to "Which practices increase risk on a glacier?",
    "q.l34#14.o0" to "Roping too close together",
    "q.l34#14.o1" to "No knots in the rope",
    "q.l34#14.o2" to "Resting inside a serac zone",
    "q.l34#14.o3" to "Travelling along the glacier margin",
    "q.l34#14.e" to "The four raise the risk of being pulled in together, deep burial, falling ice, and marginal crevasses respectively. All are avoidable choices.",
    "q.l34#15.p" to "What should the team agree before entering a crevasse field?",
    "q.l34#15.o0" to "Rope spacing and knotting method",
    "q.l34#15.o1" to "Order of passage and spacing",
    "q.l34#15.o2" to "How to handle a snow bridge: probe, detour, retreat",
    "q.l34#15.o3" to "Whose pack is heaviest",
    "q.l34#15.e" to "The first three decide how everyone reacts when something happens. Agreeing beforehand is far safer than discussing it at the edge of a crevasse.",
    "q.l34#16.p" to "Put the process for crossing a doubtful snow bridge in the correct order.",
    "q.l34#16.o0" to "Stop and assess colour, sag, and surrounding cracks",
    "q.l34#16.o1" to "Probe the bridge thickness with an axe or probe",
    "q.l34#16.o2" to "Once a detour is ruled out, shorten the rope spacing and cross one at a time",
    "q.l34#16.o3" to "After everyone is across, the last person clears their protection and follows",
    "q.l34#16.e" to "Probing must happen before anyone steps on. One at a time means only one person's weight is on the bridge at any moment, and that is the critical arrangement.",
    "q.l34#17.p" to "What is the correct order when planning a glacier day?",
    "q.l34#17.o0" to "Study the map and crevasse pattern",
    "q.l34#17.o1" to "Fix the time window for the crevasse section (early morning or night)",
    "q.l34#17.o2" to "Decide the roping arrangement and rope spacing",
    "q.l34#17.o3" to "Confirm weather and temperature again before setting out",
    "q.l34#17.e" to "Terrain first, then time, then formation, then a weather re-check. Reverse it and you get we followed the plan but chose the wrong time of day.",
    "q.l34#18.p" to "A teammate falls into a crevasse. What are the first three actions, in order?",
    "q.l34#18.o0" to "Arrest immediately and keep the rope loaded",
    "q.l34#18.o1" to "Confirm your own position is safe and build protection",
    "q.l34#18.o2" to "Call to teammates to prepare the rescue system",
    "q.l34#18.o3" to "Work through the roped-team rescue procedure",
    "q.l34#18.e" to "The arrest is the one thing that cannot wait; protection and the rescue system come after. The detailed procedure is in the self-rescue and roped-team rescue lesson.",
    "q.l34#19.p" to "The usual rope spacing on a glacier is ______-10 m.",
    "q.l34#19.a0" to "8",
    "q.l34#19.e" to "8-10 m is the common range. Shorten it in dense crevasse fields, but not so short that one fall takes the whole team.",
    "q.l34#20.p" to "Besides colour and sag, judge a snow bridge by ______ with the ice axe.",
    "q.l34#20.a0" to "probing",
    "q.l34#20.a1" to "probe",
    "q.l34#20.a2" to "probing it",
    "q.l34#20.e" to "Probing is done before anyone steps on. Push the pick in gently and feel the snow depth and whether there is a void beneath.",
    "q.l34#21.p" to "Crossing a dense crevasse field is best scheduled for ______, when bridges are strongest.",
    "q.l34#21.a0" to "early morning",
    "q.l34#21.a1" to "the morning",
    "q.l34#21.a2" to "before dawn",
    "q.l34#21.e" to "Cold makes bridges harder and stronger; afternoon melt weakens them noticeably.",
    "q.l34#22.p" to "Match each crevasse type with its typical location.",
    "q.l34#22.l0" to "Transverse crevasse",
    "q.l34#22.l1" to "Longitudinal crevasse",
    "q.l34#22.l2" to "Diagonal crevasse",
    "q.l34#22.l3" to "Serac or icefall zone",
    "q.l34#22.r0" to "Where the gradient changes (tops, feet, ice steps)",
    "q.l34#22.r1" to "The extension zone where the ice rubs the valley walls",
    "q.l34#22.r2" to "Where the glacier turns or changes width",
    "q.l34#22.r3" to "Below steep icefall, with high falling-ice risk",
    "q.l34#22.e" to "Crevasses are caused by extension. Hold that in mind and you can predict where the next stretch will crack.",
    "q.l34#23.p" to "Match each snow bridge sign with the right response.",
    "q.l34#23.l0" to "Sagging surface",
    "q.l34#23.l1" to "Dark or blue colour",
    "q.l34#23.l2" to "Radial cracks",
    "q.l34#23.l3" to "Hollow echo",
    "q.l34#23.r0" to "Deprioritise crossing; detour first",
    "q.l34#23.r1" to "The snow is thin; do not probe it alone",
    "q.l34#23.r2" to "Structure already compromised; do not cross",
    "q.l34#23.r3" to "Back off immediately and change route",
    "q.l34#23.e" to "The four signs escalate in severity. If any one appears, think detour first rather than getting across faster.",
    "q.l34#24.p" to "Match each role with its duty in a three-person rope team.",
    "q.l34#24.l0" to "First (leading, route finding)",
    "q.l34#24.l1" to "Middle",
    "q.l34#24.l2" to "Last",
    "q.l34#24.r0" to "Judges route and snow bridges, sets the pace",
    "q.l34#24.r1" to "Links front and back, passes instructions",
    "q.l34#24.r2" to "Manages the rope, watches behind and the rope end",
    "q.l34#24.e" to "Agree the division of roles before setting out. The middle is not the safest position; it is the communications hub.",
    "q.l34#25.p" to "Someone wants to test a snow bridge by stepping on it. What do you do?",
    "q.l34#25.o0" to "Stop them; probe with an axe or a probe instead, or simply detour",
    "q.l34#25.o1" to "Let them try, you are roped anyway",
    "q.l34#25.o2" to "Send them across alone first",
    "q.l34#25.o3" to "Run across to reduce the load time",
    "q.l34#25.e" to "A person is a concentrated load of tens of kilograms and one step can go through. Test with a tool, not with body weight.",
    "q.l34#26.p" to "By noon the temperature has risen and the planned crevasse section is still two hours away. What should you do?",
    "q.l34#26.o0" to "Reassess: wait for the evening cooldown or take the alternative route",
    "q.l34#26.o1" to "Carry on as planned",
    "q.l34#26.o2" to "Speed up and push through",
    "q.l34#26.o3" to "Wait where you are until tomorrow",
    "q.l34#26.e" to "Bridge strength is a function of time. The plan should be built around the strongest hours, not require people to adapt to the plan.",
    "q.l34#27.p" to "Why is a serac zone a bad place to rope up and wait?",
    "q.l34#27.o0" to "Ice towers collapse as whole blocks, and waiting lengthens exposure",
    "q.l34#27.o1" to "Because it is windy",
    "q.l34#27.o2" to "Because the ground is uneven",
    "q.l34#27.o3" to "Because there is no phone signal",
    "q.l34#27.e" to "Crevasse risk is shared by the rope team; falling ice can only be managed by reducing exposure time. The two hazards call for opposite responses.",
    "q.l34#28.p" to "Which statement about pace on a glacier is correct?",
    "q.l34#28.o0" to "Steady, even pace with constant rope spacing is safer than speeding up and slowing down",
    "q.l34#28.o1" to "Faster is safer",
    "q.l34#28.o2" to "Slower is safer",
    "q.l34#28.o3" to "Everyone walks at their own pace",
    "q.l34#28.e" to "Stopping and starting repeatedly slackens and snaps the rope, producing shock loads. On a glacier, a shared rhythm is both safety and efficiency.",
    "q.l34#29.p" to "What should someone new to glaciers practise first?",
    "q.l34#29.o0" to "Roped travel, rope spacing control, and the arrest position on safe ground",
    "q.l34#29.o1" to "Running faster",
    "q.l34#29.o2" to "Crossing crevasses alone",
    "q.l34#29.o3" to "Working at height",
    "q.l34#29.e" to "The arrest position and a feel for rope spacing must become muscle memory on safe terrain, or there will be no time for them when someone actually falls in.",
    "q.l35#0.p" to "What is the leading cause of death in avalanche burial?",
    "q.l35#0.o0" to "Asphyxia (65-100%)",
    "q.l35#0.o1" to "Trauma",
    "q.l35#0.o2" to "Hypothermia",
    "q.l35#0.o3" to "Blood loss",
    "q.l35#0.e" to "This single fact sets the order of treatment: secure the airway and ventilation first, then circulation and rewarming.",
    "q.l35#1.p" to "Roughly what are the survival rates for complete versus partial burial, on the 2023 pooled figures?",
    "q.l35#1.o0" to "About 48% and 96%",
    "q.l35#1.o1" to "About 80% and 90%",
    "q.l35#1.o2" to "About 20% and 60%",
    "q.l35#1.o3" to "Both around 50%",
    "q.l35#1.e" to "The two figures differ by more than double, which shows that having your head out and being fully buried are entirely different situations.",
    "q.l35#2.p" to "Roughly how long is the survival phase of the survival curve after burial?",
    "q.l35#2.o0" to "The first 18 minutes",
    "q.l35#2.o1" to "The first 5 minutes",
    "q.l35#2.o2" to "18-35 minutes",
    "q.l35#2.o3" to "After 90 minutes",
    "q.l35#2.e" to "Deaths in the survival phase are mostly from trauma, and the airway is usually still open. That is why 18 minutes is repeated so often.",
    "q.l35#3.p" to "What is the shape of the curve during the asphyxia phase?",
    "q.l35#3.o0" to "Survival falls steeply; this is the tightest rescue window",
    "q.l35#3.o1" to "The curve is flat",
    "q.l35#3.o2" to "Survival rises again",
    "q.l35#3.o3" to "It is unrelated to cold",
    "q.l35#3.e" to "The steep drop between 18 and 35 minutes comes from snow blocking the airway and oxygen running out in the air pocket. Almost all the value of companion rescue lives in that window.",
    "q.l35#4.p" to "Why is survival relatively flat in the latency phase (about 35-90 minutes)?",
    "q.l35#4.o0" to "People with an air pocket and a clear airway enter a cold-protected state with reduced metabolism",
    "q.l35#4.o1" to "The snow melts",
    "q.l35#4.o2" to "Rescue arrives",
    "q.l35#4.o3" to "Trauma heals",
    "q.l35#4.e" to "Here cold is protection, not threat. It is also why long burial cannot simply be equated with no chance.",
    "q.l35#5.p" to "What share of avalanche deaths is caused by hypothermia?",
    "q.l35#5.o0" to "0-4%",
    "q.l35#5.o1" to "20-30%",
    "q.l35#5.o2" to "50%",
    "q.l35#5.o3" to "Nearly all",
    "q.l35#5.e" to "The share is small but real cases exist. It is a reminder: ventilation first, rewarming second, and the order cannot be reversed.",
    "q.l35#6.p" to "In the first 0-2 minutes after an avalanche, what comes first?",
    "q.l35#6.o0" to "Check for secondary avalanche risk, post a lookout, and record the time and last seen point",
    "q.l35#6.o1" to "Start digging immediately",
    "q.l35#6.o2" to "Take photographs",
    "q.l35#6.o3" to "Call the family",
    "q.l35#6.e" to "Without a lookout the rescuers become the second burial; without a time record the 60-minute rule cannot be applied later.",
    "q.l35#7.p" to "What is the goal in the 2-10 minute stage?",
    "q.l35#7.o0" to "Reach the person as fast as possible, not clear all the snow",
    "q.l35#7.o1" to "Dig a proper channel",
    "q.l35#7.o2" to "Tidy the equipment",
    "q.l35#7.o3" to "Wait for professional teams",
    "q.l35#7.e" to "Reaching the face lets ventilation begin, minutes before full extrication, and minutes are the difference between life and death in the asphyxia phase.",
    "q.l35#8.p" to "In the first 60 seconds after reaching the face, what is the correct order?",
    "q.l35#8.o0" to "Clear snow and ice from mouth and nose, check vital signs, and give rescue breaths immediately if not breathing",
    "q.l35#8.o1" to "Pull the body out first, then clear the face",
    "q.l35#8.o2" to "Photograph first, then treat",
    "q.l35#8.o3" to "Give hot water first",
    "q.l35#8.e" to "Clear the airway before anything else. Pulling someone straight out can worsen a spinal injury and pushes snow into the mouth and nose.",
    "q.l35#9.p" to "How should 25% survival at 45 minutes versus 18% at 40 minutes be understood?",
    "q.l35#9.o0" to "Small sample sizes and different proportions with air pockets, not a rebound in the curve",
    "q.l35#9.o1" to "It means 45 minutes is safer",
    "q.l35#9.o2" to "It means you should wait until 45 minutes",
    "q.l35#9.o3" to "The data are wrong",
    "q.l35#9.e" to "Teach the trend, never turn a single point into an absolute promise. Treating noise as a pattern leads to absurd conclusions.",
    "q.l35#10.p" to "Every completely buried patient looks normal after extrication. What should you do?",
    "q.l35#10.o0" to "Still send them for medical observation",
    "q.l35#10.o1" to "Send them back to camp",
    "q.l35#10.o2" to "Continue the day's itinerary",
    "q.l35#10.o3" to "Have them walk down themselves",
    "q.l35#10.e" to "The effects of hypoxia and cold can be delayed. Observation and assessment need equipment and time, which camp cannot provide.",
    "q.l35#11.p" to "What must be recorded at an avalanche site?",
    "q.l35#11.o0" to "Time of the avalanche or last known time",
    "q.l35#11.o1" to "Last seen point",
    "q.l35#11.o2" to "Number of people buried",
    "q.l35#11.o3" to "Names of the rescuers",
    "q.l35#11.e" to "The first three directly determine the search area and the medical decisions. Rescuer names belong in the after-action record and do not affect field judgement.",
    "q.l35#12.p" to "What must be handled at the same time after extrication?",
    "q.l35#12.o0" to "Spinal protection; avoid rough handling",
    "q.l35#12.o1" to "Full insulation, removing wet clothing, and insulating from the ground",
    "q.l35#12.o2" to "Continuous monitoring of rhythm and core temperature",
    "q.l35#12.o3" to "Have the casualty stand up and move around",
    "q.l35#12.e" to "The first three are standard care. Making the casualty move worsens hypothermia and any spinal injury.",
    "q.l35#13.p" to "Which factors should NOT decide whether resuscitation is attempted?",
    "q.l35#13.o0" to "Burial depth",
    "q.l35#13.o1" to "Presence of an air pocket",
    "q.l35#13.o2" to "Snow density",
    "q.l35#13.o3" to "Whether the airway is completely packed with snow",
    "q.l35#13.e" to "The first three affect digging time and not the medical decision. Only airway status, time, and temperature enter the triage.",
    "q.l35#14.p" to "Put the first ten minutes at an avalanche site in the correct order.",
    "q.l35#14.o0" to "Confirm secondary avalanche and rockfall risk, and post a lookout",
    "q.l35#14.o1" to "Record the time and last seen point, and call for rescue",
    "q.l35#14.o2" to "Search with transceivers and probe to locate",
    "q.l35#14.o3" to "Begin digging, aiming to reach the face as fast as possible",
    "q.l35#14.e" to "The logic is first do not turn the rescue into a second accident, then make sure later decisions have evidence behind them.",
    "q.l35#15.p" to "Put the sequence after reaching the face in order.",
    "q.l35#15.o0" to "Clear snow and ice from mouth and nose, and assess the airway",
    "q.l35#15.o1" to "Check vital signs within one minute",
    "q.l35#15.o2" to "Give rescue breaths immediately if not breathing",
    "q.l35#15.o3" to "Triage by the 60-minute rule and arrange transport",
    "q.l35#15.e" to "Ventilation comes before full extrication and before moving the casualty. In practice this is the step most often done backwards.",
    "q.l35#16.p" to "Asphyxia is the main cause of avalanche death, accounting for ______-100% of fatalities.",
    "q.l35#16.a0" to "65",
    "q.l35#16.e" to "The 65-100% range comes from nine studies. It explains why ventilation first is an iron rule.",
    "q.l35#17.p" to "The golden ______ minutes repeated in the survival curve refers to the window before the asphyxia phase begins.",
    "q.l35#17.a0" to "18",
    "q.l35#17.a1" to "eighteen",
    "q.l35#17.e" to "18 minutes is the statistical inflection. It is not a magic number, but it is good enough as a training target.",
    "q.l35#18.p" to "Hypothermia accounts for only ______-4% of avalanche deaths.",
    "q.l35#18.a0" to "0",
    "q.l35#18.e" to "0-4%. The share is low, yet it explains the rare cases rescued after very long burial.",
    "q.l35#19.p" to "Match each of the four phases with its character.",
    "q.l35#19.l0" to "Survival phase (0-18 min)",
    "q.l35#19.l1" to "Asphyxia phase (18-35 min)",
    "q.l35#19.l2" to "Latency phase (35-90 min)",
    "q.l35#19.l3" to "Long-term phase (over 90 min)",
    "q.l35#19.r0" to "Deaths mostly from trauma; airway usually open",
    "q.l35#19.r1" to "Survival falls steeply; tightest rescue window",
    "q.l35#19.r2" to "Those with an air pocket become cold-protected; the curve flattens",
    "q.l35#19.r3" to "Hypothermia dominant, with occasional very long survivals",
    "q.l35#19.e" to "Four phases, four different mixes of causes. Teaching the curve as four stages is more useful than memorising single percentages.",
    "q.l35#20.p" to "Match each cause of death with its share.",
    "q.l35#20.l0" to "Asphyxia",
    "q.l35#20.l1" to "Trauma",
    "q.l35#20.l2" to "Hypothermia",
    "q.l35#20.r0" to "65-100%",
    "q.l35#20.r1" to "5-29%",
    "q.l35#20.r2" to "0-4%",
    "q.l35#20.e" to "These proportions are where the treatment priorities come from: ventilation, then bleeding control and splinting, then rewarming.",
    "q.l35#21.p" to "The team starts digging without posting a lookout. What is the biggest risk?",
    "q.l35#21.o0" to "A secondary avalanche buries the rescuers too",
    "q.l35#21.o1" to "Digging is slower",
    "q.l35#21.o2" to "Not enough rope",
    "q.l35#21.o3" to "No records are kept",
    "q.l35#21.e" to "Avalanches rarely happen only once. The lookout is the only person who can call a stop when the second one comes.",
    "q.l35#22.p" to "Why should you not simply pull the casualty out the moment you reach them?",
    "q.l35#22.o0" to "It may worsen a spinal injury and can push snow into the mouth and nose",
    "q.l35#22.o1" to "It damages their clothing",
    "q.l35#22.o2" to "It delays the photographs",
    "q.l35#22.o3" to "It frightens the casualty",
    "q.l35#22.e" to "Clear the face, clear the airway, confirm head and neck position, then clear the chest and body. Do it in the wrong order and someone can be rescued into paralysis.",
    "q.l35#23.p" to "If you are alone at the site, do you dig first or call first?",
    "q.l35#23.o0" to "Dig first; the window is shorter than any response time, and signal when there is a chance",
    "q.l35#23.o1" to "Make the call first",
    "q.l35#23.o2" to "Go back to camp for help",
    "q.l35#23.o3" to "Film a video first",
    "q.l35#23.e" to "Alone, waiting for rescue is close to giving up. When to signal can be found later; digging cannot wait.",
    "q.l35#24.p" to "Why must burial time be recorded to the minute?",
    "q.l35#24.o0" to "It determines which rule the later resuscitation triage follows",
    "q.l35#24.o1" to "For the report",
    "q.l35#24.o2" to "For the insurance claim",
    "q.l35#24.o3" to "For the statistics",
    "q.l35#24.e" to "60 minutes is the dividing line, and in the field it is usually estimated from witness times. Ten minutes of error sends the decision down a different branch.",
    "q.l35#25.p" to "Why does deep burial not equal hopeless?",
    "q.l35#25.o0" to "Depth affects digging time, while medical decisions look at time, airway, and temperature",
    "q.l35#25.o1" to "Because snow melts",
    "q.l35#25.o2" to "Because there are many people",
    "q.l35#25.o3" to "Because deeply buried casualties are colder",
    "q.l35#25.e" to "Using depth as a medical criterion makes people give up early. Depth changes how long you dig, not what you should do.",
    "q.l36#0.p" to "What is the burial time decision line in the 2023 ICAR MedCom guidance?",
    "q.l36#0.o0" to "60 minutes",
    "q.l36#0.o1" to "35 minutes",
    "q.l36#0.o2" to "90 minutes",
    "q.l36#0.o3" to "120 minutes",
    "q.l36#0.e" to "The 2013 version used 35 minutes; in 2023 it was updated to 60. Teaching material must state the year and the basis.",
    "q.l36#1.p" to "Buried 25 minutes, no vital signs, airway partly blocked by loose snow but not packed full. What should you do?",
    "q.l36#1.o0" to "Treat as asphyxia: clear the mouth and nose, give rescue breaths as soon as possible, and start compressions",
    "q.l36#1.o1" to "Treat as obstruction and withhold resuscitation",
    "q.l36#1.o2" to "Rewarm first",
    "q.l36#1.o3" to "Wait for the professional team",
    "q.l36#1.e" to "Under 60 minutes, always treat as asphyxia regardless of airway patency. Loose snow is not obstruction; obstruction requires a completely packed airway.",
    "q.l36#2.p" to "Buried 70 minutes, no vital signs, airway clear, core temperature unmeasurable. What should you do?",
    "q.l36#2.o0" to "Treat as hypothermic cardiac arrest, start CPR, and transport",
    "q.l36#2.o1" to "Treat as asphyxia and withhold resuscitation",
    "q.l36#2.o2" to "Wait for a temperature reading",
    "q.l36#2.o3" to "Provide warmth only",
    "q.l36#2.e" to "A clear airway plus more than 60 minutes makes hypothermic arrest likely enough that resuscitation should be attempted. A cold heart is not dead until it is warm.",
    "q.l36#3.p" to "Buried 70 minutes, no vital signs, mouth and nose completely packed with compacted snow, no way to measure temperature on scene. What should you do?",
    "q.l36#3.o0" to "Treat as asphyxial cardiac arrest and do not start CPR",
    "q.l36#3.o1" to "Start compressions immediately",
    "q.l36#3.o2" to "Dig them out first, then decide",
    "q.l36#3.o3" to "Give two breaths, then stop",
    "q.l36#3.e" to "This is one of the situations the 2023 guidance explicitly lists as a reason not to start resuscitation. If temperature can be measured and is below 30 C, change to attempting resuscitation.",
    "q.l36#4.p" to "Core temperature 28 C, airway clear, no vital signs, buried 80 minutes. What should you do?",
    "q.l36#4.o0" to "Attempt resuscitation and transport to a hospital with extracorporeal rewarming",
    "q.l36#4.o1" to "Withhold resuscitation",
    "q.l36#4.o2" to "Provide warmth only",
    "q.l36#4.o3" to "Wait for the temperature to rise before deciding",
    "q.l36#4.e" to "Below 30 C with a clear airway, attempt resuscitation regardless of burial time. These patients need ECLS-level rewarming.",
    "q.l36#5.p" to "How is airway obstruction defined in avalanche rescue?",
    "q.l36#5.o0" to "Mouth and nose completely packed with compacted snow or debris",
    "q.l36#5.o1" to "A little snow in the mouth",
    "q.l36#5.o2" to "Sputum present",
    "q.l36#5.o3" to "Nasal bleeding",
    "q.l36#5.e" to "The definition must be strict because it decides whether resuscitation starts. When unsure, treat as patent: that is the rescue-oriented default.",
    "q.l36#6.p" to "Which statement about the air pocket is correct?",
    "q.l36#6.o0" to "Survival is higher with an air pocket, but an air pocket is not a criterion for whether to resuscitate",
    "q.l36#6.o1" to "No air pocket means no attempt",
    "q.l36#6.o2" to "An air pocket guarantees survival",
    "q.l36#6.o3" to "The air pocket determines obstruction",
    "q.l36#6.e" to "The 2023 guidance is explicit: air pocket, snow density, and burial depth should not change management. They affect time, not the decision.",
    "q.l36#7.p" to "When may chest compressions begin?",
    "q.l36#7.o0" to "As soon as the chest is exposed; there is no need to wait for full extrication",
    "q.l36#7.o1" to "Only once the whole body is out",
    "q.l36#7.o2" to "Only in hospital",
    "q.l36#7.o3" to "Only after a temperature is measured",
    "q.l36#7.e" to "Waiting until they are dug out wastes several minutes. The 2023 guidance states effective compressions are possible even in an abnormal position while still partly buried.",
    "q.l36#8.p" to "Why give rescue breaths so early?",
    "q.l36#8.o0" to "These patients almost always die of asphyxia, so hypoxia is the first problem",
    "q.l36#8.o1" to "Because it is convenient",
    "q.l36#8.o2" to "To reassure the family",
    "q.l36#8.o3" to "To save oxygen",
    "q.l36#8.e" to "Ventilate first, then worry about circulation. This is the physiological basis of the under-60-minutes rule regardless of airway status.",
    "q.l36#9.p" to "What usually counts as a reason to stop resuscitation?",
    "q.l36#9.o0" to "Fatal injuries, completely frozen body, obstructed airway with burial over 60 minutes, markedly raised potassium",
    "q.l36#9.o1" to "The family asks",
    "q.l36#9.o2" to "It gets dark",
    "q.l36#9.o3" to "Insufficient equipment",
    "q.l36#9.e" to "These come from the 2023 guidance and ICAR termination recommendations. The judgement belongs to trained personnel, not to whoever is digging.",
    "q.l36#10.p" to "What is wrong with deciding whether to resuscitate by first looking at burial depth?",
    "q.l36#10.o0" to "Depth affects digging time and plays no part in the medical decision",
    "q.l36#10.o1" to "Depth cannot be measured",
    "q.l36#10.o2" to "Depth is always shallow",
    "q.l36#10.o3" to "Depth determines survival",
    "q.l36#10.e" to "Treating an engineering question as a medical criterion makes people give up early. The decision looks only at time, airway, and temperature.",
    "q.l36#11.p" to "Under the 2023 guidance, which factors enter the triage decision?",
    "q.l36#11.o0" to "Duration of burial",
    "q.l36#11.o1" to "Whether the airway is clear",
    "q.l36#11.o2" to "Whether core temperature can be measured, and its value",
    "q.l36#11.o3" to "Burial depth",
    "q.l36#11.e" to "The first three form the decision tree. The fourth only changes how long you dig and does not alter the triage.",
    "q.l36#12.p" to "What are the key points of managing hypothermic cardiac arrest?",
    "q.l36#12.o0" to "Handle gently; avoid jolting or bumping",
    "q.l36#12.o1" to "Insulate and warm the whole body",
    "q.l36#12.o2" to "Continuously monitor rhythm and core temperature",
    "q.l36#12.o3" to "Rewarm on scene to 35 C before transporting",
    "q.l36#12.e" to "Effective rewarming is impossible in the field, and insisting on warming first only delays transport. The goal is to reach a centre with ECLS as fast as possible.",
    "q.l36#13.p" to "Which practices around airway and ventilation are correct?",
    "q.l36#13.o0" to "Clear snow and ice from the mouth and nose",
    "q.l36#13.o1" to "When unsure about obstruction, treat the airway as patent",
    "q.l36#13.o2" to "Ventilate before considering compressions",
    "q.l36#13.o3" to "Assess the airway only after full extrication",
    "q.l36#13.e" to "The first three all point to ventilating as early as possible. The last delays the most critical few minutes.",
    "q.l36#14.p" to "Put the sequence for under 60 minutes with no vital signs in order.",
    "q.l36#14.o0" to "Clear mouth and nose, assess the airway",
    "q.l36#14.o1" to "Give rescue breaths immediately",
    "q.l36#14.o2" to "Begin chest compressions",
    "q.l36#14.o3" to "Insulate, protect the spine, and arrange transport",
    "q.l36#14.e" to "Ventilation outranks compressions. This is the biggest difference between asphyxial arrest in avalanche burial and ordinary cardiogenic arrest.",
    "q.l36#15.p" to "Put the triage sequence for over 60 minutes in order.",
    "q.l36#15.o0" to "Confirm the burial really exceeds 60 minutes",
    "q.l36#15.o1" to "Assess whether the airway is completely packed",
    "q.l36#15.o2" to "Attempt to measure core temperature",
    "q.l36#15.o3" to "Follow the matching branch to decide whether to start resuscitation",
    "q.l36#15.e" to "Time first, then airway, then temperature. If any of the three is missing, take the branch that favours attempting resuscitation.",
    "q.l36#16.p" to "The 2023 ICAR MedCom resuscitation decision line is a burial of ______ minutes.",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "The old 35-minute line is withdrawn. Teaching material and question banks must be aligned to 60.",
    "q.l36#17.p" to "When core temperature is below ______ C and the airway is clear, resuscitation should be attempted regardless of burial time.",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 C is the parallel criterion. It brings the cold-protection window into the decision.",
    "q.l36#18.p" to "Hypothermia causes only 0-4% of avalanche deaths, so the order is ______ first and rewarming second.",
    "q.l36#18.a0" to "ventilation",
    "q.l36#18.a1" to "airway",
    "q.l36#18.a2" to "securing the airway",
    "q.l36#18.e" to "Ventilation before rewarming. In avalanche rescue this order is even stricter than in ordinary hypothermia.",
    "q.l36#19.p" to "Match each burial situation with its management (2023 guidance).",
    "q.l36#19.l0" to "Under 60 min, no vital signs",
    "q.l36#19.l1" to "Over 60 min, airway clear, temperature unmeasurable",
    "q.l36#19.l2" to "Over 60 min, airway obstructed, temperature unmeasurable",
    "q.l36#19.l3" to "Temperature measurable below 30 C, airway clear",
    "q.l36#19.r0" to "Treat as asphyxia; give rescue breaths as soon as possible",
    "q.l36#19.r1" to "Treat as hypothermic arrest; start resuscitation",
    "q.l36#19.r2" to "Treat as asphyxial arrest; do not start resuscitation",
    "q.l36#19.r3" to "Attempt resuscitation regardless of time and transport to ECLS",
    "q.l36#19.e" to "These four branches cover most field situations. Remembering the branch conditions is more reliable than memorising conclusions.",
    "q.l36#20.p" to "Match each reason to stop resuscitation with its meaning.",
    "q.l36#20.l0" to "Fatal injuries",
    "q.l36#20.l1" to "Completely frozen body",
    "q.l36#20.l2" to "Obstructed airway and over 60 minutes",
    "q.l36#20.l3" to "Markedly raised potassium",
    "q.l36#20.r0" to "The injuries themselves are not survivable",
    "q.l36#20.r1" to "The body is frozen; rewarming is futile",
    "q.l36#20.r2" to "Manage as asphyxial arrest; do not start resuscitation",
    "q.l36#20.r3" to "Indicates prolonged hypoxia and a very poor prognosis",
    "q.l36#20.e" to "All four are evidence that reversal is no longer medically possible. The judgement should be made by trained personnel and the basis recorded.",
    "q.l36#21.p" to "Someone on scene argues that beyond 35 minutes you should not resuscitate. How do you respond?",
    "q.l36#21.o0" to "That is the 2013 position; 2023 moved it to 60 minutes and added the temperature criterion",
    "q.l36#21.o1" to "They are right",
    "q.l36#21.o2" to "It depends",
    "q.l36#21.o3" to "Let them decide",
    "q.l36#21.e" to "The 35-minute figure still appears widely in Chinese material. Updating it is one of the most practical contributions this lesson makes.",
    "q.l36#22.p" to "Scenario: buried 20 minutes, not breathing when dug out, loose snow in the mouth and nose but not packed full. What should you do?",
    "q.l36#22.o0" to "Clear the mouth and nose, give rescue breaths, start compressions, and transport as soon as possible",
    "q.l36#22.o1" to "Call it obstruction and withhold resuscitation",
    "q.l36#22.o2" to "Rewarm first",
    "q.l36#22.o3" to "Wait for the professional team to decide",
    "q.l36#22.e" to "Under 60 minutes with incomplete obstruction means treat as asphyxia and resuscitate fully. Loose snow is not obstruction.",
    "q.l36#23.p" to "Scenario: buried 70 minutes, airway clear, core temperature 28 C, no vital signs. What should you do?",
    "q.l36#23.o0" to "Continue resuscitation, handle gently, insulate fully, and transport to a hospital with ECLS rewarming",
    "q.l36#23.o1" to "Stop resuscitation",
    "q.l36#23.o2" to "Only warm and observe",
    "q.l36#23.o3" to "Rewarm to 35 C before transporting",
    "q.l36#23.e" to "The core of hypothermic arrest care is getting the patient somewhere rewarming is possible, and resuscitation does not stop on the way.",
    "q.l36#24.p" to "Why is the hypothermic heart described as irritable?",
    "q.l36#24.o0" to "Rough handling can trigger ventricular fibrillation, so move them gently and keep them horizontal",
    "q.l36#24.o1" to "Because it feels cold",
    "q.l36#24.o2" to "Because the rate is slow",
    "q.l36#24.o3" to "Because the pressure is low",
    "q.l36#24.e" to "This is why hypothermic casualties must be moved flat, steady, and gently, and it is a second reason, beyond spinal protection, that avalanche rescue keeps repeating.",
    "q.l36#25.p" to "A team member breaks down during the rescue and insists on stopping. What should the leader do?",
    "q.l36#25.o0" to "Take them off the task but continue resuscitation, with trained personnel judging against the criteria",
    "q.l36#25.o1" to "Stop immediately",
    "q.l36#25.o2" to "Reprimand them",
    "q.l36#25.o3" to "Make them keep compressing",
    "q.l36#25.e" to "The emotion needs to be acknowledged, but medical decisions cannot be made by emotion. Swapping the person rather than stopping is the more responsible handling.",
    "q.l37#0.p" to "What is the order of the four phases of avalanche search?",
    "q.l37#0.o0" to "Signal and clue search, coarse search, fine search, pinpoint probing",
    "q.l37#0.o1" to "Coarse, fine, pinpoint, signal",
    "q.l37#0.o2" to "Pinpoint, fine, coarse",
    "q.l37#0.o3" to "Search, dig, probe",
    "q.l37#0.e" to "The four phases narrow the search step by step: whole slope, then a few metres, then one point on the surface, then a depth. Skip a phase and you pay for it twice.",
    "q.l37#1.p" to "How wide is a transceiver search strip normally?",
    "q.l37#1.o0" to "About 40 m, and about 20 m from the debris edge",
    "q.l37#1.o1" to "10 m",
    "q.l37#1.o2" to "80 m",
    "q.l37#1.o3" to "As wide as possible",
    "q.l37#1.e" to "40 m is a teaching default, not a device limit. If training levels are uncertain, narrow it to 30 m; better to walk more passes.",
    "q.l37#2.p" to "Before search begins, what is the one thing the whole team must do?",
    "q.l37#2.o0" to "Switch every transceiver to receive and turn off phones, cameras, and other interference sources",
    "q.l37#2.o1" to "Dig a test pit first",
    "q.l37#2.o2" to "Take photographs first",
    "q.l37#2.o3" to "Coil the ropes first",
    "q.l37#2.e" to "If someone is still transmitting the search fails, and electronic interference shrinks the effective range. Both must be done as step one.",
    "q.l37#3.p" to "In the signal search phase, what do you look at first?",
    "q.l37#3.o0" to "Visible clues on the snow surface (gloves, pole tips, pack straps)",
    "q.l37#3.o1" to "The transceiver reading",
    "q.l37#3.o2" to "The snowpack structure",
    "q.l37#3.o3" to "The wind direction",
    "q.l37#3.e" to "Surface clues can shrink the search area to tens of metres. Staring at the transceiver makes you miss them.",
    "q.l37#4.p" to "In the coarse search, how close should you get?",
    "q.l37#4.o0" to "3-5 m",
    "q.l37#4.o1" to "20 m",
    "q.l37#4.o2" to "0.5 m",
    "q.l37#4.o3" to "10-15 m",
    "q.l37#4.e" to "The fine search starts at 3-5 m. This is where you switch from running to walking, and where precision starts to matter.",
    "q.l37#5.p" to "During the coarse search the distance reading starts increasing. What does that mean?",
    "q.l37#5.o0" to "You are heading the wrong way; back up along your own track",
    "q.l37#5.o1" to "The signal is too strong",
    "q.l37#5.o2" to "The device is broken",
    "q.l37#5.o3" to "The buried person has moved",
    "q.l37#5.e" to "A transceiver reading is a distance, so a rising number means the wrong direction. Decide fast; do not stand there re-confirming.",
    "q.l37#6.p" to "What is the correct action in the fine search?",
    "q.l37#6.o0" to "Hold the transceiver near the snow, work a cross pattern, find and mark the lowest reading",
    "q.l37#6.o1" to "Stand and turn in a circle",
    "q.l37#6.o2" to "Walk straight downhill",
    "q.l37#6.o3" to "Jab the probe around at random",
    "q.l37#6.e" to "Keeping it close to the snow reduces refraction error through the snowpack. Marking the lowest point gives the probe a clear starting place.",
    "q.l37#7.p" to "When pinpoint probing, the probe should be at 90 degrees to what?",
    "q.l37#7.o0" to "The snow surface (the slope face)",
    "q.l37#7.o1" to "The horizontal",
    "q.l37#7.o2" to "45 degrees to the slope",
    "q.l37#7.o3" to "Any angle",
    "q.l37#7.e" to "Straight down on a slope drives the probe obliquely through the layers and the slope angle inflates the depth reading. Companion rescue probes perpendicular to the snow surface.",
    "q.l37#8.p" to "One probe strike misses. What next?",
    "q.l37#8.o0" to "Extend outward on a 25 cm grid",
    "q.l37#8.o1" to "Switch to a longer probe",
    "q.l37#8.o2" to "Start digging with the shovel",
    "q.l37#8.o3" to "Give up on that point",
    "q.l37#8.e" to "25 cm, about 10 inches, is the standard grid. A larger grid misses the body; a smaller one wastes time.",
    "q.l37#9.p" to "After a hard strike, how do you judge whether it is a person?",
    "q.l37#9.o0" to "Look for soft, springy, body-like resistance, and compare with the ground depth around it",
    "q.l37#9.o1" to "Dig on any hard strike",
    "q.l37#9.o2" to "Check the probe for blood",
    "q.l37#9.o3" to "Listen for sound",
    "q.l37#9.e" to "Rock and ice give hard, brittle resistance; a body is springy. Also, a buried person is usually no deeper than the surrounding ground.",
    "q.l37#10.p" to "After a confirmed strike, what do you do with the probe?",
    "q.l37#10.o0" to "Leave it in place as a marker of position and depth",
    "q.l37#10.o1" to "Pull it out immediately",
    "q.l37#10.o2" to "Push it deeper",
    "q.l37#10.o3" to "Hand it to a teammate",
    "q.l37#10.e" to "A probe left standing is the digger's bullseye and the reference for whether the hole is on target.",
    "q.l37#11.p" to "When burial depth exceeds the probe length, what is correct?",
    "q.l37#11.o0" to "Dig out about 1 m, relocate with the transceiver, then probe again",
    "q.l37#11.o1" to "Keep forcing the probe",
    "q.l37#11.o2" to "Give up",
    "q.l37#11.o3" to "Have someone else probe",
    "q.l37#11.e" to "Forcing it is pointless because it never reaches the bottom. Shorten the distance and relocate; that is the only workable sequence.",
    "q.l37#12.p" to "Why do organised rescue probes stay vertical rather than perpendicular to the slope?",
    "q.l37#12.o0" to "So depth readings are comparable between rescuers and form a consistent search plane",
    "q.l37#12.o1" to "Because it is less tiring",
    "q.l37#12.o2" to "Because it is faster",
    "q.l37#12.o3" to "Because the standard says so",
    "q.l37#12.e" to "An organised probe line is a plane and needs comparable depths. Companion rescue targets a single point, so perpendicular to the surface is more accurate.",
    "q.l37#13.p" to "What should the pre-trip transceiver check include?",
    "q.l37#13.o0" to "Batteries well charged",
    "q.l37#13.o1" to "A transmit test",
    "q.l37#13.o2" to "Knowing how to switch to receive, mark, and suppress",
    "q.l37#13.o3" to "Worn on the body, not at the bottom of the pack",
    "q.l37#13.e" to "Miss any of the four and it fails when it matters. Bottom of the pack is the classic error: if the pack is buried or lost, so is the transceiver.",
    "q.l37#14.p" to "What matters when checking a probe?",
    "q.l37#14.o0" to "Length matched to local snow depth",
    "q.l37#14.o1" to "Tension cord and lock in good order",
    "q.l37#14.o2" to "Can be deployed and locked one-handed",
    "q.l37#14.o3" to "As light as possible",
    "q.l37#14.e" to "Rescue-team probes are recommended at 3 m or more (UIAA 157); personal probes are usually 240-320 cm. Light is nice, but strength and reliable locking matter more.",
    "q.l37#15.p" to "What is correct when several people are buried?",
    "q.l37#15.o0" to "Mark or suppress the first signal",
    "q.l37#15.o1" to "Then search for the second signal",
    "q.l37#15.o2" to "Do not keep confirming one signal at the expense of the rest of the area",
    "q.l37#15.o3" to "Only rescue the nearest one",
    "q.l37#15.e" to "The greatest risk in a multiple burial is finding only one. The mark and suppress functions exist for exactly this.",
    "q.l37#16.p" to "Put a complete search in the correct order.",
    "q.l37#16.o0" to "Whole team switches to receive and interference sources are switched off",
    "q.l37#16.o1" to "Run the signal search along the search strips",
    "q.l37#16.o2" to "Coarse search to 3-5 m",
    "q.l37#16.o3" to "Fine search for the lowest reading, and mark it",
    "q.l37#16.o4" to "Pinpoint probe and leave the probe in place",
    "q.l37#16.e" to "The five steps converge from area to point. Try to skip one and you pay double at the next.",
    "q.l37#17.p" to "Put the pinpoint probing procedure in order.",
    "q.l37#17.o0" to "Start at the lowest reading with the probe at 90 degrees to the snow surface",
    "q.l37#17.o1" to "If nothing, extend on a 25 cm grid",
    "q.l37#17.o2" to "Stop when you feel springy resistance",
    "q.l37#17.o3" to "Leave the probe as a marker and start digging",
    "q.l37#17.e" to "The step most often done wrong is the last: people pull the probe as soon as they strike, and the dig loses its reference.",
    "q.l37#18.p" to "Transceiver search strips are about ______ m apart.",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "Narrow to 30 m when unsure. Strips that are too wide miss the signal, and that is the most common reason a search fails.",
    "q.l37#19.p" to "The pinpoint probing grid is ______ cm on a side.",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "About 10 inches. A larger grid misses the body; a smaller one wastes time.",
    "q.l37#20.p" to "In companion rescue the probe is inserted at 90 degrees to the ______.",
    "q.l37#20.a0" to "snow surface",
    "q.l37#20.a1" to "slope surface",
    "q.l37#20.e" to "Perpendicular to the horizontal inflates the depth reading by the slope angle, the most common geometric error for beginners.",
    "q.l37#21.p" to "Match each search phase with its goal.",
    "q.l37#21.l0" to "Signal and clue search",
    "q.l37#21.l1" to "Coarse search",
    "q.l37#21.l2" to "Fine search",
    "q.l37#21.l3" to "Pinpoint probing",
    "q.l37#21.r0" to "Find the first signal",
    "q.l37#21.r1" to "Close the distance to 3-5 m",
    "q.l37#21.r2" to "Find the point on the surface closest to the buried person",
    "q.l37#21.r3" to "Confirm position and depth with the probe",
    "q.l37#21.e" to "Four goals converging inward. Remembering goals rather than movements adapts better to different terrain.",
    "q.l37#22.p" to "Match each item with its key requirement.",
    "q.l37#22.l0" to "Transceiver",
    "q.l37#22.l1" to "Probe",
    "q.l37#22.l2" to "Shovel",
    "q.l37#22.l3" to "Helmet",
    "q.l37#22.r0" to "Three-antenna digital, worn on the body, mark and suppress understood",
    "q.l37#22.r1" to "Length matched to snow depth, locks one-handed",
    "q.l37#22.r2" to "Metal blade, solid shaft, comes out fast",
    "q.l37#22.r3" to "Worn throughout search and digging",
    "q.l37#22.e" to "The most overlooked of the four is the helmet: snow blocks and ice fall from above while you dig.",
    "q.l37#23.p" to "Someone stops to keep re-confirming the first signal. What should you do?",
    "q.l37#23.o0" to "Remind them to mark or suppress it and keep covering the rest of the area",
    "q.l37#23.o1" to "Let them continue",
    "q.l37#23.o2" to "Stop and join them",
    "q.l37#23.o3" to "Abandon the search",
    "q.l37#23.e" to "In a multiple burial, finding all the signals matters more than perfecting one point.",
    "q.l37#24.p" to "Why switch off phones and cameras during the search?",
    "q.l37#24.o0" to "Electronics interfere with the transceiver signal and shorten the effective range",
    "q.l37#24.o1" to "To save battery",
    "q.l37#24.o2" to "To keep quiet",
    "q.l37#24.o3" to "To stop people taking photos",
    "q.l37#24.e" to "Interference narrows the effective width of each search strip, which indirectly causes misses. This is the rule most often compromised in practice.",
    "q.l37#25.p" to "With only two people, one searches and one digs. Is that reasonable?",
    "q.l37#25.o0" to "Reasonable, but once they get a strike both should relay-dig rather than one digging alone",
    "q.l37#25.o1" to "Unreasonable; both should search",
    "q.l37#25.o2" to "Unreasonable; wait for rescue",
    "q.l37#25.o3" to "Reasonable, and no rotation is needed",
    "q.l37#25.e" to "The key with two is relay digging once located. One person digging continuously exhausts within minutes and is actually slower.",
    "q.l37#26.p" to "Before searching you see hanging snow still above the debris. What should you do?",
    "q.l37#26.o0" to "Post a lookout and pick a safe approach line before starting the search",
    "q.l37#26.o1" to "Charge straight in",
    "q.l37#26.o2" to "Wait for the snow to stop",
    "q.l37#26.o3" to "Abandon the search",
    "q.l37#26.e" to "Rescuers being buried by a secondary avalanche is a real accident type. The lookout and the approach line are part of the search, not extra steps.",
    "q.l37#27.p" to "What is the point of the 10-minute contact and 18-minute extrication targets?",
    "q.l37#27.o0" to "They are internal team benchmarks for training and debriefing, not guarantees",
    "q.l37#27.o1" to "They are medical promises",
    "q.l37#27.o2" to "They are regulatory requirements",
    "q.l37#27.o3" to "They are equipment specifications",
    "q.l37#27.e" to "The targets tell a team where it is slow. Treat them as promises and you lose judgement the first time you miss.",
    "q.l38#0.p" to "What is the first rule of digging?",
    "q.l38#0.o0" to "Always work from the downhill side",
    "q.l38#0.o1" to "Dig straight down from above",
    "q.l38#0.o2" to "Dig down from the uphill side",
    "q.l38#0.o3" to "Dig in horizontally from the side",
    "q.l38#0.e" to "Working from downhill gives three things: snow can be thrown downhill, the trench has a gradient, and the digger is never above the buried person.",
    "q.l38#1.p" to "What does the traditional 1.5 times burial depth rule describe?",
    "q.l38#1.o0" to "How far down the slope from the probe to start digging",
    "q.l38#1.o1" to "The width of the trench",
    "q.l38#1.o2" to "The length of the probe",
    "q.l38#1.o3" to "The digging time",
    "q.l38#1.e" to "The offset leaves room to move snow. It is a rule of thumb, and newer research offers an alternative.",
    "q.l38#2.p" to "What does the 2023 snow conveyor research suggest about the start point?",
    "q.l38#2.o0" to "With three or more diggers and enough space, dig straight down the fall line from the probe",
    "q.l38#2.o1" to "Always offset 1.5 times the burial depth",
    "q.l38#2.o2" to "Dig straight down from above",
    "q.l38#2.o3" to "Dig horizontally in from the side",
    "q.l38#2.e" to "An offset start delays reaching the head. The study's premise is enough hands, so it cannot be applied unconditionally.",
    "q.l38#3.p" to "When is an offset start actually recommended?",
    "q.l38#3.o0" to "When burial is very shallow and the feet sink to nearly that depth, or with too few people for a one-person plan",
    "q.l38#3.o1" to "At any time",
    "q.l38#3.o2" to "When the snow is hard",
    "q.l38#3.o3" to "After dark",
    "q.l38#3.e" to "In those two cases the offset reduces wasted hauling. Otherwise starting at the probe is faster.",
    "q.l38#4.p" to "What width is a conveyor trench usually?",
    "q.l38#4.o0" to "1-2 m",
    "q.l38#4.o1" to "0.3 m",
    "q.l38#4.o2" to "3-4 m",
    "q.l38#4.o3" to "As narrow as possible",
    "q.l38#4.e" to "Too narrow and snow removal is inefficient; too wide and the volume of digging explodes. 1-2 m balances both.",
    "q.l38#5.p" to "Below roughly what trench gradient does snow roll back to the probe?",
    "q.l38#5.o0" to "26 degrees",
    "q.l38#5.o1" to "10 degrees",
    "q.l38#5.o2" to "45 degrees",
    "q.l38#5.o3" to "60 degrees",
    "q.l38#5.e" to "26 degrees is the threshold reported in the research. Too shallow and the snow you threw out slides back, which is wasted work.",
    "q.l38#6.p" to "Which of the three snow-moving techniques is most efficient?",
    "q.l38#6.o0" to "Paddling",
    "q.l38#6.o1" to "Scooping",
    "q.l38#6.o2" to "Cutting blocks",
    "q.l38#6.o3" to "All the same",
    "q.l38#6.e" to "Paddling sweeps snow out in a continuous, high-frequency motion. Cutting blocks only suits hard snow because it requires cutting first.",
    "q.l38#7.p" to "What is the point of appointing a dig leader?",
    "q.l38#7.o0" to "To watch direction, snow above, and the casualty's position, so not everyone has their head down",
    "q.l38#7.o1" to "To supervise the labour",
    "q.l38#7.o2" to "To photograph the scene",
    "q.l38#7.o3" to "To save manpower",
    "q.l38#7.e" to "Once everyone has their head down, the hole drifts off line and the secondary avalanche is missed. The leader is the only one looking up.",
    "q.l38#8.p" to "After reaching the face, the order of work should change to what?",
    "q.l38#8.o0" to "Clear mouth and nose and confirm the airway, then chest and arms, then legs and body",
    "q.l38#8.o1" to "Clear the legs first",
    "q.l38#8.o2" to "Pull the shoulders first",
    "q.l38#8.o3" to "Clear the pack first",
    "q.l38#8.e" to "The chest must be able to expand before ventilation is possible. Clearing legs first delays ventilation, and grabbing shoulders can cause spinal injury.",
    "q.l38#9.p" to "What is the basis for saying one person can still rescue?",
    "q.l38#9.o0" to "In the study conditions, a single digger using a limited-resource conveyor reached 1.5 m within 18 minutes",
    "q.l38#9.o1" to "Because people have potential",
    "q.l38#9.o2" to "Because snow is light",
    "q.l38#9.o3" to "Because the buried person self-rescues",
    "q.l38#9.e" to "Digging rates of about 13.2 cm per minute in hard snow and 25.3 cm per minute in soft snow come from the research, which is why the one-person method is worth practising.",
    "q.l38#10.p" to "Roughly what are the digging rates in hard and soft snow?",
    "q.l38#10.o0" to "About 13 cm per minute in hard snow and 25 cm per minute in soft",
    "q.l38#10.o1" to "About 5 cm per minute in both",
    "q.l38#10.o2" to "About 50 cm per minute in both",
    "q.l38#10.o3" to "Hard snow is faster",
    "q.l38#10.e" to "That gap explains why snow conditions change the expected rescue time, and why block cutting is only for hard snow.",
    "q.l38#11.p" to "What is the most common error when several people dig?",
    "q.l38#11.o0" to "Everyone crowded on one point with no relay or rotation",
    "q.l38#11.o1" to "Digging too wide",
    "q.l38#11.o2" to "Digging too fast",
    "q.l38#11.o3" to "Using a shovel",
    "q.l38#11.e" to "Crowding blocks each other and cannot be sustained. Rotating is far faster than one person grinding it out.",
    "q.l38#12.p" to "Which roles must be assigned for an organised dig?",
    "q.l38#12.o0" to "A dig leader",
    "q.l38#12.o1" to "Diggers and snow haulers",
    "q.l38#12.o2" to "A safety lookout",
    "q.l38#12.o3" to "Someone recording time and position",
    "q.l38#12.e" to "The four roles make direction, stamina, safety, and time somebody's job. Miss one and that element runs out of control.",
    "q.l38#13.p" to "Which practices put the snow you dug out back where it came from?",
    "q.l38#13.o0" to "Digging from above or from the uphill side",
    "q.l38#13.o1" to "A trench gradient shallower than about 26 degrees",
    "q.l38#13.o2" to "Piling snow above the probe",
    "q.l38#13.o3" to "Laying the trench along the fall line",
    "q.l38#13.e" to "The first three all send snow back. The fourth is precisely the correct approach.",
    "q.l38#14.p" to "Which statements about the start point are correct?",
    "q.l38#14.o0" to "The traditional rule is 1.5 times burial depth, cutting across from downhill",
    "q.l38#14.o1" to "Avalanche.org simplifies it to one step back under 1 m depth and two steps for deeper",
    "q.l38#14.o2" to "ISSW 2023 argues for digging down the fall line from the probe when there are enough people",
    "q.l38#14.o3" to "The rule of thumb and the research contradict each other, so you must pick one",
    "q.l38#14.e" to "The three are a principle plus two generations of experience. Teach principle, then rule of thumb, then update, and students will not treat the rule as superstition.",
    "q.l38#15.p" to "Put a standard dig in the correct order.",
    "q.l38#15.o0" to "Confirm the downhill work face and secondary avalanche risk",
    "q.l38#15.o1" to "Cut a V-shaped trench from the start point toward the probe",
    "q.l38#15.o2" to "Organise relay hauling and rotation",
    "q.l38#15.o3" to "Once at the face, clear mouth and nose first",
    "q.l38#15.e" to "The core of the order is safe first, efficient second, airway priority last.",
    "q.l38#16.p" to "Put the sequence after reaching the face in order.",
    "q.l38#16.o0" to "Clear snow and ice from mouth and nose and confirm the airway",
    "q.l38#16.o1" to "Clear snow around the chest and arms so the chest can expand",
    "q.l38#16.o2" to "Clear the legs and the rest of the body",
    "q.l38#16.o3" to "Apply the resuscitation rules and arrange transport",
    "q.l38#16.e" to "This is the opposite of dig it all out then treat, and it is the correct one: the ventilation window is only minutes.",
    "q.l38#17.p" to "The critical gradient for a snow conveyor trench is about ______ degrees.",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "Below that, blocks roll back to the probe and hauling efficiency collapses.",
    "q.l38#18.p" to "The traditional rule suggests starting about ______ times the burial depth downhill from the probe.",
    "q.l38#18.a0" to "1.5",
    "q.l38#18.a1" to "1,5",
    "q.l38#18.e" to "1.5 times is a rule of thumb. With enough people, prefer digging down the fall line from the probe.",
    "q.l38#19.p" to "The companion rescue targets are contact within ______ minutes and extrication within 18.",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 and 18 are internal benchmarks for training and debriefing, used to find which step is slow.",
    "q.l38#20.p" to "Match each snow-moving technique with its condition.",
    "q.l38#20.l0" to "Paddling",
    "q.l38#20.l1" to "Scooping",
    "q.l38#20.l2" to "Cutting blocks",
    "q.l38#20.l3" to "Conveyor relay",
    "q.l38#20.r0" to "Most efficient; suits most loose snow",
    "q.l38#20.r1" to "Second best; good for moving snow out of the trench",
    "q.l38#20.r2" to "Slowest; only for hard snow",
    "q.l38#20.r3" to "The overall organisation when several people work together",
    "q.l38#20.e" to "The efficiency ranking gives paddle first, scoop second, cut blocks only in hard snow. Relay is not a technique but an organisation.",
    "q.l38#21.p" to "Match each common error with its consequence.",
    "q.l38#21.l0" to "Digging from the uphill side",
    "q.l38#21.l1" to "Trench gradient too shallow",
    "q.l38#21.l2" to "Pulling the body out as soon as you reach them",
    "q.l38#21.l3" to "Pulling the probe after a strike",
    "q.l38#21.r0" to "Blocks roll back onto the face; slow and dangerous",
    "q.l38#21.r1" to "Snow flows back and has to be moved repeatedly",
    "q.l38#21.r2" to "May worsen a spinal injury and push snow into the airway",
    "q.l38#21.r3" to "Loses the position and depth reference",
    "q.l38#21.e" to "All four are common, and all four can be avoided by having practised beforehand.",
    "q.l38#22.p" to "The snow is hard and there are only three of you. Where should you start digging?",
    "q.l38#22.o0" to "Down the fall line from the probe, using block cutting through the hard layer",
    "q.l38#22.o1" to "Three times the burial depth back",
    "q.l38#22.o2" to "Straight down from above",
    "q.l38#22.o3" to "Wait for equipment",
    "q.l38#22.e" to "Enough hands means go down the fall line; hard snow only changes the technique to block cutting, not the principle.",
    "q.l38#23.p" to "Why is everyone digging hard together actually slower?",
    "q.l38#23.o0" to "They block each other, cannot sustain it, and nobody is watching the snow above",
    "q.l38#23.o1" to "Because people get hot",
    "q.l38#23.o2" to "Because there are not enough shovels",
    "q.l38#23.o3" to "Because nobody is in charge",
    "q.l38#23.e" to "Digging is extremely intense work and exhausts people within minutes. Rotation plus leadership plus relay turns manpower into speed.",
    "q.l38#24.p" to "You find a large hard snow block beside the buried person during the rescue. What do you do?",
    "q.l38#24.o0" to "Clear the airway path first; do not delay ventilation to move the block",
    "q.l38#24.o1" to "Move the block first",
    "q.l38#24.o2" to "Smash it with the axe",
    "q.l38#24.o3" to "Dig around it",
    "q.l38#24.e" to "The block can wait. The airway window is minutes long and outranks clearing the scene.",
    "q.l38#25.p" to "There is only one shovel at the scene. What is the best use of it?",
    "q.l38#25.o0" to "The strongest person digs while the others push snow with hands and ski poles, rotating",
    "q.l38#25.o1" to "One person digs the whole way",
    "q.l38#25.o2" to "Wait for a second shovel",
    "q.l38#25.o3" to "Use a backpack instead",
    "q.l38#25.e" to "The correct one-shovel method is a limited-resource conveyor: one digs, everyone else moves snow out.",
    "q.l38#26.p" to "A debrief shows contact took 14 minutes. Which step most needs review?",
    "q.l38#26.o0" to "Search and location: which of the four phases was slow",
    "q.l38#26.o1" to "The digging phase",
    "q.l38#26.o2" to "The call for help",
    "q.l38#26.o3" to "Equipment purchasing",
    "q.l38#26.e" to "Contact time is set by search and location; digging sets extrication time. The two metrics have to be reviewed separately.",
    "q.l39#0.p" to "What is the most accurate definition of leadership?",
    "q.l39#0.o0" to "Behaviour that influences others and makes the team willing to reach a goal together",
    "q.l39#0.o1" to "What a person with a title says",
    "q.l39#0.o2" to "The fittest person leads",
    "q.l39#0.o3" to "The most senior person decides",
    "q.l39#0.e" to "Seeing leadership as behaviour rather than position produces more people who dare to speak up, and that is part of your safety margin.",
    "q.l39#1.p" to "How do hard skills and soft skills divide the work?",
    "q.l39#1.o0" to "Hard skills decide whether you can do it; soft skills decide whether the team is willing to do it together",
    "q.l39#1.o1" to "Hard skills matter more",
    "q.l39#1.o2" to "Soft skills are just politeness",
    "q.l39#1.o3" to "They are unrelated",
    "q.l39#1.e" to "Being technically able while the team will not execute amounts to not doing it. In the mountains, execution rate is usually set by soft skills.",
    "q.l39#2.p" to "What are the three layers of responsibility?",
    "q.l39#2.o0" to "Behaviour, thinking, and feeling",
    "q.l39#2.o1" to "Plan, execute, review",
    "q.l39#2.o2" to "Leader, partner, member",
    "q.l39#2.o3" to "Ascend, summit, descend",
    "q.l39#2.e" to "Looking only at behaviour misses how people judge and how they feel. Many recurring problems have their roots in the second and third layers.",
    "q.l39#3.p" to "What does the iceberg model of conflict show?",
    "q.l39#3.o0" to "Positions sit above the waterline, needs below it",
    "q.l39#3.o1" to "All conflict comes from personality",
    "q.l39#3.o2" to "Conflict cannot be resolved",
    "q.l39#3.o3" to "Silence means there is no conflict",
    "q.l39#3.e" to "I must summit is a position; underneath may be not wanting to let the team down. Address the need and the position has room to move.",
    "q.l39#4.p" to "What is the risk of the expert halo?",
    "q.l39#4.o0" to "Confidence and good gear get read as competence, and nobody dares question an obvious error",
    "q.l39#4.o1" to "Experts are too expensive",
    "q.l39#4.o2" to "Experts do not follow orders",
    "q.l39#4.o3" to "Experts are unfit",
    "q.l39#4.e" to "The halo suppresses challenge. The most dangerous state on a team is not nobody knowing, but nobody daring to say hold on, this is wrong.",
    "q.l39#5.p" to "What is the most important duty of a follower?",
    "q.l39#5.o0" to "Ask, feed back, and state clearly when it is time to stop",
    "q.l39#5.o1" to "Obey completely",
    "q.l39#5.o2" to "Avoid causing trouble",
    "q.l39#5.o3" to "Stay silent",
    "q.l39#5.e" to "Treat calling a stop as everyone's authority, not the leader's privilege, and grant it explicitly before departure.",
    "q.l39#6.p" to "When should the turnaround time be set?",
    "q.l39#6.o0" to "Before departure, and made known to the whole team",
    "q.l39#6.o1" to "Just before the summit",
    "q.l39#6.o2" to "Depends on mood",
    "q.l39#6.o3" to "Decided by the fastest person",
    "q.l39#6.e" to "A deadline set on the mountain, tired and goal-focused, will almost certainly be pushed back. Set it before departure and it has force.",
    "q.l39#7.p" to "What typically shows a leader abusing the role?",
    "q.l39#7.o0" to "Using rank to override judgement and treating challenge as disobedience",
    "q.l39#7.o1" to "Listening to opinions",
    "q.l39#7.o2" to "Explaining the basis for decisions",
    "q.l39#7.o3" to "Admitting uncertainty",
    "q.l39#7.e" to "Suppression stops information rising. A leader's most important input comes precisely from people who dare to speak.",
    "q.l39#8.p" to "Someone on the team stays silent the whole time. What is the most likely reason?",
    "q.l39#8.o0" to "They believe speaking will not help, or fear it will damage relationships",
    "q.l39#8.o1" to "They have no opinions",
    "q.l39#8.o2" to "They lack fitness",
    "q.l39#8.o3" to "They cannot follow the language",
    "q.l39#8.e" to "Silence is usually the result of expression costing too much. The leader should lower that cost, for example by asking the youngest first.",
    "q.l39#9.p" to "What is usually the first step in resolving conflict?",
    "q.l39#9.o0" to "Build trust: let the other person feel heard first",
    "q.l39#9.o1" to "Reason with them",
    "q.l39#9.o2" to "Take a vote",
    "q.l39#9.o3" to "Replace them",
    "q.l39#9.e" to "Without trust, reasoning is heard as blame. Acknowledge the feeling first, then discuss facts and options.",
    "q.l39#10.p" to "When helping the team reach the goal conflicts with keeping everyone safe, which wins?",
    "q.l39#10.o0" to "Safety; the objective can be attempted another time",
    "q.l39#10.o1" to "The objective",
    "q.l39#10.o2" to "A vote decides",
    "q.l39#10.o3" to "Whoever paid decides",
    "q.l39#10.e" to "Objectives can be repeated; people cannot. In commercial teams this is especially easily distorted by profit pressure.",
    "q.l39#11.p" to "Which behaviours are soft skills?",
    "q.l39#11.o0" to "Explaining the basis of a decision clearly",
    "q.l39#11.o1" to "Keeping communication going under pressure",
    "q.l39#11.o2" to "Actively asking the quiet ones what they think",
    "q.l39#11.o3" to "Summiting fastest",
    "q.l39#11.e" to "The first three are all about keeping information moving. Speed is a capability, not leadership.",
    "q.l39#12.p" to "How do you reduce the risk of the expert halo?",
    "q.l39#12.o0" to "Encourage newcomers to ask questions",
    "q.l39#12.o1" to "Explain the reasoning when deciding",
    "q.l39#12.o2" to "Appoint one person to argue the opposite case",
    "q.l39#12.o3" to "Let only the most experienced person speak",
    "q.l39#12.e" to "The first three create legitimacy for challenge. The last is precisely a halo amplifier.",
    "q.l39#13.p" to "What counts as legitimate follower behaviour?",
    "q.l39#13.o0" to "Voicing disagreement",
    "q.l39#13.o1" to "Asking for the reasoning behind a decision",
    "q.l39#13.o2" to "Refusing to go on when they judge it unsafe",
    "q.l39#13.o3" to "Complaining privately without saying anything",
    "q.l39#13.e" to "Private complaints change nothing and build distrust. The first three are constructive disobedience.",
    "q.l39#14.p" to "Put the handling of one conflict in order.",
    "q.l39#14.o0" to "Let the other person finish, and confirm what you heard",
    "q.l39#14.o1" to "Separate the position from the need",
    "q.l39#14.o2" to "Offer options and state their costs",
    "q.l39#14.o3" to "Agree, then restate it to confirm",
    "q.l39#14.e" to "The critical step is the second: if the need is not identified, the solution is just each side giving ground, and it returns quickly.",
    "q.l39#15.p" to "Put the process for a high-risk decision in order.",
    "q.l39#15.o0" to "Define the objective and the non-negotiable limits",
    "q.l39#15.o1" to "List the options and what each costs",
    "q.l39#15.o2" to "Weigh likelihood against consequence",
    "q.l39#15.o3" to "Set the deadline in advance and hold to it",
    "q.l39#15.o4" to "Revise as new information arrives",
    "q.l39#15.e" to "This is the skeleton of a nine-step process. Its real value is step four: turning when we must turn back into a number set beforehand.",
    "q.l39#16.p" to "The turnaround time set before a decision is commonly called ______ time.",
    "q.l39#16.a0" to "turnaround",
    "q.l39#16.e" to "It turns resolve into a rule. Written down and spoken out, it has force.",
    "q.l39#17.p" to "The three layers of responsibility are behaviour, thinking, and ______.",
    "q.l39#17.a0" to "feeling",
    "q.l39#17.a1" to "emotion",
    "q.l39#17.e" to "The layer most often overlooked is feeling, and it is usually the earliest signal that something is wrong.",
    "q.l39#18.p" to "Match each role with its core duty.",
    "q.l39#18.l0" to "Leader",
    "q.l39#18.l1" to "Partner or guide",
    "q.l39#18.l2" to "Team member",
    "q.l39#18.l3" to "Safety lookout",
    "q.l39#18.r0" to "Sets goals and limits, and makes decisions understandable",
    "q.l39#18.r1" to "Performs the technical work and reports what is happening",
    "q.l39#18.r2" to "Asks, feeds back, and says stop when needed",
    "q.l39#18.r3" to "Watches environmental risk only, and takes no part in the work",
    "q.l39#18.e" to "The four roles make information, execution, and checks and balances. Without a check, decisions become one person's word.",
    "q.l39#19.p" to "Match each conflict behaviour with the need beneath it.",
    "q.l39#19.l0" to "I have to summit, no matter what",
    "q.l39#19.l1" to "Whatever, you decide",
    "q.l39#19.l2" to "I am fine",
    "q.l39#19.l3" to "He is always holding us back",
    "q.l39#19.r0" to "Fear of being looked down on; needs recognition",
    "q.l39#19.r1" to "Does not want responsibility for the decision; needs protection",
    "q.l39#19.r2" to "Does not want to be a burden; needs to be looked after",
    "q.l39#19.r3" to "Anxious about progress; needs certainty",
    "q.l39#19.e" to "Four behaviours, four needs. Only addressing the need can change the behaviour.",
    "q.l39#20.p" to "The most experienced person says they have done this route and it is fine, but the map shows an icefall ahead. What should you do?",
    "q.l39#20.o0" to "Ask to check the map and the terrain together, using facts to calibrate experience",
    "q.l39#20.o1" to "Trust them",
    "q.l39#20.o2" to "Contradict them on the spot",
    "q.l39#20.o3" to "Split up",
    "q.l39#20.e" to "Experience is valuable input, not a conclusion. Calibrating with the map and the ground respects them without following blindly.",
    "q.l39#21.p" to "A team member keeps saying whatever works for everyone else. What is the most sensible response?",
    "q.l39#21.o0" to "Give concrete options to choose between instead of open questions",
    "q.l39#21.o1" to "Take them at their word",
    "q.l39#21.o2" to "Stop asking them",
    "q.l39#21.o3" to "Decide for them and inform them afterwards",
    "q.l39#21.e" to "Whatever works usually means I do not want the consequences of choosing. Concrete options lower the cost of speaking and let information surface.",
    "q.l39#22.p" to "After deciding to turn around, what should the leader make clear?",
    "q.l39#22.o0" to "The basis (what was seen), the boundary (what would trigger a re-evaluation), and the next step",
    "q.l39#22.o1" to "Only that turning back is not negotiable",
    "q.l39#22.o2" to "Only their feelings",
    "q.l39#22.o3" to "Nothing",
    "q.l39#22.e" to "Explaining the basis turns obedience into understanding, and people who understand will volunteer information next time.",
    "q.l39#23.p" to "Why is voting on whether to keep climbing technically unreliable?",
    "q.l39#23.o0" to "The majority may lack the information to judge, and pressure distorts what people say",
    "q.l39#23.o1" to "Because voting is too slow",
    "q.l39#23.o2" to "Because there are not enough people",
    "q.l39#23.o3" to "Because the leader disagrees",
    "q.l39#23.e" to "A vote turns the decision into a distribution of opinions, while mountain decisions depend on information and criteria. Collect opinions, but judge on evidence.",
    "q.l39#24.p" to "When nobody wants to be the bad guy, what is the most effective way to break the silence?",
    "q.l39#24.o0" to "The leader states their own concern first, making it something the team can discuss",
    "q.l39#24.o1" to "Call someone out",
    "q.l39#24.o2" to "Keep waiting",
    "q.l39#24.o3" to "Turn around without explanation",
    "q.l39#24.e" to "The first person to voice a concern sharply lowers the cost for everyone else. The leader is best placed to be that person.",
    "q.l39#25.p" to "If the leader's own error created danger, what should they do?",
    "q.l39#25.o0" to "Review the error openly and say what changed, rather than playing it down",
    "q.l39#25.o1" to "Do not mention it",
    "q.l39#25.o2" to "Blame the weather",
    "q.l39#25.o3" to "Change the subject",
    "q.l39#25.e" to "Admitting an error raises trust rather than lowering it. Playing it down teaches the team to conceal things, and that is the real danger.",
    "q.l40#0.p" to "What is the first principle of eating at altitude?",
    "q.l40#0.o0" to "Ensure carbohydrate intake; being able to eat at all matters most",
    "q.l40#0.o1" to "Protein first",
    "q.l40#0.o2" to "Fat first",
    "q.l40#0.o3" to "Eat less to save weight",
    "q.l40#0.e" to "Carbohydrate supplies energy fast and uses little oxygen, which makes it the best value fuel at altitude. When you cannot eat, first find a way to get carbohydrate in.",
    "q.l40#1.p" to "Which macronutrient has the highest energy density?",
    "q.l40#1.o0" to "Fat",
    "q.l40#1.o1" to "Carbohydrate",
    "q.l40#1.o2" to "Protein",
    "q.l40#1.o3" to "All the same",
    "q.l40#1.e" to "Fat is about 9 kcal/g, more than double carbohydrate or protein. That is why high-altitude snacks favour nuts and oil sachets.",
    "q.l40#2.p" to "What is wrong with planning to switch to fat burning once you are up there?",
    "q.l40#2.o0" to "Raising the fat-burning share takes long-term training and cannot be switched on in days",
    "q.l40#2.o1" to "Fat tastes bad",
    "q.l40#2.o2" to "Fat is too heavy",
    "q.l40#2.o3" to "Fat makes you cold",
    "q.l40#2.e" to "Metabolic adaptation takes weeks to months. Pre-trip training can improve fat use, but you cannot count on it happening on the mountain.",
    "q.l40#3.p" to "When appetite drops at altitude, what is the most effective strategy?",
    "q.l40#3.o0" to "Small amounts often, choosing energy-dense food that goes down easily",
    "q.l40#3.o1" to "Force down three big meals",
    "q.l40#3.o2" to "Drink only sports drinks",
    "q.l40#3.o3" to "Wait until hungry",
    "q.l40#3.e" to "With a poor appetite, eating a lot at once is nearly impossible. Breaking the total into many small portions is the only sustainable method.",
    "q.l40#4.p" to "What is the main purpose of snacks you can eat while moving?",
    "q.l40#4.o0" to "They keep the rhythm going, so you can fuel without stopping",
    "q.l40#4.o1" to "They make you feel full",
    "q.l40#4.o2" to "They supply protein",
    "q.l40#4.o3" to "They replace meals",
    "q.l40#4.e" to "Once you have to stop to eat, the rhythm breaks. Gels, chews, and bars are valuable because they do not interrupt movement.",
    "q.l40#5.p" to "How does dehydration affect eating?",
    "q.l40#5.o0" to "It suppresses appetite and judgement at the same time, making the energy gap harder to close",
    "q.l40#5.o1" to "No effect",
    "q.l40#5.o2" to "It increases appetite",
    "q.l40#5.o3" to "It only affects thirst",
    "q.l40#5.e" to "Lack of water makes people unwilling to eat and poor at judging how much they are short. Hydration and fuelling must be planned together.",
    "q.l40#6.p" to "What is the correct attitude to BCAAs?",
    "q.l40#6.o0" to "Research links them to ammonia metabolism, but evidence is limited and they cannot replace total calories",
    "q.l40#6.o1" to "They can fully replace food",
    "q.l40#6.o2" to "More is better",
    "q.l40#6.o3" to "They are completely useless",
    "q.l40#6.e" to "Supplements are marginal optimisation. When total calories are short, no supplement makes up the difference.",
    "q.l40#7.p" to "Why is daily energy demand actually higher at altitude?",
    "q.l40#7.o0" to "Cold, load carrying, and hypoxia all raise resting cost and the work of breathing",
    "q.l40#7.o1" to "Because gravity is stronger up high",
    "q.l40#7.o2" to "Because you sleep badly",
    "q.l40#7.o3" to "Because you are nervous",
    "q.l40#7.e" to "Demand rises while appetite falls, and that is where the altitude energy gap comes from. Strategy has to be built around that contradiction.",
    "q.l40#8.p" to "What is a sensible fuelling plan for summit day?",
    "q.l40#8.o0" to "A hot carbohydrate-based meal before leaving, then fuel every 45-60 minutes on the move",
    "q.l40#8.o1" to "Do not eat before leaving, to save weight",
    "q.l40#8.o2" to "Only eat after the summit",
    "q.l40#8.o3" to "Run the day on coffee",
    "q.l40#8.e" to "Leaving on an empty stomach burns through glycogen in the first two hours. Small, frequent fuelling is the only way to last ten hours or more.",
    "q.l40#9.p" to "What does hot food provide at altitude?",
    "q.l40#9.o0" to "Heat, water, and psychological support, and it is easier to accept",
    "q.l40#9.o1" to "Only ritual",
    "q.l40#9.o2" to "Protein",
    "q.l40#9.o3" to "Help digesting fibre",
    "q.l40#9.e" to "Hot food solves three problems at once: energy, hydration, and morale. That is why camp cooking cannot be replaced by dry rations alone.",
    "q.l40#10.p" to "A team member has not been able to eat for two days. What should you be most alert to?",
    "q.l40#10.o0" to "Energy depletion causing hypothermia and poor judgement, possibly also worsening altitude illness",
    "q.l40#10.o1" to "They will lose weight",
    "q.l40#10.o2" to "They will be constipated",
    "q.l40#10.o3" to "They will lack vitamins",
    "q.l40#10.e" to "At altitude, cannot eat is both a cause and a symptom. If it does not improve, assess for altitude illness rather than just urging them to eat more.",
    "q.l40#11.p" to "What are the criteria for high-altitude snack food?",
    "q.l40#11.o0" to "High energy density",
    "q.l40#11.o1" to "Does not go hard in the cold and is easy to chew",
    "q.l40#11.o2" to "Does not need a lot of water to swallow",
    "q.l40#11.o3" to "The bigger the volume the better",
    "q.l40#11.e" to "Cold freezes chocolate and bars rock hard, and at -20 C frozen food is essentially inedible. Big volume means it fills the pack and does not get finished.",
    "q.l40#12.p" to "Which practices around hydration and fuelling are correct?",
    "q.l40#12.o0" to "Drink enough before setting out",
    "q.l40#12.o1" to "Sip frequently while moving",
    "q.l40#12.o2" to "Pair electrolytes with energy intake",
    "q.l40#12.o3" to "Catch up in one go at camp",
    "q.l40#12.e" to "Drinking a large amount at once burdens the gut and does not correct the day's deficit. Spreading intake is what works.",
    "q.l40#13.p" to "Which practices actually raise how much people eat on the mountain?",
    "q.l40#13.o0" to "Bring flavours you already like at home",
    "q.l40#13.o1" to "Portion food into small bags within easy reach",
    "q.l40#13.o2" to "Bring several textures to rotate",
    "q.l40#13.o3" to "Bring only the single highest-calorie item",
    "q.l40#13.e" to "Food aversion is common at altitude: the same flavour for days becomes inedible. Variety and familiarity are practical strategy.",
    "q.l40#14.p" to "Put a day's fuelling rhythm in a sensible order.",
    "q.l40#14.o0" to "Hydrate on waking, with a carbohydrate-based breakfast",
    "q.l40#14.o1" to "Small fuel doses every 45-60 minutes once moving",
    "q.l40#14.o2" to "An extra dose before a long climb",
    "q.l40#14.o3" to "Hot food and fluids on reaching camp",
    "q.l40#14.e" to "The key to the rhythm is do not wait until hungry. Hunger means glycogen is already low, and refuelling then takes 20-30 minutes to bite.",
    "q.l40#15.p" to "What is the correct order for handling cannot eat?",
    "q.l40#15.o0" to "Hydrate first and check for dehydration",
    "q.l40#15.o1" to "Switch to easy, energy-dense food in small frequent portions",
    "q.l40#15.o2" to "Assess for symptoms of altitude illness",
    "q.l40#15.o3" to "If nothing improves, consider descending",
    "q.l40#15.e" to "Dehydration is the reversible first step. If they still cannot eat once dehydration is excluded, assess illness rather than keep coaxing.",
    "q.l40#16.p" to "Fat has an energy density of about ______ kcal/g.",
    "q.l40#16.a0" to "9",
    "q.l40#16.e" to "Carbohydrate and protein are about 4 kcal/g. That gap is why altitude food favours nuts, oil sachets, and chocolate.",
    "q.l40#17.p" to "On the move, fuel roughly every ______ minutes (one figure).",
    "q.l40#17.a0" to "45-60",
    "q.l40#17.a1" to "45 to 60",
    "q.l40#17.a2" to "45",
    "q.l40#17.a3" to "60",
    "q.l40#17.a4" to "50",
    "q.l40#17.e" to "Small and frequent beats large and rare, and is less likely to upset the stomach.",
    "q.l40#18.p" to "Match each fuel with its role.",
    "q.l40#18.l0" to "Carbohydrate",
    "q.l40#18.l1" to "Fat",
    "q.l40#18.l2" to "Protein",
    "q.l40#18.l3" to "Water and electrolytes",
    "q.l40#18.r0" to "Fastest to use; first choice at altitude",
    "q.l40#18.r1" to "Highest energy density; long-term supply",
    "q.l40#18.r2" to "Repair and maintenance, not a main fuel",
    "q.l40#18.r3" to "Maintains circulation and temperature regulation",
    "q.l40#18.e" to "The proportions can shift, but carbohydrate's foundational role cannot be replaced.",
    "q.l40#19.p" to "Match each situation with the right choice.",
    "q.l40#19.l0" to "Long climb",
    "q.l40#19.l1" to "Waiting in extreme cold",
    "q.l40#19.l2" to "Two hours before a summit push",
    "q.l40#19.l3" to "Back at camp",
    "q.l40#19.r0" to "Gels and chews: carbohydrate you can eat while walking",
    "q.l40#19.r1" to "High-fat, high-calorie food that does not freeze hard",
    "q.l40#19.r2" to "A hot carbohydrate-based meal",
    "q.l40#19.r3" to "Hot food plus fluids and electrolytes",
    "q.l40#19.e" to "The same food works differently in different situations. Matching to the situation beats buying a pile of energy bars.",
    "q.l40#20.p" to "A team member brings only protein powder to save weight. What is your judgement?",
    "q.l40#20.o0" to "No: protein is not a main fuel, and altitude demands enough carbohydrate",
    "q.l40#20.o1" to "Fine, protein is purer",
    "q.l40#20.o2" to "Fine, protein is lighter",
    "q.l40#20.o3" to "Depends on taste",
    "q.l40#20.e" to "Protein is an inefficient route to energy and adds kidney load and dehydration risk. At altitude the main fuels must be carbohydrate and fat.",
    "q.l40#21.p" to "Food freezes hard in the cold. What is the most practical fix?",
    "q.l40#21.o0" to "Carry what you plan to eat close to your body for warmth",
    "q.l40#21.o1" to "Soak it in hot water",
    "q.l40#21.o2" to "Bite it",
    "q.l40#21.o3" to "Give up on eating it",
    "q.l40#21.e" to "Body-warm storage is the simplest effective method. Bars in the pack at -20 C are about as edible as a rock.",
    "q.l40#22.p" to "Why is eating itself a high-altitude skill?",
    "q.l40#22.o0" to "Sustaining intake despite hypoxia and poor appetite directly determines stamina and judgement",
    "q.l40#22.o1" to "Because a good appetite is a blessing",
    "q.l40#22.o2" to "Because food is expensive",
    "q.l40#22.o3" to "Because of the photographs",
    "q.l40#22.e" to "An energy deficit does not show up as hunger at first; it shows up as slowing down, feeling cold, and judging badly. Eating steadily is a trained outcome.",
    "q.l40#23.p" to "Which statement about caffeine at altitude is correct?",
    "q.l40#23.o0" to "Moderate use is fine, but it cannot replace rest and hydration",
    "q.l40#23.o1" to "More is better",
    "q.l40#23.o2" to "It is completely forbidden",
    "q.l40#23.o3" to "Use it only to push through when tired",
    "q.l40#23.e" to "Caffeine helps a little with headache, but using it to mask fatigue pushes the problem to a more dangerous moment.",
    "q.l41#0.p" to "What is expedition logistics really about?",
    "q.l41#0.o0" to "Multiple transport legs, each with its own weight limit, timeline, and risk",
    "q.l41#0.o1" to "Sending everything to the trailhead in one go",
    "q.l41#0.o2" to "Buying the most expensive gear",
    "q.l41#0.o3" to "Hiring the best guide",
    "q.l41#0.e" to "Only by treating logistics as a chain rather than a point can you make the right trade-off on each leg. Break one link and everything downstream suffers.",
    "q.l41#1.p" to "What is the correct logic for packing expedition loads?",
    "q.l41#1.o0" to "Pack by order of arrival, so what you need first comes out first",
    "q.l41#1.o1" to "Pack by category",
    "q.l41#1.o2" to "Pack by price",
    "q.l41#1.o3" to "Mix everything together",
    "q.l41#1.e" to "Space is tight and weather is bad at high camp, so digging through bags is very expensive. Packing by arrival order saves a lot of exposure time.",
    "q.l41#2.p" to "What is a climbing permit usually tied to?",
    "q.l41#2.o0" to "A liaison officer, the route, and a validity period",
    "q.l41#2.o1" to "The fee only",
    "q.l41#2.o2" to "The number of people only",
    "q.l41#2.o3" to "The season only",
    "q.l41#2.e" to "All three are bound into the permit. Changing route, overstaying, or swapping people may require re-registration and can incur extra fees.",
    "q.l41#3.p" to "What is the usual rule for a rubbish deposit?",
    "q.l41#3.o0" to "It is refunded only if all rubbish is carried out",
    "q.l41#3.o1" to "You pay it and never get it back",
    "q.l41#3.o2" to "You are fined by weight",
    "q.l41#3.o3" to "Payment is voluntary",
    "q.l41#3.e" to "The point is not revenue but turning carry your rubbish down into an economic constraint. Budget the manpower for it in the plan.",
    "q.l41#4.p" to "Why must porter and staff loads not be increased at will?",
    "q.l41#4.o0" to "There are legal or industry limits; overloading transfers risk to them and slows the whole team",
    "q.l41#4.o1" to "Because they complain",
    "q.l41#4.o2" to "Because gear breaks",
    "q.l41#4.o3" to "Because insurance will not pay",
    "q.l41#4.e" to "Overloading builds your efficiency on someone else's harm and slows the whole transport chain. It is an ethical issue as well as a management one.",
    "q.l41#5.p" to "In a supply plan, what does consumption rate mean?",
    "q.l41#5.o0" to "People x days x daily allowance, used to derive totals and resupply points",
    "q.l41#5.o1" to "How far you walk each day",
    "q.l41#5.o2" to "How much you climb each day",
    "q.l41#5.o3" to "How much each person carries",
    "q.l41#5.e" to "Fuel, canisters, and food are all calculated by rate. Guessing usually means discovering on the coldest days that there is not enough gas.",
    "q.l41#6.p" to "The permit expires but the weather window has not arrived. What is the most sensible action?",
    "q.l41#6.o0" to "Assess the cost of extension and the compliance requirements early, and apply for an extension or reschedule if needed",
    "q.l41#6.o1" to "Keep climbing past the expiry",
    "q.l41#6.o2" to "Switch routes without registering",
    "q.l41#6.o3" to "Ask the liaison officer to bend the rules",
    "q.l41#6.e" to "Climbing past expiry voids the permit, the insurance, and rescue cover at the same time. An extension is expensive, but cheaper than being unrescuable after an accident.",
    "q.l41#7.p" to "Why keep a reserve of supplies?",
    "q.l41#7.o0" to "Weather delays, gear attrition, and team condition all raise consumption",
    "q.l41#7.o1" to "To sell to others",
    "q.l41#7.o2" to "To save weight",
    "q.l41#7.o3" to "For compliance",
    "q.l41#7.e" to "Expedition consumption is never linear. The reserve is the space for a few unplanned extra days.",
    "q.l41#8.p" to "What is the core of high-camp supply management?",
    "q.l41#8.o0" to "A clear ration table and rotation, so no camp has a pile while another runs out",
    "q.l41#8.o1" to "The more the better",
    "q.l41#8.o2" to "Whoever arrives first takes it",
    "q.l41#8.o3" to "Split it evenly",
    "q.l41#8.e" to "A ration table tells each camp what it has and when it will be resupplied. Without one, supplies pile up in the wrong place.",
    "q.l41#9.p" to "What is usually needed for summit certification?",
    "q.l41#9.o0" to "Summit photos or video, a declaration form, and permit and ID documents",
    "q.l41#9.o1" to "Only photographs",
    "q.l41#9.o2" to "Only teammates' testimony",
    "q.l41#9.o3" to "Nothing",
    "q.l41#9.e" to "Requirements vary by peak, but photo, declaration, and permit are nearly universal. Sorting it out afterwards is much harder than preparing before you go.",
    "q.l41#10.p" to "If your luggage does not arrive on the same flight, what must you protect first?",
    "q.l41#10.o0" to "Climbing boots and personal technical gear; they are almost impossible to replace at short notice",
    "q.l41#10.o1" to "Spare clothes",
    "q.l41#10.o2" to "Snacks",
    "q.l41#10.o3" to "Souvenirs",
    "q.l41#10.e" to "Boots that do not fit make walking impossible, and technical gear is a safety matter. Most teams require both to travel with you.",
    "q.l41#11.p" to "What must an expedition logistics plan confirm leg by leg?",
    "q.l41#11.o0" to "Transport mode and backup options",
    "q.l41#11.o1" to "Porterage loads and costs",
    "q.l41#11.o2" to "Timings and checkpoints for each leg",
    "q.l41#11.o3" to "Team members' social media accounts",
    "q.l41#11.e" to "The first three decide whether the plan can move forward. The fourth is unrelated to logistics.",
    "q.l41#12.p" to "What does permit and compliance cost usually include?",
    "q.l41#12.o0" to "Permit and liaison officer fees",
    "q.l41#12.o1" to "The rubbish deposit",
    "q.l41#12.o2" to "Extension fees",
    "q.l41#12.o3" to "Gear depreciation",
    "q.l41#12.e" to "The first three are compliance costs and must be budgeted as separate lines. Depreciation is a personal cost.",
    "q.l41#13.p" to "Which situations should camp supply management avoid?",
    "q.l41#13.o0" to "One camp oversupplied while another runs out of food",
    "q.l41#13.o1" to "Fuel and food stored together, causing contamination",
    "q.l41#13.o2" to "No ration table, relying on memory",
    "q.l41#13.o3" to "Rotating as planned",
    "q.l41#13.e" to "The first three are all failures of management. The last is precisely the correct practice.",
    "q.l41#14.p" to "Put the planning of expedition logistics in order.",
    "q.l41#14.o0" to "Confirm route, permit, and validity period",
    "q.l41#14.o1" to "Set transport mode and deadlines for each leg",
    "q.l41#14.o2" to "Pack by arrival order and build the ration table",
    "q.l41#14.o3" to "Set aside reserves and an extension budget",
    "q.l41#14.e" to "The order is compliance first, then movement, then detail. Book transport before the permit is settled and a change doubles the cost.",
    "q.l41#15.p" to "Put the arrival of supplies at high camp in order.",
    "q.l41#15.o0" to "Road transport to base camp",
    "q.l41#15.o1" to "Porterage or carrying to intermediate camps",
    "q.l41#15.o2" to "Distribution to each high camp against the ration table",
    "q.l41#15.o3" to "Count critical supplies before the summit push (fuel, food, batteries)",
    "q.l41#15.e" to "The last step is most often skipped. Skip the pre-push count and the classic result is discovering a fuel shortage at high camp.",
    "q.l41#16.p" to "Total supply is usually derived as people x days x ______.",
    "q.l41#16.a0" to "daily allowance",
    "q.l41#16.a1" to "daily use",
    "q.l41#16.a2" to "consumption rate",
    "q.l41#16.e" to "Only by writing the rate into the plan can you calculate resupply points and reserves.",
    "q.l41#17.p" to "Many peaks refund the rubbish ______ only if all waste is carried out.",
    "q.l41#17.a0" to "deposit",
    "q.l41#17.a1" to "waste deposit",
    "q.l41#17.e" to "Treat the deposit as a cost line and you will not discover on the last day that you lack the people to carry rubbish.",
    "q.l41#18.p" to "Match each logistics stage with its main risk.",
    "q.l41#18.l0" to "Road transport",
    "q.l41#18.l1" to "Porterage",
    "q.l41#18.l2" to "High-camp rationing",
    "q.l41#18.l3" to "Permit validity",
    "q.l41#18.r0" to "Roads cut, landslides, vehicle delays",
    "q.l41#18.r1" to "Overload, staff condition, weather",
    "q.l41#18.r2" to "Misallocated supplies, running out of food or fuel",
    "q.l41#18.r3" to "Overstaying voids the permit and rescue cover",
    "q.l41#18.e" to "The four stages carry completely different risks, so the contingencies have to be written separately.",
    "q.l41#19.p" to "Match each document with its use.",
    "q.l41#19.l0" to "Permit and liaison documents",
    "q.l41#19.l1" to "Rubbish deposit receipt",
    "q.l41#19.l2" to "Summit photo and declaration form",
    "q.l41#19.l3" to "Insurance and rescue numbers",
    "q.l41#19.r0" to "Access and compliance checks",
    "q.l41#19.r1" to "The basis for refunding the deposit on leaving",
    "q.l41#19.r2" to "Applying for summit certification",
    "q.l41#19.r3" to "Contact and claims after an incident",
    "q.l41#19.e" to "Four documents for four moments: entering, leaving, certifying, and an incident. Miss one and that moment stalls.",
    "q.l41#20.p" to "The team wants to add a fixed-rope section outside the permitted route. What should they do first?",
    "q.l41#20.o0" to "Confirm whether it breaches the permit and protected-area rules, and register it if needed",
    "q.l41#20.o1" to "Fix it first, ask later",
    "q.l41#20.o2" to "Fix it at night",
    "q.l41#20.o3" to "Get someone else to fix it",
    "q.l41#20.e" to "In protected areas fixed rope is often treated as a permanent installation, and without permission it may be a violation. Confirm before you touch anything.",
    "q.l41#21.p" to "The staff team says the workload exceeds the contract. What is the most reasonable handling?",
    "q.l41#21.o0" to "Renegotiate against the contract and actual workload, and record the change",
    "q.l41#21.o1" to "Refuse to talk",
    "q.l41#21.o2" to "Force them to complete it",
    "q.l41#21.o3" to "Pay extra privately without recording it",
    "q.l41#21.e" to "Manpower changes are common on expeditions. Renegotiating with a record protects both sides.",
    "q.l41#22.p" to "Why budget separately for delays?",
    "q.l41#22.o0" to "Weather windows and logistics delays are normal, and a delay means extra lodging, manpower, and permit costs",
    "q.l41#22.o1" to "For shopping",
    "q.l41#22.o2" to "For tips",
    "q.l41#22.o3" to "Because of exchange rates",
    "q.l41#22.e" to "A delay budget is not waste; it is what prevents dangerous decisions made because of money.",
    "q.l41#23.p" to "What is the correct way to handle rubbish when leaving the mountain?",
    "q.l41#23.o0" to "Sort and carry it all out as the permit requires, and keep the receipts",
    "q.l41#23.o1" to "Bury it in the snow",
    "q.l41#23.o2" to "Burn it",
    "q.l41#23.o3" to "Hand it to the next team",
    "q.l41#23.e" to "Burying and burning both break the rules and can contaminate water. Carrying out with receipts is the only way to get the deposit back.",
    "q.l41#24.p" to "What should expedition cargo insurance cover above all?",
    "q.l41#24.o0" to "Trip interruption costs from gear lost or delayed",
    "q.l41#24.o1" to "Freight charges only",
    "q.l41#24.o2" to "Personal injury only",
    "q.l41#24.o3" to "Nothing is needed",
    "q.l41#24.e" to "Delayed gear can end a trip outright. Insurance must cover delay and interruption, not just loss.",
    "q.l41#25.p" to "What is the most effective way to agree workload with a staff team?",
    "q.l41#25.o0" to "Confirm loads, number of carries, and fees in writing before departure, and record changes as they happen",
    "q.l41#25.o1" to "Agree verbally",
    "q.l41#25.o2" to "Sort it out when you arrive",
    "q.l41#25.o3" to "Let them decide",
    "q.l41#25.e" to "Changes are normal on expeditions. Written confirmation and change records avoid a fee argument on the last day.",
    "q.l41#26.p" to "What should a base-camp inventory list contain?",
    "q.l41#26.o0" to "Item, quantity, which camp holds it, date opened, and who is responsible",
    "q.l41#26.o1" to "The total only",
    "q.l41#26.o2" to "The category only",
    "q.l41#26.o3" to "Nothing",
    "q.l41#26.e" to "Where it is, how much is left, and who is using it are the three essentials. Without them, supplies always pile up in the wrong place.",
    "q.l41#27.p" to "If the permit requires all rubbish to be carried out, what must the plan add?",
    "q.l41#27.o0" to "Manpower and porterage capacity for the return, plus weighing and receipts",
    "q.l41#27.o1" to "Rubbish bags only",
    "q.l41#27.o2" to "A fine budget only",
    "q.l41#27.o3" to "Nothing extra",
    "q.l41#27.e" to "On the way out the team is at its weakest and the schedule is tightest, yet the rubbish is heaviest. Put it in the transport plan or it gets out of control on the last day.",
    "q.t01#0.p" to "Which set of information is most useful for judging how hard a hiking route is?",
    "q.t01#0.o0" to "Distance in kilometres",
    "q.t01#0.o1" to "Distance plus total ascent plus surface plus resupply and escape points",
    "q.t01#0.o2" to "The highest altitude",
    "q.t01#0.o3" to "How long it took someone else",
    "q.t01#0.e" to "Distance is only one input. Two 10 km routes, one with 80 m of ascent and one with 800 m, can differ two to three times in time, and whether the surface is dirt, scree, or wet rock decides the risk of a turned ankle.",
    "q.t01#1.p" to "Two routes are both 10 km: A has 80 m of ascent, B has 800 m. What is the main difference?",
    "q.t01#1.o0" to "How good the views are",
    "q.t01#1.o1" to "Time and effort: B is roughly two to three times A",
    "q.t01#1.o2" to "The altitude",
    "q.t01#1.o3" to "Almost none",
    "q.t01#1.e" to "Ascent is the most overlooked variable. As a rule, every 100 m of climbing is roughly another 500 m of flat walking, so 800 m of ascent adds about 4 km out of nowhere.",
    "q.t01#2.p" to "What should a first hike satisfy?",
    "q.t01#2.o0" to "Completable within three hours",
    "q.t01#2.o1" to "Under 300 m of total ascent",
    "q.t01#2.o2" to "A road or village on the way where you can bail out",
    "q.t01#2.o3" to "Full phone signal the whole way",
    "q.t01#2.e" to "The first three are controllable limits. Signal is luck and cannot be part of the plan; many valleys have none at all.",
    "q.t01#3.p" to "Why confirm the escape points before the scenery?",
    "q.t01#3.o0" to "There are usually toilets there",
    "q.t01#3.o1" to "If weather or energy goes wrong you can get down nearby instead of forcing the whole loop",
    "q.t01#3.o2" to "They are good photo spots",
    "q.t01#3.o3" to "The insurance requires it",
    "q.t01#3.e" to "An escape point turns must finish into can choose to stop. The plan should know the nearest exit for every section, and how long it takes to reach from where you are.",
    "q.t01#4.p" to "The same route gets much harder after rain. What is the main reason?",
    "q.t01#4.o0" to "The temperature drops",
    "q.t01#4.o1" to "The surface turns wet and muddy, possibly requiring a stream crossing, so time and ankle risk both rise",
    "q.t01#4.o2" to "The views are worse",
    "q.t01#4.o3" to "There are fewer people",
    "q.t01#4.e" to "Wet ground lengthens the day and raises the chance of slips and sprains. Budget a 4-hour route at 5-6 hours after rain, and re-judge whether the steep descents are passable.",
    "q.t01#5.p" to "A companion says they did this route in four hours. How should you read that?",
    "q.t01#5.o0" to "So I will certainly do it in four",
    "q.t01#5.o1" to "That is an experienced person's pace; the group should allow 1.3-1.5 times, based on the slowest member",
    "q.t01#5.o2" to "It means the route is easy",
    "q.t01#5.o3" to "It is completely unusable",
    "q.t01#5.e" to "Their time reflects their fitness, load, and familiarity. Calculate the group's total on the slowest member, then add breaks, photos, and route-finding, to get close to reality.",
    "q.t01#6.p" to "What is a common rough method for estimating hiking time?",
    "q.t01#6.o0" to "Base time from distance, plus 30 minutes for every 300-500 m of ascent",
    "q.t01#6.o1" to "Distance only",
    "q.t01#6.o2" to "Ascent only",
    "q.t01#6.o3" to "Body weight",
    "q.t01#6.e" to "Distance alone underestimates climbing. Split distance time from ascent time, then multiply by a group factor, and the error shrinks a lot.",
    "q.t01#7.p" to "Why confirm escape points before setting out?",
    "q.t01#7.o0" to "Only with a way down midway can you talk about safety and adjusting the plan",
    "q.t01#7.o1" to "For photographs",
    "q.t01#7.o2" to "To save on tickets",
    "q.t01#7.o3" to "To travel light",
    "q.t01#7.e" to "An escape point is the safety valve of an itinerary. Without one, there is only pressing on.",
    "q.t02#0.p" to "What is the most important fit criterion for hiking footwear?",
    "q.t02#0.o0" to "The tighter the better for stability",
    "q.t02#0.o1" to "The heel does not slide, and the toes do not hit the front on descents",
    "q.t02#0.o2" to "The bigger the more comfortable",
    "q.t02#0.o3" to "Brand and price",
    "q.t02#0.e" to "Try boots in the afternoon, wearing hiking socks, and walk down a slope. A foot that slides front to back rubs the Achilles going up and jams the toes going down, and both directions produce blisters.",
    "q.t02#1.p" to "What most directly causes blisters?",
    "q.t02#1.o0" to "Boots being new",
    "q.t02#1.o1" to "Moisture, friction, and local pressure combined",
    "q.t02#1.o2" to "Walking too long",
    "q.t02#1.o3" to "Sock colour",
    "q.t02#1.e" to "A single factor rarely does it alone. Sand in the boot creates local pressure, sweat softens the skin, and another half hour of walking finishes the job.",
    "q.t02#2.p" to "Which set of practices best prevents blisters?",
    "q.t02#2.o0" to "Tape the hot spots before setting out, keep socks dry, and change socks midway",
    "q.t02#2.o1" to "Wear two pairs of cotton socks",
    "q.t02#2.o2" to "Soak your feet before leaving",
    "q.t02#2.o3" to "Never stop, to avoid taking boots off",
    "q.t02#2.e" to "Tape moves friction off the skin onto the patch, and changing socks solves moisture. Together they stop most blisters.",
    "q.t02#3.p" to "How should lacing be adjusted for a long descent?",
    "q.t02#3.o0" to "Tie tighter to reduce forward sliding",
    "q.t02#3.o1" to "Undo them completely",
    "q.t02#3.o2" to "Leave them as they were for climbing",
    "q.t02#3.o3" to "Only lace the ankle section",
    "q.t02#3.e" to "On a descent the foot slides forward. Tighten the mid and ankle sections and ease the instep: that locks the heel without crushing the top of the foot.",
    "q.t02#4.p" to "A hot spot appears: locally red, warm, and sore to press. What should you do?",
    "q.t02#4.o0" to "Stop and deal with it immediately",
    "q.t02#4.o1" to "Apply tape or a blister patch",
    "q.t02#4.o2" to "Check the boot and sock for creases and grit",
    "q.t02#4.o3" to "Keep walking and deal with it once it has burst",
    "q.t02#4.e" to "A hot spot is reversible and takes two minutes to treat. Once the skin is broken every step enlarges the wound and infection becomes a risk.",
    "q.t02#5.p" to "Why are cotton socks not recommended for long hikes?",
    "q.t02#5.o0" to "Cotton holds sweat without wicking, and once wet it both increases friction and stops insulating",
    "q.t02#5.o1" to "Cotton socks are too expensive",
    "q.t02#5.o2" to "Cotton does not breathe and smells",
    "q.t02#5.o3" to "Cotton socks fade",
    "q.t02#5.e" to "Wet cotton lies against the skin and raises friction; once the temperature drops, wet socks also drain heat fast. Wool or synthetics wick, and still insulate somewhat when wet.",
    "q.t02#6.p" to "What is the purpose of a heel lock lacing pattern?",
    "q.t02#6.o0" to "It pins the heel into the heel cup and reduces toe jamming on descents",
    "q.t02#6.o1" to "It makes the boot tighter",
    "q.t02#6.o2" to "It is quicker to put on",
    "q.t02#6.o3" to "It reduces wear",
    "q.t02#6.e" to "On descents the foot slides forward, and toes jamming into the front is the main cause of black toenails and blisters. Locking the heel solves it directly.",
    "q.t02#7.p" to "How much room is usually recommended in front of the toes when buying hiking footwear?",
    "q.t02#7.o0" to "About a finger's width, because feet swell on long days",
    "q.t02#7.o1" to "A snug fit with no gap",
    "q.t02#7.o2" to "One size larger",
    "q.t02#7.o3" to "Two sizes larger",
    "q.t02#7.e" to "Feet swell slightly over hours of walking. A finger's width prevents toe jamming on descents without being so loose that it rubs.",
    "q.t03#0.p" to "What is the usual upper limit for a hiking load?",
    "q.t03#0.o0" to "10-20% of body weight; beginners should stay at the low end",
    "q.t03#0.o1" to "The heavier the safer",
    "q.t03#0.o2" to "30% of body weight",
    "q.t03#0.o3" to "There is no limit",
    "q.t03#0.e" to "Weight translates directly into joint load and oxygen cost. On a first multi-day hike, keep the pack at 12-15% of body weight and still have energy at the end: that is the right amount.",
    "q.t03#1.p" to "Where should heavy items go when packing?",
    "q.t03#1.o0" to "Close to your back, between the shoulder blades and the waist",
    "q.t03#1.o1" to "At the very bottom",
    "q.t03#1.o2" to "On the outside",
    "q.t03#1.o3" to "In the lid",
    "q.t03#1.e" to "Heavy items close to the back at roughly body centre-of-mass height sway least. At the bottom they drag and load the lower back; on the outside they pull the centre of mass away and the shoulders compensate.",
    "q.t03#2.p" to "How should shoulder straps and hip belt divide the work?",
    "q.t03#2.o0" to "The shoulder straps carry the load",
    "q.t03#2.o1" to "The hip belt carries most of the weight; the straps hold the pack close and stable",
    "q.t03#2.o2" to "The hip belt is decorative",
    "q.t03#2.o3" to "Either way works",
    "q.t03#2.e" to "The hip belt transfers load to the pelvis, the strongest load-bearing part of the body. Over-tight shoulder straps compress blood flow and after a while the arms go numb.",
    "q.t03#3.p" to "What belongs in the lid or on the outside?",
    "q.t03#3.o0" to "Waterproofs, map, headlamp",
    "q.t03#3.o1" to "The day's water and snacks",
    "q.t03#3.o2" to "Tent poles strapped across the outside",
    "q.t03#3.o3" to "The heaviest water bottle",
    "q.t03#3.e" to "The lid and outside carry only what you need at any moment, or what has an awkward shape. Heavy items outside wreck the centre of mass and snag on branches and rock in narrow places.",
    "q.t03#4.p" to "What happens when a pack does not sit against your back?",
    "q.t03#4.o0" to "The centre of mass moves back, the shoulders and neck compensate, and descents become unstable",
    "q.t03#4.o1" to "It only looks bad",
    "q.t03#4.o2" to "Capacity shrinks",
    "q.t03#4.o3" to "No effect",
    "q.t03#4.e" to "With a gap between back panel and back, the pack swings with each step. To steady it people lean forward and shrug, and a few hours later the lower back goes first.",
    "q.t03#5.p" to "Why weigh your pack before setting out?",
    "q.t03#5.o0" to "A baseline number is the only way to judge what is unnecessary",
    "q.t03#5.o1" to "Airports check it",
    "q.t03#5.o2" to "You can post it on social media",
    "q.t03#5.o3" to "It has no practical value",
    "q.t03#5.e" to "Weighing turns it feels a bit heavy into a number. Remove duplicate utensils, excess clothing, and full water bottles from the same pack and you often save two or three kilos.",
    "q.t03#6.p" to "What is the commonly advised upper limit for a hiking pack as a share of body weight?",
    "q.t03#6.o0" to "20-25%",
    "q.t03#6.o1" to "10%",
    "q.t03#6.o2" to "40%",
    "q.t03#6.o3" to "No limit",
    "q.t03#6.e" to "Above that ratio both climbing energy cost and injury risk rise noticeably. Lightweighting starts with the gear you leave behind.",
    "q.t03#7.p" to "What is the main benefit of trekking poles on a descent?",
    "q.t03#7.o0" to "They share knee load and add a balance point",
    "q.t03#7.o1" to "They make you faster",
    "q.t03#7.o2" to "They reduce pack weight",
    "q.t03#7.o3" to "Self-defence",
    "q.t03#7.e" to "Knees take several times the impact going down as going up. Poles move part of that load to the arms and give you a third contact point.",
    "q.t04#0.p" to "What is the correct way to hold a sustainable pace uphill?",
    "q.t04#0.o0" to "An intensity where you can speak full sentences, resting before you are tired",
    "q.t04#0.o1" to "Push to the top in one go, then rest",
    "q.t04#0.o2" to "Follow the fastest person",
    "q.t04#0.o3" to "Always go very slowly",
    "q.t04#0.e" to "The talk test is the simplest intensity gauge. If you cannot finish a sentence, slow down; waiting until you are gasping means a longer recovery.",
    "q.t04#1.p" to "What is the correct rhythm for drinking?",
    "q.t04#1.o0" to "Drink when thirsty",
    "q.t04#1.o1" to "Sip every 20-30 minutes, and add electrolytes in the heat",
    "q.t04#1.o2" to "Drink a litre at once",
    "q.t04#1.o3" to "Drink as little as possible to avoid toilet stops",
    "q.t04#1.e" to "By the time you are thirsty you are already 1-2% of body weight down, and judgement and endurance are both falling. Regular sipping absorbs better than a litre in one go.",
    "q.t04#2.p" to "What is a more effective way to fuel while walking?",
    "q.t04#2.o0" to "30-60 g of carbohydrate per hour, in small frequent doses",
    "q.t04#2.o1" to "One big meal when hungry",
    "q.t04#2.o2" to "Sports drinks only",
    "q.t04#2.o3" to "Willpower until camp",
    "q.t04#2.e" to "The body can only absorb so much carbohydrate per hour, and dumping in too much just bloats you. Eating on the move (nuts, bars, bread) is steadier than stopping for a big meal.",
    "q.t04#3.p" to "Which are early signs of low blood sugar?",
    "q.t04#3.o0" to "Shaky hands and cold sweat",
    "q.t04#3.o1" to "Sudden irritability or slowed reactions",
    "q.t04#3.o2" to "Vision washing out or feeling floaty",
    "q.t04#3.o3" to "Energy suddenly improving",
    "q.t04#3.e" to "When these appear, stop and eat 15-20 g of fast carbohydrate (sugar, juice) and they ease within ten minutes. Pushing on can end in a faint.",
    "q.t04#4.p" to "Why should a rest not exceed about 10 minutes?",
    "q.t04#4.o0" to "The body cools and muscles stiffen, so restarting costs more",
    "q.t04#4.o1" to "Teammates will complain",
    "q.t04#4.o2" to "It wastes time",
    "q.t04#4.o3" to "There is no basis for it",
    "q.t04#4.e" to "After a long stop heart rate drops and muscle temperature falls, and the first kilometre back feels heavy. Several short breaks cost less total time than one long one.",
    "q.t04#5.p" to "When does hitting the wall usually happen on a hike?",
    "q.t04#5.o0" to "Two to three hours in, once glycogen is depleted having barely been replaced",
    "q.t04#5.o1" to "Before setting off on day one",
    "q.t04#5.o2" to "On the descent",
    "q.t04#5.o3" to "When sleep deprived",
    "q.t04#5.e" to "Glycogen stores last roughly 90-120 minutes of moderate work. Past that with no carbohydrate intake you get sudden weakness, dizziness, and no desire to talk.",
    "q.t04#6.p" to "What is the most practical subjective check on whether your pace is right?",
    "q.t04#6.o0" to "The talk test: you can still speak in full sentences",
    "q.t04#6.o1" to "Heart rate numbers",
    "q.t04#6.o2" to "How much you sweat",
    "q.t04#6.o3" to "Cadence",
    "q.t04#6.e" to "Being able to speak in full sentences means you are still aerobic. If you cannot, the intensity is too high and a long day will drain you early.",
    "q.t04#7.p" to "In hot weather, when are electrolytes most often forgotten?",
    "q.t04#7.o0" to "Before setting out and through the first half of the day, not after cramps start",
    "q.t04#7.o1" to "After coming down",
    "q.t04#7.o2" to "Before bed",
    "q.t04#7.o3" to "At meals",
    "q.t04#7.e" to "Cramps mean you are already short. Small amounts, early, throughout the day beats a big dose afterwards.",
    "q.t15#0.p" to "What is the one thing to do with a phone map before heading into the hills?",
    "q.t15#0.o0" to "Download offline maps and confirm offline positioning works",
    "q.t15#0.o1" to "Clear the cache",
    "q.t15#0.o2" to "Switch to dark mode",
    "q.t15#0.o3" to "Turn on battery saver",
    "q.t15#0.e" to "An offline base map plus an offline track is the only thing that still works when you have battery but no signal.",
    "q.t15#1.p" to "On a 1:50,000 map, two centimetres represent how many metres on the ground?",
    "q.t15#1.o0" to "1,000 m",
    "q.t15#1.o1" to "100 m",
    "q.t15#1.o2" to "500 m",
    "q.t15#1.o3" to "2,000 m",
    "q.t15#1.e" to "One centimetre is 500 m, so two is 1,000 m. Get the scale wrong and everything after it is wrong.",
    "q.t15#2.p" to "Tighter contour lines mean what?",
    "q.t15#2.o0" to "A steeper slope",
    "q.t15#2.o1" to "A gentler slope",
    "q.t15#2.o2" to "Higher altitude",
    "q.t15#2.o3" to "A wider path",
    "q.t15#2.e" to "Tight lines mean more height gain over the same horizontal distance. This is how you judge whether a section will be hard work.",
    "q.t15#3.p" to "What is the most reliable way to find direction in the field without electronics?",
    "q.t15#3.o0" to "Compass and map",
    "q.t15#3.o1" to "The way trees grow",
    "q.t15#3.o2" to "The direction of clouds",
    "q.t15#3.o3" to "Instinct",
    "q.t15#3.e" to "Vegetation and cloud patterns are only hints with large errors. Compass plus map is the only stable combination.",
    "q.t15#4.p" to "You think you may have taken a wrong turn. What is the first thing to do?",
    "q.t15#4.o0" to "Stop and look back for three obvious landmarks to confirm your position",
    "q.t15#4.o1" to "Keep walking to find the way",
    "q.t15#4.o2" to "Speed up",
    "q.t15#4.o3" to "Call a friend",
    "q.t15#4.e" to "Stopping and looking back is the only way to turn I think I am lost into I am lost. Walking on just enlarges the error.",
    "q.t15#5.p" to "What should an offline navigation kit contain before you go?",
    "q.t15#5.o0" to "Offline maps",
    "q.t15#5.o1" to "Route tracks (GPX)",
    "q.t15#5.o2" to "A power bank",
    "q.t15#5.o3" to "Social apps",
    "q.t15#5.e" to "The first three ensure it works without signal. Social apps need a network and are no help in the hills.",
    "q.t15#6.p" to "Put one position fix in order.",
    "q.t15#6.o0" to "Open the offline map and locate your current position",
    "q.t15#6.o1" to "Compare with the terrain to confirm the slope aspect and contour pattern",
    "q.t15#6.o2" to "Identify the next obvious landmark",
    "q.t15#6.o3" to "Confirm your direction of travel and the distance remaining",
    "q.t15#6.e" to "Fixing position is not looking at the blue dot; it is the blue dot matching the terrain. The second step is the one that matters.",
    "q.t15#7.p" to "A teammate says following the crowd cannot be wrong. What is the most reasonable reply?",
    "q.t15#7.o0" to "The crowd may be heading somewhere else; check the route before following",
    "q.t15#7.o1" to "Following is easiest",
    "q.t15#7.o2" to "More people always means safer",
    "q.t15#7.o3" to "Just ask someone",
    "q.t15#7.e" to "At a junction the crowd is often on a different route. Checking the map once costs ten seconds.",
    "q.t05#0.p" to "When designing a multi-day route, what should be settled first?",
    "q.t05#0.o0" to "Upper limits on daily distance and ascent, plus resupply and escape points",
    "q.t05#0.o1" to "Which sights are along the way",
    "q.t05#0.o2" to "Which guesthouse to stay in",
    "q.t05#0.o3" to "What photos to take",
    "q.t05#0.e" to "Draw the line for how far the group can walk in a day first, then fit the route inside it. Do it the other way round and you build an itinerary nobody can finish, then walk into the dark to catch up.",
    "q.t05#1.p" to "What is the purpose of a spare day?",
    "q.t05#1.o0" to "So weather or injury delays do not have to be absorbed by walking into the night",
    "q.t05#1.o1" to "To sleep in",
    "q.t05#1.o2" to "Time for photographs",
    "q.t05#1.o3" to "No real purpose",
    "q.t05#1.e" to "Multi-day routes almost always run late. With a spare day, a delay means dropping a section; without one, it becomes night walking or forcing through dangerous ground.",
    "q.t05#2.p" to "Which time costs are most often underestimated?",
    "q.t05#2.o0" to "Route finding and correcting mistakes",
    "q.t05#2.o1" to "Water collection and filtering",
    "q.t05#2.o2" to "Camping, cooking, and packing up",
    "q.t05#2.o3" to "Walking on flat ground",
    "q.t05#2.e" to "Map distance only covers the walking. A real day also contains route finding, water, pitching, cooking, and packing, which together usually add 1.5-2 hours.",
    "q.t05#3.p" to "How dense should escape points be?",
    "q.t05#3.o0" to "At least one junction or village a day where you can get out",
    "q.t05#3.o1" to "One for the whole route is enough",
    "q.t05#3.o2" to "Not needed",
    "q.t05#3.o3" to "One every five days",
    "q.t05#3.e" to "Escape points that sparse effectively write must finish into the plan. Only knowing the nearest exit for every section gives you a real choice.",
    "q.t05#4.p" to "Why should the longest day not be the first day?",
    "q.t05#4.o0" to "Condition and judgement are worst on day one, before adapting to load and altitude",
    "q.t05#4.o1" to "The views are worse on day one",
    "q.t05#4.o2" to "It usually rains on day one",
    "q.t05#4.o3" to "There is no difference",
    "q.t05#4.e" to "The body needs a day or two to adapt: shoulders to the load, feet to the boots, and people to the rhythm. Put the hardest day in the middle and you get more success and fewer injuries.",
    "q.t05#5.p" to "An itinerary says six hours to reach the camp. What else must it state?",
    "q.t05#5.o0" to "A latest arrival time, after which the alternative plan starts",
    "q.t05#5.o1" to "The expected temperature",
    "q.t05#5.o2" to "The companions' phone numbers",
    "q.t05#5.o3" to "Nothing else",
    "q.t05#5.e" to "The estimate is an expectation; the latest time is a decision line. Past it, use the backup camp or turn around rather than gamble.",
    "q.t05#6.p" to "Why build spare days into a multi-day itinerary?",
    "q.t05#6.o0" to "Weather, injury, and transport delays all eat time; without a spare day the only thing left to cut is your safety margin",
    "q.t05#6.o1" to "To rest",
    "q.t05#6.o2" to "For photographs",
    "q.t05#6.o3" to "To save money",
    "q.t05#6.e" to "A spare day is part of the plan. Treat it as waste and what gets squeezed in the end is rest and safety.",
    "q.t05#7.p" to "What arrival time at camp is recommended on a multi-day route?",
    "q.t05#7.o0" to "Leave 1-2 hours of daylight to pitch and cook",
    "q.t05#7.o1" to "The last moment before dark",
    "q.t05#7.o2" to "The later the cooler",
    "q.t05#7.o3" to "It does not matter",
    "q.t05#7.e" to "Pitching after dark is slow and makes it easy to miss hazards on the site. Writing an arrival time into the plan is discipline.",
    "q.t06#0.p" to "How far should a campsite be from water, at minimum?",
    "q.t06#0.o0" to "5 m",
    "q.t06#0.o1" to "60 m",
    "q.t06#0.o2" to "200 m",
    "q.t06#0.o3" to "As close as possible",
    "q.t06#0.e" to "60 m is the minimum in most protected areas. Closer than that contaminates the water and puts you near animals coming to drink at night. Washing and dishes also stay 60 m away.",
    "q.t06#1.p" to "Which locations should a campsite avoid?",
    "q.t06#1.o0" to "Rockfall runout directly below a steep slope",
    "q.t06#1.o1" to "Dry riverbeds",
    "q.t06#1.o2" to "Under an isolated large tree",
    "q.t06#1.o3" to "Where an animal trail passes through",
    "q.t06#1.e" to "All four are fine until they are not: rockfall, flash flood, lightning, animals. A camp is where you stay still all night, so there is no room for that kind of risk.",
    "q.t06#2.p" to "Why should the ground under a tent have a slight slope?",
    "q.t06#2.o0" to "So it drains and does not pool in rain",
    "q.t06#2.o1" to "It sleeps better",
    "q.t06#2.o2" to "It looks tidier",
    "q.t06#2.o3" to "It stops the tent deforming",
    "q.t06#2.e" to "Perfectly flat ground pools water in heavy rain. A 2-3 degree slope sheds it, and with the head slightly higher you do not slide downhill all night.",
    "q.t06#3.p" to "How should a tent be oriented for stability?",
    "q.t06#3.o0" to "Door downwind, long side into the wind",
    "q.t06#3.o1" to "Door into the wind",
    "q.t06#3.o2" to "Any way",
    "q.t06#3.o3" to "Facing the sun",
    "q.t06#3.e" to "With the door downwind you do not get blasted every time you go in or out, and less rain blows inside. Long side to the wind gives the smallest profile and evens the load on the poles.",
    "q.t06#4.p" to "Why not camp on a ridge?",
    "q.t06#4.o0" to "High wind and high lightning risk",
    "q.t06#4.o1" to "The view is too open",
    "q.t06#4.o2" to "The ground is too hard",
    "q.t06#4.o3" to "It is too close to water",
    "q.t06#4.e" to "A ridge is the local high point, with almost no windbreak and the highest chance of a strike in a storm. Camp on the lee side, slightly below the crest.",
    "q.t06#5.p" to "What should you do after packing up camp?",
    "q.t06#5.o0" to "Restore the ground, take all rubbish, and check for anything left behind",
    "q.t06#5.o1" to "Just leave",
    "q.t06#5.o2" to "Bury the rubbish",
    "q.t06#5.o3" to "Leave firewood for the next person",
    "q.t06#5.e" to "Others will use the site. Checking for pegs, packaging, and food scraps, and flattening out the crushed grass, is basic courtesy.",
    "q.t07#0.p" to "What is a rough estimate of fuel use?",
    "q.t07#0.o0" to "30-50 g of gas per person per day",
    "q.t07#0.o1" to "200 g per person per day",
    "q.t07#0.o2" to "50 g per team per day",
    "q.t07#0.o3" to "No estimate needed",
    "q.t07#0.e" to "On a normal trip built around boiling water, 30-50 g per person per day is safe. Low temperatures, melting snow, and real cooking all push it up, so carry a spare canister.",
    "q.t07#1.p" to "What should a food plan prioritise?",
    "q.t07#1.o0" to "High calorie density",
    "q.t07#1.o1" to "Keeps well and does not spoil",
    "q.t07#1.o2" to "Little washing up and few pans to scrub",
    "q.t07#1.o3" to "Requires long simmering",
    "q.t07#1.e" to "Every gram in the pack costs effort and every minute in the pot costs fuel. Dehydrated meals, nuts, oats, and bread, things that just need water, are the best value.",
    "q.t07#2.p" to "Why is carbohydrate preferred at altitude?",
    "q.t07#2.o0" to "It digests with less oxygen and converts quickly into usable energy",
    "q.t07#2.o1" to "Carbohydrate is cheaper",
    "q.t07#2.o2" to "Carbohydrate is lighter",
    "q.t07#2.o3" to "There is no difference",
    "q.t07#2.e" to "Fat has more calories per gram but needs more oxygen to metabolise. In a hypoxic environment, carbohydrate is the oxygen-cheaper fuel.",
    "q.t07#3.p" to "What is the most important precaution when using a stove in a tent?",
    "q.t07#3.o0" to "Keep it ventilated to prevent carbon monoxide poisoning",
    "q.t07#3.o1" to "Keep the flame small",
    "q.t07#3.o2" to "Do not talk",
    "q.t07#3.o3" to "Light a candle to warm up first",
    "q.t07#3.e" to "Early carbon monoxide symptoms (headache, drowsiness) are almost indistinguishable from altitude illness or fatigue, and people often die in their sleep. A tent must have a vent open.",
    "q.t07#4.p" to "After collecting water in the wild, what is the most reliable treatment?",
    "q.t07#4.o0" to "Boil for one minute",
    "q.t07#4.o1" to "Filter through cloth",
    "q.t07#4.o2" to "Let it settle",
    "q.t07#4.o3" to "Add sugar",
    "q.t07#4.e" to "Boiling kills bacteria, viruses, and parasites. Filters are limited against viruses and chemical tablets need waiting time. At altitude the boiling point is lower, so boil for longer.",
    "q.t07#5.p" to "What is the best way to portion food?",
    "q.t07#5.o0" to "By day, labelled with dates, so you do not rummage through everything",
    "q.t07#5.o1" to "All into one big bag",
    "q.t07#5.o2" to "In original packaging, straight into the pack",
    "q.t07#5.o3" to "By flavour",
    "q.t07#5.e" to "Portioning by day controls the rate of consumption and avoids eating too well early and running short later. The date label also tells you which bag to open first.",
    "q.t08#0.p" to "Which three pieces of weather information matter most before setting out?",
    "q.t08#0.o0" to "The 24-48 hour trend, precipitation probability, and wind with feels-like temperature",
    "q.t08#0.o1" to "Today's high",
    "q.t08#0.o2" to "Yesterday's weather",
    "q.t08#0.o3" to "Humidity",
    "q.t08#0.e" to "Today's temperature alone says very little. The trend decides whether to change plans, precipitation decides what to pack, and wind decides how cold it feels and whether you can stand up in the open.",
    "q.t08#1.p" to "A cumulonimbus tops out into an anvil. What does that mean?",
    "q.t08#1.o0" to "The storm is mature, possibly with heavy rain, hail, and lightning",
    "q.t08#1.o1" to "The weather is about to clear",
    "q.t08#1.o2" to "Just high cloud, no impact",
    "q.t08#1.o3" to "Snow is coming",
    "q.t08#1.e" to "An anvil means the updraft has hit the tropopause and the storm is at its strongest. Get off ridges, open ground, and away from isolated trees as fast as possible.",
    "q.t08#2.p" to "Which signs may precede a thunderstorm?",
    "q.t08#2.o0" to "Thunder in the distance",
    "q.t08#2.o1" to "The cloud base darkening and lowering",
    "q.t08#2.o2" to "A sudden wind shift and temperature drop",
    "q.t08#2.o3" to "Hair standing up and skin tingling",
    "q.t08#2.e" to "The last one means charge is already strong and a strike may be very close. Drop height immediately, crouch with feet together, and do not lie flat.",
    "q.t08#3.p" to "What is the right thing to do in a thunderstorm?",
    "q.t08#3.o0" to "Leave ridges and isolated trees, lose height, and keep about 50 m between people",
    "q.t08#3.o1" to "Shelter under the tallest tree",
    "q.t08#3.o2" to "Move fast along the ridge",
    "q.t08#3.o3" to "Huddle together for warmth",
    "q.t08#3.e" to "Lightning favours the highest point. Spreading out means that if one person is struck the others can still help; huddling turns one strike into several casualties.",
    "q.t08#4.p" to "What is the earliest and most reliable sign of hypothermia?",
    "q.t08#4.o0" to "Persistent shivering, clumsy movement, and slurred speech",
    "q.t08#4.o1" to "Red skin",
    "q.t08#4.o2" to "Heavy sweating",
    "q.t08#4.o3" to "A slow heartbeat",
    "q.t08#4.e" to "Shivering is the body generating heat to save itself. Shivering stopping is not improvement; it may be a worse sign. Treat in order: shelter, dry clothes, insulation, warm drink.",
    "q.t08#5.p" to "At the same temperature, why does wind feel colder?",
    "q.t08#5.o0" to "Wind speeds up heat loss from the skin, so feels-like temperature is well below air temperature",
    "q.t08#5.o1" to "Wind blows cold air into your clothes",
    "q.t08#5.o2" to "It is psychological",
    "q.t08#5.o3" to "Humidity changes",
    "q.t08#5.e" to "That is wind chill. Zero degrees with a 40 km/h wind feels close to -10. Decide what to wear from the feels-like temperature, not the air temperature.",
    "q.t09#0.p" to "Above 3,000 m, how fast should sleeping altitude rise?",
    "q.t09#0.o0" to "No more than 500 m per day",
    "q.t09#0.o1" to "1,000 m per day",
    "q.t09#0.o2" to "1,500 m per day",
    "q.t09#0.o3" to "No limit",
    "q.t09#0.e" to "Climb high, sleep low is the usual strategy: you may go higher during the day, but do not sleep more than 500 m higher each day. Ascending too fast is the main trigger for AMS.",
    "q.t09#1.p" to "What is the most typical picture of acute mountain sickness (AMS)?",
    "q.t09#1.o0" to "Headache with nausea or poor appetite, plus dizziness and fatigue",
    "q.t09#1.o1" to "Joint pain and a rash",
    "q.t09#1.o2" to "A persistent cough with blood",
    "q.t09#1.o3" to "A fever of 39 C",
    "q.t09#1.e" to "Only the combination means something: a headache alone may be dehydration or tiredness, but add poor appetite and fatigue and it looks more like AMS.",
    "q.t09#2.p" to "Once AMS symptoms appear, what is the correct management?",
    "q.t09#2.o0" to "Stop ascending; acclimatise in place or descend",
    "q.t09#2.o1" to "Take medication and keep ascending as planned",
    "q.t09#2.o2" to "Drink more and walk it off",
    "q.t09#2.o3" to "Hurry to camp and rest there",
    "q.t09#2.e" to "The core rule is never ascend with symptoms. If symptoms are mild and conditions allow, stay another day at the same altitude; if they worsen, descend.",
    "q.t09#3.p" to "Which are danger signs requiring immediate descent?",
    "q.t09#3.o0" to "Breathless even at rest",
    "q.t09#3.o1" to "Unsteady walking, as if drunk",
    "q.t09#3.o2" to "Confusion or abnormal behaviour",
    "q.t09#3.o3" to "A mild headache",
    "q.t09#3.e" to "These three suggest HAPE or HACE may already be developing. There is only one direction of treatment: descend, give oxygen, and seek medical support.",
    "q.t09#4.p" to "Why is sleeping lower recommended?",
    "q.t09#4.o0" to "Breathing shallows at night and hypoxia is worst then; sleeping lower reduces the overnight drop",
    "q.t09#4.o1" to "It is quieter lower down",
    "q.t09#4.o2" to "It is warmer lower down",
    "q.t09#4.o3" to "The views are better",
    "q.t09#4.e" to "Ventilation falls during sleep, so saturation is lower than when awake. Putting camp a few hundred metres below the day's high point is a margin you give your night-time self.",
    "q.t09#5.p" to "Are fitter people less likely to get altitude sickness?",
    "q.t09#5.o0" to "Not necessarily; rate of ascent and individual variation matter most",
    "q.t09#5.o1" to "Yes, the fitter the safer",
    "q.t09#5.o2" to "No, the fitter the more likely",
    "q.t09#5.o3" to "It depends only on age",
    "q.t09#5.e" to "Fitter people often walk faster and climb higher, which makes problems more likely. Keeping fitness and acclimatisation separate is one of the most important habits at altitude.",
    "q.t10#0.p" to "How many layers does a high-altitude hiking clothing system usually have?",
    "q.t10#0.o0" to "Base layer, insulation, and windproof shell",
    "q.t10#0.o1" to "Underwear and a jacket",
    "q.t10#0.o2" to "Cotton, wool, and a raincoat",
    "q.t10#0.o3" to "The more the better",
    "q.t10#0.e" to "Layering is not about wearing more, it is about adjusting at any moment. Take the shell off when you heat up and put it straight back on when you stop; getting chilled usually happens in that ten-minute break.",
    "q.t10#1.p" to "Roughly how much does UV intensity increase per 1,000 m of altitude?",
    "q.t10#1.o0" to "10-12%",
    "q.t10#1.o1" to "2%",
    "q.t10#1.o2" to "50%",
    "q.t10#1.o3" to "It does not change",
    "q.t10#1.e" to "Thinner air filters less UV. Add snow reflection of about 80% and the real exposure on your face and nose is close to being sunburned twice.",
    "q.t10#2.p" to "What should sun protection at altitude include?",
    "q.t10#2.o0" to "UV400 sunglasses",
    "q.t10#2.o1" to "SPF50+ sunscreen, reapplied every 2-3 hours",
    "q.t10#2.o2" to "Lip balm with sun protection",
    "q.t10#2.o3" to "A sun hat or head covering",
    "q.t10#2.e" to "Four items, four places: eyes, skin, lips, face. Lips have no melanin protection and crack most easily, and they are the most often forgotten.",
    "q.t10#3.p" to "Why do hands and feet always get cold first?",
    "q.t10#3.o0" to "The body protects core temperature first and constricts blood vessels in the limbs",
    "q.t10#3.o1" to "Hands and feet have little fat",
    "q.t10#3.o2" to "Hands and feet move less",
    "q.t10#3.o3" to "It is psychological",
    "q.t10#3.e" to "It is a normal survival mechanism, so warming the trunk is the priority: once the core is warm, blood returns to the extremities. Adding gloves without warming the trunk has limited effect.",
    "q.t10#4.p" to "Gloves and socks are wet. What should you do?",
    "q.t10#4.o0" to "Change them immediately; wet layers keep draining heat",
    "q.t10#4.o1" to "Keep them on, they will dry as you warm up",
    "q.t10#4.o2" to "Wring them out",
    "q.t10#4.o3" to "Change tomorrow",
    "q.t10#4.e" to "Wet fabric conducts heat several times faster than dry. Once hands and feet are numb, movement slows and both gear handling and walking get more error-prone.",
    "q.t10#5.p" to "What is snow blindness?",
    "q.t10#5.o0" to "UV burn of the cornea, usually with severe pain, light sensitivity, and tearing 6-12 hours later",
    "q.t10#5.o1" to "Eye strain from reflected light",
    "q.t10#5.o2" to "Frostbite of the eyeball",
    "q.t10#5.o3" to "Vitamin A deficiency",
    "q.t10#5.e" to "Snow blindness is delayed: nothing during the day, pain at night. Prevention is almost entirely sunglasses, and they are just as necessary under overcast skies and in snow fog.",
    "q.t11#0.p" to "What should you do if you cannot eat at altitude?",
    "q.t11#0.o0" to "Eat proactively in small frequent amounts, carbohydrate first",
    "q.t11#0.o1" to "Do not eat; wait for an appetite",
    "q.t11#0.o2" to "Drink only hot water",
    "q.t11#0.o3" to "Get through it on coffee",
    "q.t11#0.e" to "At altitude an energy deficit directly slows acclimatisation. Breaking one big meal into several small snacks is far easier than forcing down a full portion.",
    "q.t11#1.p" to "What is the simplest indicator of whether you are drinking enough?",
    "q.t11#1.o0" to "Urine staying pale yellow",
    "q.t11#1.o1" to "Drinking a full 3 L a day",
    "q.t11#1.o2" to "Not feeling thirsty",
    "q.t11#1.o3" to "Body weight not changing",
    "q.t11#1.e" to "Urine colour is the most direct hydration indicator. Dark yellow means you are behind; completely clear may mean too much intake, and you should add some electrolytes.",
    "q.t11#2.p" to "What is the most common cause of poor sleep at altitude?",
    "q.t11#2.o0" to "Low oxygen causing periodic breathing that keeps waking you from light sleep",
    "q.t11#2.o1" to "The tent is uncomfortable",
    "q.t11#2.o2" to "It is too quiet",
    "q.t11#2.o3" to "Walking too little during the day",
    "q.t11#2.e" to "It is physiological, so do not worry about not getting eight hours. What does deserve attention is insomnia with headache and nausea; that may be AMS.",
    "q.t11#3.p" to "Which practices help you sleep better at altitude?",
    "q.t11#3.o0" to "Do not eat a heavy meal before bed",
    "q.t11#3.o1" to "Do not drink alcohol",
    "q.t11#3.o2" to "Drink a moderate amount before bed",
    "q.t11#3.o3" to "Use acetazolamide under medical supervision",
    "q.t11#3.e" to "The first three are things you can do yourself; the last needs a doctor's assessment. Medication is a medical decision, not something teammates should recommend to each other.",
    "q.t11#4.p" to "Why is alcohol more dangerous at altitude than at home?",
    "q.t11#4.o0" to "It suppresses breathing, worsens hypoxia, and masks AMS symptoms",
    "q.t11#4.o1" to "It dehydrates you",
    "q.t11#4.o2" to "It keeps you awake",
    "q.t11#4.o3" to "It is high in calories",
    "q.t11#4.e" to "Respiratory drive is already weakened at altitude and alcohol suppresses it further. Worse, drunkenness looks a lot like early HACE, which makes misjudging it easy.",
    "q.t11#5.p" to "Can you use caffeine at altitude?",
    "q.t11#5.o0" to "Yes in moderation, but it cannot replace rest and hydration",
    "q.t11#5.o1" to "Not at all",
    "q.t11#5.o2" to "The more the better",
    "q.t11#5.o3" to "Only in the morning",
    "q.t11#5.e" to "One coffee will not cause altitude sickness, nor will it cure fatigue. It helps a little with headache, but using it to push through only postpones the problem.",
    "q.t12#0.p" to "What is the most important mental preparation before a trip?",
    "q.t12#0.o0" to "Accept that you may not get there, and treat turning back as part of the plan",
    "q.t12#0.o1" to "Resolve never to give up",
    "q.t12#0.o2" to "Write the goal on the back of your hand",
    "q.t12#0.o3" to "Do not tell your family the itinerary",
    "q.t12#0.e" to "Write turning back into the plan and people will stop when it is right. Make must finish the goal instead and they tend to ignore the danger signs in order to finish.",
    "q.t12#1.p" to "What is the best thing to do if you cannot keep up with the group?",
    "q.t12#1.o0" to "Say so honestly and ask the group to walk at the slowest person's pace",
    "q.t12#1.o1" to "Grit your teeth and keep up so you do not hold anyone back",
    "q.t12#1.o2" to "Drop quietly to the back",
    "q.t12#1.o3" to "Head down alone without telling anyone",
    "q.t12#1.e" to "Forcing the pace empties you within hours, and after that errors and injuries are more likely. Walking at the slowest person's pace is both efficient and safe.",
    "q.t12#2.p" to "Which approaches help with exposure and a fear of heights?",
    "q.t12#2.o0" to "Look at your feet section by section instead of staring into the distance",
    "q.t12#2.o1" to "Slow your breathing and put attention on the movement",
    "q.t12#2.o2" to "Keep three points of contact and make small movements",
    "q.t12#2.o3" to "Close your eyes and move fast",
    "q.t12#2.e" to "Fear makes breathing shallow and movement stiff, and stiffness is exactly where mistakes come from. Pulling attention back to the next foothold is the most effective fix.",
    "q.t12#3.p" to "What is wrong with the thought we have come this far, it cannot be for nothing?",
    "q.t12#3.o0" to "It uses time already spent as a reason to keep taking risk",
    "q.t12#3.o1" to "It is not positive enough",
    "q.t12#3.o2" to "It makes you walk too slowly",
    "q.t12#3.o3" to "Nothing is wrong with it",
    "q.t12#3.e" to "Time already spent does not come back if you continue, but continuing can bring new and irreversible costs. Judge by what is ahead, not what is behind.",
    "q.t12#4.p" to "What should the group agree before departure?",
    "q.t12#4.o0" to "Who has authority to call a stop, the regrouping point if separated, and how long silence triggers the emergency plan",
    "q.t12#4.o1" to "Who takes the photographs",
    "q.t12#4.o2" to "Who walks fastest",
    "q.t12#4.o3" to "Who carries the most",
    "q.t12#4.e" to "Make calling a stop an authority granted in advance rather than a test of personal courage, and people will speak when it matters. The same goes for the regrouping point and the overdue plan.",
    "q.t12#5.p" to "Someone suddenly goes quiet, flat, and slow. What should you consider first?",
    "q.t12#5.o0" to "Possibly not enough energy or water, or early altitude illness or hypothermia",
    "q.t12#5.o1" to "They are just in a bad mood",
    "q.t12#5.o2" to "It is a personality issue",
    "q.t12#5.o3" to "They need time alone",
    "q.t12#5.e" to "In the field, a change in mood is often the first face of a physical problem. Feed them, water them, add clothing, check their condition, and only then talk about feelings.",
    "q.t13#0.p" to "How often should resupply points be on a long route?",
    "q.t13#0.o0" to "Every 3-5 days",
    "q.t13#0.o1" to "One for the whole route",
    "q.t13#0.o2" to "Every day",
    "q.t13#0.o3" to "No resupply needed",
    "q.t13#0.e" to "Resupply points cut a long route into small sections, each of which can be assessed and exited independently. Too long a gap and one weather delay drags the whole route with it.",
    "q.t13#1.p" to "Roughly how much does a day of dehydrated food weigh?",
    "q.t13#1.o0" to "600-800 g",
    "q.t13#1.o1" to "200 g",
    "q.t13#1.o2" to "1.5 kg",
    "q.t13#1.o3" to "3 kg",
    "q.t13#1.e" to "600-800 g of dehydrated main meals provides about 2,500-3,000 kcal. Add nuts and oil sachets and the total weight goes up a little.",
    "q.t13#2.p" to "Which regulations must be confirmed before a long route?",
    "q.t13#2.o0" to "Park or protected-area permits",
    "q.t13#2.o1" to "Whether open fires are allowed",
    "q.t13#2.o2" to "Whether all rubbish must be carried out",
    "q.t13#2.o3" to "Whether drones may be flown",
    "q.t13#2.e" to "None of these is trivial: entering without a permit can get you turned back, illegal fires start wildfires easily in dry seasons, and drones are completely banned in many protected areas.",
    "q.t13#3.p" to "Why carry some cash?",
    "q.t13#3.o0" to "Mountain resupply points, villages, and transport often take cash only, and the network may be down",
    "q.t13#3.o1" to "It looks professional",
    "q.t13#3.o2" to "It makes a good doorstop",
    "q.t13#3.o3" to "It helps with weighing",
    "q.t13#3.e" to "The more remote the place, the more it runs on cash. Small notes are most useful, and keep an emergency amount separate from day-to-day spending.",
    "q.t13#4.p" to "How should emergency communication be set up for a long route?",
    "q.t13#4.o0" to "A satellite communicator or personal locator beacon, plus a paper map and itinerary left with your contact",
    "q.t13#4.o1" to "Phone only",
    "q.t13#4.o2" to "A whistle only",
    "q.t13#4.o3" to "Nothing is needed",
    "q.t13#4.e" to "Many long routes have no signal at all. A device can send messages, while the map and itinerary let the person at home know where you went and when to raise the alarm.",
    "q.t13#5.p" to "When a plan keeps a 20% margin, what does that mean in practice?",
    "q.t13#5.o0" to "Twenty percent more food, fuel, time, and cash than the theoretical figure",
    "q.t13#5.o1" to "Carry extra water only",
    "q.t13#5.o2" to "Keep spare time only",
    "q.t13#5.o3" to "It is unnecessary",
    "q.t13#5.e" to "A margin is room left for the unexpected. A one-day weather delay, two extra stove meals, an unplanned fare should not put the trip immediately on the back foot.",
    "q.t14#0.p" to "What is the basic field treatment for a sprained ankle?",
    "q.t14#0.o0" to "Rest, ice, compression, elevation (RICE)",
    "q.t14#0.o1" to "Heat and massage immediately",
    "q.t14#0.o2" to "Keep walking, it will loosen up",
    "q.t14#0.o3" to "Rub the bruise out hard",
    "q.t14#0.e" to "Heat and massage in the acute phase increase bleeding and swelling. For the first 48 hours use ice, compression, and elevation, then return to movement gradually.",
    "q.t14#1.p" to "What is the correct order for treating a hypothermic casualty?",
    "q.t14#1.o0" to "Shelter from wind, dry clothing, insulate from the ground, warm drinks for the alert, and rewarm slowly",
    "q.t14#1.o1" to "Hot drink first, then change clothes",
    "q.t14#1.o2" to "Rub the hands and feet to restore circulation",
    "q.t14#1.o3" to "Make the casualty walk fast to generate heat",
    "q.t14#1.e" to "Stop the heat loss first, then think about rewarming. Rubbing the limbs and forcing walking can push cold blood back to the core and make things worse.",
    "q.t14#2.p" to "If you suspect heat stroke, what is the first step?",
    "q.t14#2.o0" to "Move to shade and airflow, loosen clothing, and start active cooling",
    "q.t14#2.o1" to "Give large amounts of plain water",
    "q.t14#2.o2" to "Keep them walking so they sweat it out",
    "q.t14#2.o3" to "Cover them up to prevent a chill",
    "q.t14#2.e" to "Heat stroke is a failure of heat loss, so cooling comes before fluids. If consciousness is altered, never force fluids because of the risk of aspiration.",
    "q.t14#3.p" to "What must a distress message include?",
    "q.t14#3.o0" to "An exact location or coordinates",
    "q.t14#3.o1" to "Number of people and injuries",
    "q.t14#3.o2" to "Gear and supplies on hand",
    "q.t14#3.o3" to "Contact details and remaining battery",
    "q.t14#3.e" to "Rescuers first need to know where, how many, how badly hurt, and how long you can hold out. Incomplete information often costs hours of back-and-forth.",
    "q.t14#4.p" to "How should an overdue plan be set up?",
    "q.t14#4.o0" to "Agree fixed check-in times, and who calls whom, and when the alarm is raised, after how long",
    "q.t14#4.o1" to "Decide at the time",
    "q.t14#4.o2" to "Just tell family roughly where you are going",
    "q.t14#4.o3" to "No plan is needed",
    "q.t14#4.e" to "The plan must be specific about times and actions: no word by this hour means a phone call, and a few hours later means contacting local rescue. Contact me if anything happens is not a plan.",
    "q.t14#5.p" to "When must you call for rescue rather than keep managing it yourself?",
    "q.t14#5.o0" to "Cannot move unaided, altered consciousness, or condition steadily worsening",
    "q.t14#5.o1" to "Just a bit tired",
    "q.t14#5.o2" to "Boots rubbing",
    "q.t14#5.o3" to "Two hours behind schedule",
    "q.t14#5.e" to "Decide the threshold in advance: able to walk, alert, improving means self-evacuate; unable to walk, not alert, deteriorating means call early.",
    "q.t16#0.p" to "What is the basic three-zone division of a campsite?",
    "q.t16#0.o0" to "Sleeping, cooking, and toilet kept apart",
    "q.t16#0.o1" to "Men, women, and shared",
    "q.t16#0.o2" to "Tents, vehicles, and fire",
    "q.t16#0.o3" to "No zoning needed",
    "q.t16#0.e" to "Zoning solves three problems: fire risk, smells attracting animals, and cross-contamination in hygiene.",
    "q.t16#1.p" to "What is a sensible cathole depth and distance from water?",
    "q.t16#1.o0" to "15-20 cm deep, more than 60 m from water",
    "q.t16#1.o1" to "5 cm deep, 5 m from water",
    "q.t16#1.o2" to "As deep and as far as possible",
    "q.t16#1.o3" to "No hole needed",
    "q.t16#1.e" to "Too shallow and it will not break down; too close and it contaminates the water. 60 m is the standard distance.",
    "q.t16#2.p" to "What is the correct way to deal with toilet paper?",
    "q.t16#2.o0" to "Bag it and carry it out",
    "q.t16#2.o1" to "Burn it",
    "q.t16#2.o2" to "Bury it in the cathole",
    "q.t16#2.o3" to "Drop it in the grass",
    "q.t16#2.e" to "Burning paper is a fire risk in dry seasons, and buried paper reappears after snowmelt or when animals dig. Carrying it out is cleanest.",
    "q.t16#3.p" to "How should washing-up water be disposed of?",
    "q.t16#3.o0" to "Strain out the scraps, scatter the water, and carry the scraps out",
    "q.t16#3.o1" to "Pour it into the stream",
    "q.t16#3.o2" to "Pour it beside the tent",
    "q.t16#3.o3" to "Pour it into the cathole",
    "q.t16#3.e" to "Scraps are pollution and an animal attractant, so strain and carry them out; scatter the remaining water rather than dumping it in one spot.",
    "q.t16#4.p" to "What are the three key things for foot care while hiking?",
    "q.t16#4.o0" to "Wash your feet daily, change to dry socks, and air the boots",
    "q.t16#4.o1" to "Walk more",
    "q.t16#4.o2" to "Wear thicker socks",
    "q.t16#4.o3" to "Apply ointment",
    "q.t16#4.e" to "Blisters and maceration both come from moisture plus friction. Keeping things dry beats any ointment.",
    "q.t16#5.p" to "Which practices should camp hygiene avoid?",
    "q.t16#5.o0" to "Eating inside the tent",
    "q.t16#5.o1" to "Leaving food scraps at camp",
    "q.t16#5.o2" to "Washing dishes beside the water",
    "q.t16#5.o3" to "Putting boots in the tent porch before bed",
    "q.t16#5.e" to "The first three bring animals and contamination into the sleeping area. Boots in the porch is normal practice, but shake them out first.",
    "q.t16#6.p" to "Put the morning pack-up in order.",
    "q.t16#6.o0" to "Pack the sleeping bag away in its dry bag first",
    "q.t16#6.o1" to "Collect the small items and rubbish inside the tent",
    "q.t16#6.o2" to "Take the tent down and shake off dew and frost",
    "q.t16#6.o3" to "Sweep the site and confirm nothing is left behind",
    "q.t16#6.e" to "The last step is the one most often missed, and left-behind items are the most common way to fail leave-no-trace.",
    "q.t16#7.p" to "There are animal signs near camp (droppings, digging). What should you do?",
    "q.t16#7.o0" to "Hang food high or store it sealed, well away from where you sleep",
    "q.t16#7.o1" to "Keep cooking in the same place",
    "q.t16#7.o2" to "Feed it a little",
    "q.t16#7.o3" to "Put the food in the tent",
    "q.t16#7.e" to "Animals are drawn by smell. Food in the tent is the most dangerous choice because it leads them straight to where you sleep.",
    "q.t17#0.p" to "What is the most practical hydration indicator on a hike?",
    "q.t17#0.o0" to "Urine staying pale yellow",
    "q.t17#0.o1" to "Thirst",
    "q.t17#0.o2" to "How much you sweat",
    "q.t17#0.o3" to "Body weight",
    "q.t17#0.e" to "By the time you are thirsty you are already short of fluid. Urine colour is the cheapest daily self-check.",
    "q.t17#1.p" to "What is the core criterion for heat stroke?",
    "q.t17#1.o0" to "Core temperature above 40 C with altered mental status",
    "q.t17#1.o1" to "Sweating heavily",
    "q.t17#1.o2" to "Red skin",
    "q.t17#1.o3" to "A fast heartbeat",
    "q.t17#1.e" to "Altered mental status is the key signal. Without a thermometer in the field, judge on mental state and cool immediately.",
    "q.t17#2.p" to "What is the correct order of heat illness treatment?",
    "q.t17#2.o0" to "Move to shade, loosen clothing, cool, then replace electrolytes",
    "q.t17#2.o1" to "Fluids first, then cool",
    "q.t17#2.o2" to "Massage the limbs first",
    "q.t17#2.o3" to "Give water first",
    "q.t17#2.e" to "Cooling comes first. Fluids take time to work, while heat damages organs immediately.",
    "q.t17#3.p" to "What should you do in the first 48 hours after a sprained ankle?",
    "q.t17#3.o0" to "Ice, compression, elevation; avoid heat and hard rubbing",
    "q.t17#3.o1" to "Heat and massage",
    "q.t17#3.o2" to "Keep walking",
    "q.t17#3.o3" to "Rub the bruise out hard",
    "q.t17#3.e" to "Heat and rubbing in the acute phase increase bleeding and swelling. All four steps of RICE matter.",
    "q.t17#4.p" to "What is correct when a heat casualty is confused?",
    "q.t17#4.o0" to "Do not force fluids; use wet cooling and seek help as fast as possible",
    "q.t17#4.o1" to "Pour water into their mouth",
    "q.t17#4.o2" to "Give salt tablets",
    "q.t17#4.o3" to "Let them drink on their own",
    "q.t17#4.e" to "With an unreliable swallow reflex, fluids risk aspiration. The only effective measures then are cooling and professional rescue.",
    "q.t17#5.p" to "How should a blister that affects walking be treated?",
    "q.t17#5.o0" to "Disinfect, drain from the edge, keep the roof, and cover with a dressing",
    "q.t17#5.o1" to "Tear the whole thing off",
    "q.t17#5.o2" to "Puncture it in the middle",
    "q.t17#5.o3" to "Ignore it",
    "q.t17#5.e" to "The blister roof is the best dressing you have. Puncturing the middle tears easily.",
    "q.t17#6.p" to "Which conditions raise the risk of heat illness on a hike?",
    "q.t17#6.o0" to "High humidity and no wind",
    "q.t17#6.o1" to "Continuous climbing at midday",
    "q.t17#6.o2" to "Drinking plain water without electrolytes",
    "q.t17#6.o3" to "Wearing light, breathable clothing",
    "q.t17#6.e" to "The first three weaken heat loss or electrolyte balance. Light breathable clothing is precisely a cooling measure.",
    "q.t17#7.p" to "Which items most belong in a hiking first-aid kit?",
    "q.t17#7.o0" to "Blister plasters and dressings",
    "q.t17#7.o1" to "Pain and fever relief",
    "q.t17#7.o2" to "An elastic bandage",
    "q.t17#7.o3" to "Antibiotics",
    "q.t17#7.e" to "The first three cover the most common hiking problems: feet, pain, and sprains. Antibiotics need a doctor's judgement.",
    "q.t17#8.p" to "Put the treatment of heat exhaustion in order.",
    "q.t17#8.o0" to "Stop moving and get into shade",
    "q.t17#8.o1" to "Loosen clothing and start active cooling",
    "q.t17#8.o2" to "Replace fluids containing electrolytes",
    "q.t17#8.o3" to "Monitor consciousness and condition, and call for help if needed",
    "q.t17#8.e" to "The core of the order is stop heat exposure first. Walking on pushes heat exhaustion toward heat stroke.",
    "q.t17#9.p" to "A teammate suddenly has a headache, nausea, and cool clammy skin during a midday climb. What should you do?",
    "q.t17#9.o0" to "Stop immediately, cool them, replace electrolytes, and observe",
    "q.t17#9.o1" to "Keep walking to camp",
    "q.t17#9.o2" to "Give a painkiller and carry on",
    "q.t17#9.o3" to "Have them put on more clothes",
    "q.t17#9.e" to "These are the classic signs of heat exhaustion. Continuing deteriorates fast, and heat stroke can kill within tens of minutes.",
    "q.t18#0.p" to "Which pair of measurements matters most when judging whether a river can be forded?",
    "q.t18#0.o0" to "Depth multiplied by velocity",
    "q.t18#0.o1" to "Depth",
    "q.t18#0.o2" to "River width",
    "q.t18#0.o3" to "Water temperature",
    "q.t18#0.e" to "At the same depth, doubling the velocity doubles the force. Measuring only the depth is the most common misjudgement in hiking.",
    "q.t18#1.p" to "What is the engineering safety limit for fording?",
    "q.t18#1.o0" to "A depth-velocity product above 1.0 m2/s counts as uncrossable",
    "q.t18#1.o1" to "Depth above 0.5 m",
    "q.t18#1.o2" to "Velocity above 3 m/s",
    "q.t18#1.o3" to "Width above 20 m",
    "q.t18#1.e" to "1.0 assumes a healthy adult, a short crossing, and no heavy pack. A team may set an internal limit of 0.8, but that is a conservative choice, not the standard.",
    "q.t18#2.p" to "When judging velocity by throwing a stick, what is the criterion?",
    "q.t18#2.o0" to "If you have to jog to keep up with it, it is faster than walking pace",
    "q.t18#2.o1" to "Whether the stick sinks",
    "q.t18#2.o2" to "Whether the stick spins",
    "q.t18#2.o3" to "Whether there is foam on the surface",
    "q.t18#2.e" to "Walking along the bank to follow it is the most direct test. Needing to jog to keep up means the current is already too strong.",
    "q.t18#3.p" to "Deeper than what should send you to another crossing point?",
    "q.t18#3.o0" to "The thigh of the shortest person on the team",
    "q.t18#3.o1" to "The leader's waist",
    "q.t18#3.o2" to "The knee",
    "q.t18#3.o3" to "The chest",
    "q.t18#3.e" to "Measure against the shortest person, not the strongest. The team is limited by its weakest member; that is the iron rule of river crossing.",
    "q.t18#4.p" to "What does the run-out mean?",
    "q.t18#4.o0" to "The downstream area the current would carry you into if you slipped",
    "q.t18#4.o1" to "A steep bank",
    "q.t18#4.o2" to "The gradient of the riverbed",
    "q.t18#4.o3" to "The catchment upstream",
    "q.t18#4.e" to "If the run-out holds a waterfall, log jams, or a steep bank, the point is unusable even if the water in front of you is shallow.",
    "q.t18#5.p" to "What should you look for first when choosing a crossing point?",
    "q.t18#5.o0" to "A wide, shallow section",
    "q.t18#5.o1" to "A narrow, deep section",
    "q.t18#5.o2" to "The outside of a bend",
    "q.t18#5.o3" to "Near a fallen log",
    "q.t18#5.e" to "Wider sections are usually shallower and slower; the outside of a bend is deep and fast, and logs are lethal entrapment hazards.",
    "q.t18#6.p" to "How much of a rise in water level is enough to make a previously safe point dangerous?",
    "q.t18#6.o0" to "15 cm",
    "q.t18#6.o1" to "1 m",
    "q.t18#6.o2" to "50 cm",
    "q.t18#6.o3" to "Such a small change makes no difference",
    "q.t18#6.e" to "15 cm can change both depth and velocity significantly, especially where glacial melt feeds the river.",
    "q.t18#7.p" to "Which conditions mean abandoning a crossing point outright?",
    "q.t18#7.o0" to "You cannot see the bed and the water is turbid",
    "q.t18#7.o1" to "Log jams or a steep bank downstream",
    "q.t18#7.o2" to "Heavy rain upstream recently",
    "q.t18#7.o3" to "A gentle gravel riverbed",
    "q.t18#7.e" to "The first three mean the situation cannot be assessed or a mistake cannot be absorbed. A gravel bed is exactly what you want.",
    "q.t18#8.p" to "What must be done with equipment before fording?",
    "q.t18#8.o0" to "Undo the sternum strap",
    "q.t18#8.o1" to "Loosen the shoulder straps",
    "q.t18#8.o2" to "Tighten external attachments to reduce water scooping",
    "q.t18#8.o3" to "Put phone and medication in a dry bag",
    "q.t18#8.e" to "The first two let you escape the pack; the last two keep critical items from being lost. All four are done before stepping in.",
    "q.t18#9.p" to "Put the decision sequence for a crossing in order.",
    "q.t18#9.o0" to "First ask whether you have to cross at all (detour, bridge, wait for the water to drop)",
    "q.t18#9.o1" to "Choose a point and measure depth and velocity",
    "q.t18#9.o2" to "Confirm the whole team is handling packs and clothing the same way",
    "q.t18#9.o3" to "Cross using a formation or a solo method",
    "q.t18#9.e" to "The first question removes most of the risk. Many people skip it and go straight to working out how to cross.",
    "q.t18#10.p" to "The river is clearly higher in the afternoon than at dawn. Why?",
    "q.t18#10.o0" to "The daily cycle of glacial melt, peaking in the afternoon",
    "q.t18#10.o1" to "It rains more in the afternoon",
    "q.t18#10.o2" to "Reservoir releases upstream",
    "q.t18#10.o3" to "Evaporation",
    "q.t18#10.e" to "Melt-fed rivers follow a very regular daily cycle: lowest at dawn, highest in the afternoon. Schedule crossings for the morning where you can.",
    "q.t19#0.p" to "What is the correct triangle formation?",
    "q.t19#0.o0" to "Three people facing inward, gripping shoulders or packs, with only one person moving one leg at a time",
    "q.t19#0.o1" to "Three abreast holding hands, walking together",
    "q.t19#0.o2" to "Three in single file",
    "q.t19#0.o3" to "Two carrying one",
    "q.t19#0.e" to "Stepping together means the whole formation loses support at once. Hand-in-hand tires quickly and slips; grip shoulders or packs instead.",
    "q.t19#1.p" to "In a line formation, where should the strongest person stand?",
    "q.t19#1.o0" to "At the ends, especially the upstream end",
    "q.t19#1.o1" to "In the middle",
    "q.t19#1.o2" to "At the back",
    "q.t19#1.o3" to "Anywhere",
    "q.t19#1.e" to "The upstream end takes the main force of the current and the downstream end catches anyone who slips. Put beginners in the middle with a strong person on each side.",
    "q.t19#2.p" to "What is the verbal cadence for moving in formation?",
    "q.t19#2.o0" to "One step, stop, one step",
    "q.t19#2.o1" to "Left right left, continuously",
    "q.t19#2.o2" to "No talking",
    "q.t19#2.o3" to "Everyone at their own pace",
    "q.t19#2.e" to "A shared cadence exists so that only one person moves at a time. Stepping simultaneously is the most common formation error.",
    "q.t19#3.p" to "What is the first rule after a fall?",
    "q.t19#3.o0" to "Do not stand up",
    "q.t19#3.o1" to "Stand up immediately",
    "q.t19#3.o2" to "Grab the rope",
    "q.t19#3.o3" to "Grab a log",
    "q.t19#3.e" to "A foot can jam in rocks or a log, and the current will push the person under: foot entrapment is the classic mechanism of river-crossing deaths.",
    "q.t19#4.p" to "What is the correct posture after a fall?",
    "q.t19#4.o0" to "Face up, feet downstream and near the surface, head up",
    "q.t19#4.o1" to "Swim face down",
    "q.t19#4.o2" to "Tread water upright",
    "q.t19#4.o3" to "Curl into a ball",
    "q.t19#4.e" to "Face up with feet downstream lets you push off obstacles with your feet instead of standing on the bottom, and it protects your head.",
    "q.t19#5.p" to "Which statement about the pack hip belt while fording is correct?",
    "q.t19#5.o0" to "US practice says undo it so you can dump the pack; New Zealand MSC says keep it done up as flotation; what matters is that the team is consistent",
    "q.t19#5.o1" to "It must always be undone",
    "q.t19#5.o2" to "It must always be done up",
    "q.t19#5.o3" to "It makes no difference",
    "q.t19#5.e" to "Each school has its own premise. The real danger is half the team undone and half done up, which makes rescue coordination impossible.",
    "q.t19#6.p" to "The pack snags on a rock. What should you do?",
    "q.t19#6.o0" to "Raise both arms and slip out of the shoulder straps; losing the pack is better",
    "q.t19#6.o1" to "Hold on hard",
    "q.t19#6.o2" to "Dive down to undo it",
    "q.t19#6.o3" to "Wait for a teammate",
    "q.t19#6.e" to "A snagged pack pins you against the current. Raising the arms and slipping out is the fastest escape.",
    "q.t19#7.p" to "What is the correct sequence when getting out on the far bank?",
    "q.t19#7.o0" to "Undo the hip belt, then slip the upstream shoulder strap off, and let the pack float in front of you for support as you stand",
    "q.t19#7.o1" to "Stand up first, then deal with the pack",
    "q.t19#7.o2" to "Throw the pack onto the bank",
    "q.t19#7.o3" to "Climb straight out",
    "q.t19#7.e" to "The pack's buoyancy can help, but the wrong order costs you support. Hip belt first, then the upstream shoulder strap, is standard practice.",
    "q.t19#8.p" to "What preparation does a formation crossing need?",
    "q.t19#8.o0" to "Practise the grips and cadence on dry land",
    "q.t19#8.o1" to "Decide who takes the upstream end",
    "q.t19#8.o2" to "Agree a single policy for hip belts and sternum straps",
    "q.t19#8.o3" to "Let each person choose their own method",
    "q.t19#8.e" to "A formation depends on coordination, and coordination can only come from agreeing beforehand. Everyone doing their own thing breaks the formation in the water.",
    "q.t19#9.p" to "Which statements about rope-assisted crossing are correct?",
    "q.t19#9.o0" to "Most teams are not proficient enough, so the risk can exceed the benefit",
    "q.t19#9.o1" to "The rope should be anchored on the bank, never tied to a person",
    "q.t19#9.o2" to "Cross on the downstream side of the rope",
    "q.t19#9.o3" to "A rope tensioned straight across the current is the safest option",
    "q.t19#9.e" to "A taut horizontal rope pushes people under the water. Rope systems are a specialist technique, not something to invent on the spot.",
    "q.t19#10.p" to "Put a formation crossing in the correct order.",
    "q.t19#10.o0" to "Choose the point and confirm the run-out is safe",
    "q.t19#10.o1" to "Whole team undoes sternum straps and agrees the hip belt policy",
    "q.t19#10.o2" to "Practise the formation and cadence on dry land",
    "q.t19#10.o3" to "Shuffle across as a unit on the cadence, one person stepping at a time",
    "q.t19#10.o4" to "On the far bank, change into dry clothes and have a hot drink",
    "q.t19#10.e" to "The last step is the one most often skipped: cold-water hypothermia is often more likely than a fall.",
    "q.t19#11.p" to "A teammate suddenly stops moving in the water. What is most likely?",
    "q.t19#11.o0" to "A foot is trapped; help immediately and keep them face up",
    "q.t19#11.o1" to "They are resting",
    "q.t19#11.o2" to "They are enjoying the view",
    "q.t19#11.o3" to "They are waiting for a command",
    "q.t19#11.e" to "Suddenly stopping is the classic sign of foot entrapment. What they need is do not struggle, stay face up, and someone approaching from upstream.",
    "q.t20#0.p" to "What is the most common equipment failure on a long trail?",
    "q.t20#0.o0" to "Soles delaminating and air pads leaking",
    "q.t20#0.o1" to "Pack straps breaking",
    "q.t20#0.o2" to "Tent holes",
    "q.t20#0.o3" to "Trekking poles snapping",
    "q.t20#0.e" to "Both lead directly to cannot walk or cannot sleep. Pre-trip checks should look at them first.",
    "q.t20#1.p" to "A sole starts to delaminate. What is the best field fix?",
    "q.t20#1.o0" to "Tape it to stop it spreading, then use proper adhesive once in town",
    "q.t20#1.o1" to "Melt it with fire",
    "q.t20#1.o2" to "Tie it up with cord",
    "q.t20#1.o3" to "Keep walking and deal with it when it falls off",
    "q.t20#1.e" to "Tape limits the damage; it does not repair it. Let it keep peeling and the whole sole comes away, at which point you really cannot walk.",
    "q.t20#2.p" to "A tent pole snaps. What is the most practical field repair?",
    "q.t20#2.o0" to "Slide a repair sleeve over the break and keep using it",
    "q.t20#2.o1" to "Wrap it in a ball of tape",
    "q.t20#2.o2" to "Throw the tent away",
    "q.t20#2.o3" to "Replace the whole pole with a branch",
    "q.t20#2.e" to "A sleeve restores most of the strength. Tape gets you one or two nights and lets the break get worse.",
    "q.t20#3.p" to "A down jacket gets a small puncture. What is correct?",
    "q.t20#3.o0" to "Apply a patch and press it down; do not pat the jacket",
    "q.t20#3.o1" to "Pat off the escaping down",
    "q.t20#3.o2" to "Seal it with flame",
    "q.t20#3.o3" to "Sew it tight",
    "q.t20#3.e" to "Patting keeps pushing down out through the pinhole. A patch plus gentle pressure is the most effective way to stop the loss.",
    "q.t20#4.p" to "Which is NOT a common cause of a leaking sleeping pad?",
    "q.t20#4.o0" to "Being left in the sun",
    "q.t20#4.o1" to "Sharp stones underneath",
    "q.t20#4.o2" to "A valve not closed properly",
    "q.t20#4.o3" to "Seam fatigue",
    "q.t20#4.e" to "Sunlight does not puncture the air chamber directly. Beyond the first three, the usual culprit is ground that was not cleared.",
    "q.t20#5.p" to "What is worth carrying in a hiking repair kit?",
    "q.t20#5.o0" to "Dyneema tape",
    "q.t20#5.o1" to "Pad patches and adhesive",
    "q.t20#5.o2" to "Spare buckles",
    "q.t20#5.o3" to "A screwdriver set",
    "q.t20#5.e" to "The first three cover the three high-frequency failures: tent fabric, air chambers, and pack buckles. A screwdriver set is weight you will not use.",
    "q.t20#6.p" to "What is worth five minutes of checking each evening at camp?",
    "q.t20#6.o0" to "Sand and grit inside the boots",
    "q.t20#6.o1" to "Whether the socks are soaked",
    "q.t20#6.o2" to "Pack seams and buckles",
    "q.t20#6.o3" to "Trekking pole length",
    "q.t20#6.e" to "The first two decide the state of your feet, and the third decides whether a strap fails tomorrow. Pole length is adjustable any time and needs no daily check.",
    "q.t20#7.p" to "What is the right idea about gear reaching the end of its life?",
    "q.t20#7.o0" to "Judge by use intensity and visible wear, not by year of purchase",
    "q.t20#7.o1" to "New is always better",
    "q.t20#7.o2" to "Replace only when it breaks",
    "q.t20#7.o3" to "Older is more reliable",
    "q.t20#7.e" to "The same item lasts very differently depending on how often it is used. Look at wear (soles, buckles, coatings) rather than at the date.",
    "q.t21#0.p" to "What is the most reasonable attitude to night walking?",
    "q.t21#0.o0" to "Do not do it unless you have to; if you must, slow down and tighten formation management",
    "q.t21#0.o1" to "It is cooler at night, so it suits covering ground",
    "q.t21#0.o2" to "Night walking is safer",
    "q.t21#0.o3" to "A headlamp is all you need",
    "q.t21#0.e" to "Terrain judgement and navigation become several times harder at night, and accident rates rise. Night walking is a last resort, not a strategy.",
    "q.t21#1.p" to "What is the correct lighting setup for night walking?",
    "q.t21#1.o0" to "Headlamp plus spare batteries plus a backup light (small torch or second headlamp)",
    "q.t21#1.o1" to "Phone flash only",
    "q.t21#1.o2" to "Headlamp only",
    "q.t21#1.o3" to "Candles",
    "q.t21#1.e" to "Losing your light at night means losing the ability to move. A backup light is redundancy, for the same reason rope systems have it.",
    "q.t21#2.p" to "How should spacing be managed at night?",
    "q.t21#2.o0" to "Close up, with the lead group checking on the rear often and someone posted at junctions",
    "q.t21#2.o1" to "Spread out and walk alone",
    "q.t21#2.o2" to "Let fitness decide the spacing",
    "q.t21#2.o3" to "The rear finds its own way",
    "q.t21#2.e" to "At night the field of view is narrow and a dropped member is hard to spot. Posting someone at a junction is the cheapest insurance there is.",
    "q.t21#3.p" to "Which is NOT an early sign of an approaching thunderstorm?",
    "q.t21#3.o0" to "Temperature gradually rising",
    "q.t21#3.o1" to "Cumulus building rapidly in height",
    "q.t21#3.o2" to "Distant rumbling thunder",
    "q.t21#3.o3" to "Hair standing up and skin tingling",
    "q.t21#3.e" to "Temperature usually falls as a storm arrives. Hair standing up signals charge building, and you should leave high ground immediately.",
    "q.t21#4.p" to "What should you do if a thunderstorm catches you in the mountains?",
    "q.t21#4.o0" to "Get down to lower ground quickly, away from ridges, water, and isolated trees",
    "q.t21#4.o1" to "Shelter under a big rock on the summit",
    "q.t21#4.o2" to "Stand under a tree",
    "q.t21#4.o3" to "Keep pressing on",
    "q.t21#4.e" to "High points, water, isolated trees, and metal are all preferred paths for lightning. Losing height and spreading out is the only effective measure.",
    "q.t21#5.p" to "What is the correct posture when sheltering from lightning?",
    "q.t21#5.o0" to "Crouch spread apart with feet together; do not lie down",
    "q.t21#5.o1" to "Lie on the ground",
    "q.t21#5.o2" to "Stand upright",
    "q.t21#5.o3" to "Hug a tree",
    "q.t21#5.e" to "Feet together reduces step voltage; lying down increases contact area with the ground and is more dangerous.",
    "q.t21#6.p" to "What else must be guarded against during a thunderstorm?",
    "q.t21#6.o0" to "Hypothermia from a sharp temperature drop",
    "q.t21#6.o1" to "Flash floods from heavy rain",
    "q.t21#6.o2" to "Getting lost when visibility collapses",
    "q.t21#6.o3" to "UV burns",
    "q.t21#6.e" to "Storms usually bring cooling, heavy rain, and fog. It is a bundle of risks, not a single one.",
    "q.t21#7.p" to "What does leaving your itinerary with a home contact do in a night-walking or thunderstorm scenario?",
    "q.t21#7.o0" to "It lets the outside world start a search promptly when the team is overdue",
    "q.t21#7.o1" to "It is polite",
    "q.t21#7.o2" to "It helps with insurance claims",
    "q.t21#7.o3" to "Nothing",
    "q.t21#7.e" to "Night and bad weather leave the least margin for error. An itinerary is the precondition for someone coming to look for you if things go wrong.",
)
